values ($school967_nature$[{"slug":"solar-system","course":{"title":"المجموعة الشمسية","description":"رحلة عملية إلى الشمس والكواكب والمدارات والفصول والأطوار والجاذبية، تتضمن مختبرات علمية تفاعلية.","category":"الفلك والطبيعة"},"stages":[{"index":0,"stage":{"title":"الشمس: قلب المجموعة الشمسية","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 1 ندرس الشمس: قلب المجموعة الشمسية. الشمس نجم يتكون أساسًا من الهيدروجين والهيليوم؛ تنتج طاقتها في اللب باندماج الهيدروجين في الهيليوم. ينتقل الضوء عبر طبقات داخلية حتى يصل إلى الغلاف الشمسي ثم إلى الأرض خلال نحو 8 دقائق و20 ثانية.","tips":["الشمس نجم يتكون أساسًا من الهيدروجين والهيليوم؛ تنتج طاقتها في اللب باندماج الهيدروجين في الهيليوم. ينتقل الضوء عبر طبقات داخلية حتى يصل إلى الغلاف الشمسي ثم إلى الأرض خلال نحو 8 دقائق و20 ثانية.","في النموذج اختر الأرض ثم الشمس مرجعًا: الشمس أكبر من الأرض بنحو 109 مرات في القطر. هذه مقارنة للحجم، وليست مقارنة للمسافة؛ لأن مقياس المسافات مختلف تمامًا عن مقياس الكواكب.","لا تخلط بين الشمس والكوكب، ولا بين التفاعلات النووية والاحتراق الكيميائي. لا تنظر إلى الشمس مباشرة أو عبر عدسات غير مخصصة للرصد الشمسي."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"الشمس نجم يتكون أساسًا من الهيدروجين والهيليوم؛ تنتج طاقتها في اللب باندماج الهيدروجين في الهيليوم. ينتقل الضوء عبر طبقات داخلية حتى يصل إلى الغلاف الشمسي ثم إلى الأرض خلال نحو 8 دقائق و20 ثانية. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"في اللب","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"في النموذج اختر الأرض ثم الشمس مرجعًا: الشمس أكبر من الأرض بنحو 109 مرات في القطر. هذه مقارنة للحجم، وليست مقارنة للمسافة؛ لأن مقياس المسافات مختلف تمامًا عن مقياس الكواكب. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"اعرف مصدر الطاقة ← قارن الشمس بالأرض ← راجع وصول الضوء","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"يحدث اندماج الهيدروجين في اللب الشمسي حيث الحرارة والضغط مرتفعان. الشمس نجم يشع الطاقة، وليست كوكبًا يدور حول الشمس. يبعد متوسط الأرض عن الشمس نحو 150 مليون كم، ويحتاج الضوء قرابة 8 دقائق و20 ثانية. الاندماج في قلب الشمس يحوّل الهيدروجين إلى الهيليوم في صافي التفاعل. لا تخلط بين الشمس والكوكب، ولا بين التفاعلات النووية والاحتراق الكيميائي. لا تنظر إلى الشمس مباشرة أو عبر عدسات غير مخصصة للرصد الشمسي. خطوات التحليل الصحيحة: اعرف مصدر الطاقة ← قارن الشمس بالأرض ← راجع وصول الضوء. مصطلح التذكر هو نجم.","example":"نجم","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-sun","scenario":"الشمس: قلب المجموعة الشمسية"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"أين يحدث الاندماج الذي يغذي الشمس؟","target":"","options":["في الغلاف الأرضي","على القمر","داخل المشتري","في اللب"],"answerIndex":3,"explanation":"يحدث اندماج الهيدروجين في اللب الشمسي حيث الحرارة والضغط مرتفعان."},{"number":1,"kind":"choice","prompt":"أي وصف أدق للشمس؟","target":"","options":["قمر","مذنب","نجم","كوكب صخري"],"answerIndex":2,"explanation":"الشمس نجم يشع الطاقة، وليست كوكبًا يدور حول الشمس."},{"number":2,"kind":"choice","prompt":"كم يستغرق ضوء الشمس للوصول إلى الأرض تقريبًا؟","target":"","options":["سنة","8 دقائق و20 ثانية","ثانية واحدة","يوم كامل"],"answerIndex":1,"explanation":"يبعد متوسط الأرض عن الشمس نحو 150 مليون كم، ويحتاج الضوء قرابة 8 دقائق و20 ثانية."},{"number":3,"kind":"choice","prompt":"ماذا تندمج نوى الهيدروجين لتكوّن في الشمس؟","target":"","options":["الهيليوم","الحديد","النيون فقط","الكربون الصلب"],"answerIndex":0,"explanation":"الاندماج في قلب الشمس يحوّل الهيدروجين إلى الهيليوم في صافي التفاعل."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الشمس: قلب المجموعة الشمسية» في هذا التمرين.","target":"","tokens":["راجع وصول الضوء","قارن الشمس بالأرض","اعرف مصدر الطاقة"],"answer":["اعرف مصدر الطاقة","قارن الشمس بالأرض","راجع وصول الضوء"],"explanation":"الترتيب الصحيح وفق الدرس: اعرف مصدر الطاقة ← قارن الشمس بالأرض ← راجع وصول الضوء."},{"number":5,"kind":"type","prompt":"ما الاسم العلمي للجسم الذي تنتمي إليه الشمس؟","target":"","answer":"نجم","explanation":"الشمس نجم يتكون أساسًا من الهيدروجين والهيليوم؛ تنتج طاقتها في اللب باندماج الهيدروجين في الهيليوم. ينتقل الضوء عبر طبقات داخلية حتى يصل إلى الغلاف الشمسي ثم إلى الأرض خلال نحو 8 دقائق و20 ثانية."}]},{"index":1,"stage":{"title":"أحجام الكواكب ومسافاتها","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 2 ندرس أحجام الكواكب ومسافاتها. توجد ثمانية كواكب معترف بها في المجموعة الشمسية. ترتيبها من الداخل هو عطارد والزهرة والأرض والمريخ والمشتري وزحل وأورانوس ونبتون. تمثل الوحدة الفلكية AU متوسط المسافة بين الأرض والشمس تقريبًا.","tips":["توجد ثمانية كواكب معترف بها في المجموعة الشمسية. ترتيبها من الداخل هو عطارد والزهرة والأرض والمريخ والمشتري وزحل وأورانوس ونبتون. تمثل الوحدة الفلكية AU متوسط المسافة بين الأرض والشمس تقريبًا.","قطر المشتري يقارب 11 مرة قطر الأرض، لكن بعد نبتون عن الشمس يقارب 30 وحدة فلكية؛ لا يمكن جمع الحجم والمسافة في رسم مقياسي عادي من دون أن تختفي أحجام الكواكب تقريبًا.","تُظهر معظم الملصقات الكواكب كبيرة ومتقاربة لتسهيل رؤيتها؛ هذه رسوم توضيحية وليست تصويرًا دقيقًا للمقياس. غيّر مقياس «القطر» و«المسافة» كلًّا على حدة."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"توجد ثمانية كواكب معترف بها في المجموعة الشمسية. ترتيبها من الداخل هو عطارد والزهرة والأرض والمريخ والمشتري وزحل وأورانوس ونبتون. تمثل الوحدة الفلكية AU متوسط المسافة بين الأرض والشمس تقريبًا. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"ثمانية","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"قطر المشتري يقارب 11 مرة قطر الأرض، لكن بعد نبتون عن الشمس يقارب 30 وحدة فلكية؛ لا يمكن جمع الحجم والمسافة في رسم مقياسي عادي من دون أن تختفي أحجام الكواكب تقريبًا. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد الكوكب ← اختر نوع المقياس ← اقرأ المقارنة","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"المجموعة الشمسية تضم ثمانية كواكب، مع تصنيف بلوتو ككوكب قزم. الوحدة الفلكية تساوي نحو 149.6 مليون كيلومتر. نبتون هو الكوكب الثامن الأبعد عن الشمس. قطر المشتري حوالي 11 ضعف قطر الأرض. تُظهر معظم الملصقات الكواكب كبيرة ومتقاربة لتسهيل رؤيتها؛ هذه رسوم توضيحية وليست تصويرًا دقيقًا للمقياس. غيّر مقياس «القطر» و«المسافة» كلًّا على حدة. خطوات التحليل الصحيحة: حدد الكوكب ← اختر نوع المقياس ← اقرأ المقارنة. مصطلح التذكر هو AU.","example":"AU","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-scale","scenario":"أحجام الكواكب ومسافاتها"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"كم كوكبًا في المجموعة الشمسية حسب التصنيف المعتمد؟","target":"","options":["سبعة","اثنا عشر","ثمانية","تسعة"],"answerIndex":2,"explanation":"المجموعة الشمسية تضم ثمانية كواكب، مع تصنيف بلوتو ككوكب قزم."},{"number":1,"kind":"choice","prompt":"ما الذي تقيسه الوحدة الفلكية AU؟","target":"","options":["طول اليوم الأرضي","المسافة بين الأرض والشمس تقريبًا","قطر الشمس","كتلة المريخ"],"answerIndex":1,"explanation":"الوحدة الفلكية تساوي نحو 149.6 مليون كيلومتر."},{"number":2,"kind":"choice","prompt":"أي كوكب أبعد عن الشمس من البقية؟","target":"","options":["نبتون","الأرض","عطارد","الزهرة"],"answerIndex":0,"explanation":"نبتون هو الكوكب الثامن الأبعد عن الشمس."},{"number":3,"kind":"choice","prompt":"كم يساوي قطر المشتري مقارنة بقطر الأرض تقريبًا؟","target":"","options":["مرتين","100 مرة","نصف قطر الأرض","11 مرة"],"answerIndex":3,"explanation":"قطر المشتري حوالي 11 ضعف قطر الأرض."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «أحجام الكواكب ومسافاتها» في هذا التمرين.","target":"","tokens":["اقرأ المقارنة","اختر نوع المقياس","حدد الكوكب"],"answer":["حدد الكوكب","اختر نوع المقياس","اقرأ المقارنة"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الكوكب ← اختر نوع المقياس ← اقرأ المقارنة."},{"number":5,"kind":"type","prompt":"ما الوحدة المستخدمة للمسافات بين الكواكب والشمس؟","target":"","answer":"AU","explanation":"توجد ثمانية كواكب معترف بها في المجموعة الشمسية. ترتيبها من الداخل هو عطارد والزهرة والأرض والمريخ والمشتري وزحل وأورانوس ونبتون. تمثل الوحدة الفلكية AU متوسط المسافة بين الأرض والشمس تقريبًا."}]},{"index":2,"stage":{"title":"الكواكب الصخرية الأربعة","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 3 ندرس الكواكب الصخرية الأربعة. عطارد والزهرة والأرض والمريخ كواكب داخلية صخرية ذات سطوح صلبة. عطارد أقربها إلى الشمس، والزهرة غلافه الجوي كثيف جدًا وغني بثاني أكسيد الكربون، والمريخ ذو غلاف رقيق نسبيًا.","tips":["عطارد والزهرة والأرض والمريخ كواكب داخلية صخرية ذات سطوح صلبة. عطارد أقربها إلى الشمس، والزهرة غلافه الجوي كثيف جدًا وغني بثاني أكسيد الكربون، والمريخ ذو غلاف رقيق نسبيًا.","قارن قطر الأرض بالمريخ عبر المحاكاة: قطر المريخ يقارب 53% من قطر الأرض. مع ذلك، لا يمكن استنتاج درجة حرارة سطح كوكب من المسافة وحدها؛ فالزهرة أشد حرارة من عطارد بسبب تأثير الاحتباس الشديد.","أقرب كوكب ليس بالضرورة الأعلى حرارة. لا تخلط بين غلاف الأرض الذي يدعم الماء السائل على سطحها والغلاف الكثيف لزهرة يسبب احتباسًا حراريًا شديدًا."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"عطارد والزهرة والأرض والمريخ كواكب داخلية صخرية ذات سطوح صلبة. عطارد أقربها إلى الشمس، والزهرة غلافه الجوي كثيف جدًا وغني بثاني أكسيد الكربون، والمريخ ذو غلاف رقيق نسبيًا. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"أربعة","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"قارن قطر الأرض بالمريخ عبر المحاكاة: قطر المريخ يقارب 53% من قطر الأرض. مع ذلك، لا يمكن استنتاج درجة حرارة سطح كوكب من المسافة وحدها؛ فالزهرة أشد حرارة من عطارد بسبب تأثير الاحتباس الشديد. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"قارن الكواكب ← حدد تركيب السطح ← افحص الغلاف الجوي","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"الكواكب الداخلية الصخرية هي عطارد والزهرة والأرض والمريخ. عطارد هو الكوكب الأول في الترتيب من الشمس. غلاف الزهرة الكثيف واحتباسه الحراري الشديد يجعلان سطحه أشد حرارة من عطارد. قطر المريخ حوالي نصف قطر الأرض. أقرب كوكب ليس بالضرورة الأعلى حرارة. لا تخلط بين غلاف الأرض الذي يدعم الماء السائل على سطحها والغلاف الكثيف لزهرة يسبب احتباسًا حراريًا شديدًا. خطوات التحليل الصحيحة: قارن الكواكب ← حدد تركيب السطح ← افحص الغلاف الجوي. مصطلح التذكر هو الزهرة.","example":"الزهرة","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-scale","scenario":"الكواكب الصخرية الأربعة"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"كم عدد الكواكب الصخرية الداخلية؟","target":"","options":["ثمانية","أربعة","اثنان","ستة"],"answerIndex":1,"explanation":"الكواكب الداخلية الصخرية هي عطارد والزهرة والأرض والمريخ."},{"number":1,"kind":"choice","prompt":"أي الكواكب أقرب إلى الشمس؟","target":"","options":["عطارد","الزهرة","الأرض","المريخ"],"answerIndex":0,"explanation":"عطارد هو الكوكب الأول في الترتيب من الشمس."},{"number":2,"kind":"choice","prompt":"أي الكواكب الصخرية أشد حرارة في المتوسط؟","target":"","options":["عطارد","المريخ","الأرض","الزهرة"],"answerIndex":3,"explanation":"غلاف الزهرة الكثيف واحتباسه الحراري الشديد يجعلان سطحه أشد حرارة من عطارد."},{"number":3,"kind":"choice","prompt":"لماذا يظهر المريخ أصغر من الأرض في المقارنة؟","target":"","options":["لأنه قمر","لأنه بلا جاذبية","قطره أقل من قطر الأرض","لأنه أبعد عن الشمس دائمًا"],"answerIndex":2,"explanation":"قطر المريخ حوالي نصف قطر الأرض."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الكواكب الصخرية الأربعة» في هذا التمرين.","target":"","tokens":["افحص الغلاف الجوي","حدد تركيب السطح","قارن الكواكب"],"answer":["قارن الكواكب","حدد تركيب السطح","افحص الغلاف الجوي"],"explanation":"الترتيب الصحيح وفق الدرس: قارن الكواكب ← حدد تركيب السطح ← افحص الغلاف الجوي."},{"number":5,"kind":"type","prompt":"ما الكوكب الشهير بالاحتباس الحراري الشديد؟","target":"","answer":"الزهرة","explanation":"عطارد والزهرة والأرض والمريخ كواكب داخلية صخرية ذات سطوح صلبة. عطارد أقربها إلى الشمس، والزهرة غلافه الجوي كثيف جدًا وغني بثاني أكسيد الكربون، والمريخ ذو غلاف رقيق نسبيًا."}]},{"index":3,"stage":{"title":"العمالقة الغازية والجليدية","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 4 ندرس العمالقة الغازية والجليدية. المشتري وزحل عملاقان غازيان تهيمن عليهما مادتا الهيدروجين والهيليوم، بينما أورانوس ونبتون يصنفان عملاقين جليديين لوفرة مواد ثقيلة نسبيًا في داخلهما. للكواكب العملاقة أنظمة حلقات وأقمار، مع اختلاف واضح في بنيتها.","tips":["المشتري وزحل عملاقان غازيان تهيمن عليهما مادتا الهيدروجين والهيليوم، بينما أورانوس ونبتون يصنفان عملاقين جليديين لوفرة مواد ثقيلة نسبيًا في داخلهما. للكواكب العملاقة أنظمة حلقات وأقمار، مع اختلاف واضح في بنيتها.","في وضع الأحجام سترى أن المشتري أكبر الكواكب قطرًا، بينما نبتون أصغر منه بكثير لكنه أبعد عن الشمس. وجود حلقات ليس خاصًا بزحل وحده؛ للكواكب العملاقة الأخرى حلقات أيضًا.","لا تعرض «العمالقة الجليدية» كأنها كرات جليد صلب؛ الاسم يشير إلى تركيب داخلي معقد. ولا تفترض أن للمشتري سطحًا صلبًا واضحًا كالأرض."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"المشتري وزحل عملاقان غازيان تهيمن عليهما مادتا الهيدروجين والهيليوم، بينما أورانوس ونبتون يصنفان عملاقين جليديين لوفرة مواد ثقيلة نسبيًا في داخلهما. للكواكب العملاقة أنظمة حلقات وأقمار، مع اختلاف واضح في بنيتها. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"المشتري","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"في وضع الأحجام سترى أن المشتري أكبر الكواكب قطرًا، بينما نبتون أصغر منه بكثير لكنه أبعد عن الشمس. وجود حلقات ليس خاصًا بزحل وحده؛ للكواكب العملاقة الأخرى حلقات أيضًا. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"ميز نوع العملاق ← قارن القطر ← راجع التركيب","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"المشتري أكبر الكواكب قطرًا وحجمًا في المجموعة الشمسية. أورانوس ونبتون هما العملاقان الجليديان. للمشتري وزحل وأورانوس ونبتون أنظمة حلقات. يهيمن الهيدروجين والهيليوم على تركيب العملاقين الغازيين. لا تعرض «العمالقة الجليدية» كأنها كرات جليد صلب؛ الاسم يشير إلى تركيب داخلي معقد. ولا تفترض أن للمشتري سطحًا صلبًا واضحًا كالأرض. خطوات التحليل الصحيحة: ميز نوع العملاق ← قارن القطر ← راجع التركيب. مصطلح التذكر هو المشتري.","example":"المشتري","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-scale","scenario":"العمالقة الغازية والجليدية"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما أكبر كواكب النظام الشمسي؟","target":"","options":["المشتري","زحل","نبتون","الأرض"],"answerIndex":0,"explanation":"المشتري أكبر الكواكب قطرًا وحجمًا في المجموعة الشمسية."},{"number":1,"kind":"choice","prompt":"أي زوج يُصنف عملاقين جليديين؟","target":"","options":["عطارد والزهرة","الأرض والمريخ","المشتري وزحل","أورانوس ونبتون"],"answerIndex":3,"explanation":"أورانوس ونبتون هما العملاقان الجليديان."},{"number":2,"kind":"choice","prompt":"هل الحلقات مقتصرة على زحل؟","target":"","options":["لدى الأرض فقط","لدى عطارد فقط","لا، لدى العمالقة الأربعة حلقات","نعم"],"answerIndex":2,"explanation":"للمشتري وزحل وأورانوس ونبتون أنظمة حلقات."},{"number":3,"kind":"choice","prompt":"مما يتكون المشتري وزحل في الغالب؟","target":"","options":["هواء أرضي","الهيدروجين والهيليوم","صخور حديدية فقط","جليد ماء نقي"],"answerIndex":1,"explanation":"يهيمن الهيدروجين والهيليوم على تركيب العملاقين الغازيين."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «العمالقة الغازية والجليدية» في هذا التمرين.","target":"","tokens":["راجع التركيب","قارن القطر","ميز نوع العملاق"],"answer":["ميز نوع العملاق","قارن القطر","راجع التركيب"],"explanation":"الترتيب الصحيح وفق الدرس: ميز نوع العملاق ← قارن القطر ← راجع التركيب."},{"number":5,"kind":"type","prompt":"ما اسم الكوكب الأكبر في المجموعة الشمسية؟","target":"","answer":"المشتري","explanation":"المشتري وزحل عملاقان غازيان تهيمن عليهما مادتا الهيدروجين والهيليوم، بينما أورانوس ونبتون يصنفان عملاقين جليديين لوفرة مواد ثقيلة نسبيًا في داخلهما. للكواكب العملاقة أنظمة حلقات وأقمار، مع اختلاف واضح في بنيتها."}]},{"index":4,"stage":{"title":"حركة الكواكب والمدارات","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 5 ندرس حركة الكواكب والمدارات. تتحرك الكواكب حول الشمس في مدارات إهليلجية (بيضاوية) والشمس تقع في إحدى البؤرتين. بحسب قانون كبلر الثالث، وبالسنوات والوحدات الفلكية تقريبًا حول الشمس، مربع الفترة المدارية يتناسب مع مكعب نصف المحور الأكبر.","tips":["تتحرك الكواكب حول الشمس في مدارات إهليلجية (بيضاوية) والشمس تقع في إحدى البؤرتين. بحسب قانون كبلر الثالث، وبالسنوات والوحدات الفلكية تقريبًا حول الشمس، مربع الفترة المدارية يتناسب مع مكعب نصف المحور الأكبر.","عند نصف محور أكبر يساوي 1 AU تكون السنة سنة أرضية تقريبًا. وعند 4 AU تكون الفترة المدارية 8 سنوات، لأن الجذر التربيعي لـ4³ يساوي 8.","المحاكاة ثنائية الأبعاد مبسطة وتفترض أن الكتلة الشمسية هي المسيطرة. الأجسام ذات اللامركزية العالية تتغير سرعتها على طول المدار ولا تتحرك بسرعة زاوية ثابتة."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"تتحرك الكواكب حول الشمس في مدارات إهليلجية (بيضاوية) والشمس تقع في إحدى البؤرتين. بحسب قانون كبلر الثالث، وبالسنوات والوحدات الفلكية تقريبًا حول الشمس، مربع الفترة المدارية يتناسب مع مكعب نصف المحور الأكبر. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"إهليلجية","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"عند نصف محور أكبر يساوي 1 AU تكون السنة سنة أرضية تقريبًا. وعند 4 AU تكون الفترة المدارية 8 سنوات، لأن الجذر التربيعي لـ4³ يساوي 8. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد نصف المحور ← استخدم علاقة كبلر ← احسب الزمن المداري","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"تنص قوانين كبلر على أن مدارات الكواكب إهليلجية تقريبًا. الفترة بالسنوات تساوي تقريبًا جذر مكعب نصف المحور الأكبر بوحدة AU. تقع الشمس في إحدى بؤرتي المدار الإهليلجي. نصف المحور الأكبر للأرض قريب من وحدة فلكية واحدة. المحاكاة ثنائية الأبعاد مبسطة وتفترض أن الكتلة الشمسية هي المسيطرة. الأجسام ذات اللامركزية العالية تتغير سرعتها على طول المدار ولا تتحرك بسرعة زاوية ثابتة. خطوات التحليل الصحيحة: حدد نصف المحور ← استخدم علاقة كبلر ← احسب الزمن المداري. مصطلح التذكر هو إهليلج.","example":"إهليلج","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-orbit","scenario":"حركة الكواكب والمدارات"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما الشكل العام لمدارات الكواكب؟","target":"","options":["مربعة","مثلثية","خطوط مستقيمة","إهليلجية"],"answerIndex":3,"explanation":"تنص قوانين كبلر على أن مدارات الكواكب إهليلجية تقريبًا."},{"number":1,"kind":"choice","prompt":"عند 4 AU كم تستغرق السنة وفق تقريب كبلر؟","target":"","options":["16 سنة","سنة واحدة","8 سنوات","4 سنوات"],"answerIndex":2,"explanation":"الفترة بالسنوات تساوي تقريبًا جذر مكعب نصف المحور الأكبر بوحدة AU."},{"number":2,"kind":"choice","prompt":"في أي موضع تقع الشمس في مدار كبلر؟","target":"","options":["النقطة الأبعد دائمًا","إحدى بؤرتي القطع الناقص","المركز الهندسي دائمًا","خارج المدار"],"answerIndex":1,"explanation":"تقع الشمس في إحدى بؤرتي المدار الإهليلجي."},{"number":3,"kind":"choice","prompt":"أي قيمة تمثل نصف المحور الأكبر لمدار الأرض تقريبًا؟","target":"","options":["1 AU","30 AU","0 AU","100 AU"],"answerIndex":0,"explanation":"نصف المحور الأكبر للأرض قريب من وحدة فلكية واحدة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «حركة الكواكب والمدارات» في هذا التمرين.","target":"","tokens":["احسب الزمن المداري","استخدم علاقة كبلر","حدد نصف المحور"],"answer":["حدد نصف المحور","استخدم علاقة كبلر","احسب الزمن المداري"],"explanation":"الترتيب الصحيح وفق الدرس: حدد نصف المحور ← استخدم علاقة كبلر ← احسب الزمن المداري."},{"number":5,"kind":"type","prompt":"ما اسم شكل مدار الكوكب غير الدائري عمومًا؟","target":"","answer":"إهليلج","explanation":"تتحرك الكواكب حول الشمس في مدارات إهليلجية (بيضاوية) والشمس تقع في إحدى البؤرتين. بحسب قانون كبلر الثالث، وبالسنوات والوحدات الفلكية تقريبًا حول الشمس، مربع الفترة المدارية يتناسب مع مكعب نصف المحور الأكبر."}]},{"index":5,"stage":{"title":"الأيام والسنوات على الكواكب","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 6 ندرس الأيام والسنوات على الكواكب. السنة هي زمن إكمال دورة حول الشمس، واليوم قد يعني دورة محورية نجمية أو الفترة بين شروقين شمسيين، وهما ليسا متماثلين دائمًا. تختلف مدارات الكواكب وسرعات دورانها؛ فلا يعني طول السنة طول اليوم.","tips":["السنة هي زمن إكمال دورة حول الشمس، واليوم قد يعني دورة محورية نجمية أو الفترة بين شروقين شمسيين، وهما ليسا متماثلين دائمًا. تختلف مدارات الكواكب وسرعات دورانها؛ فلا يعني طول السنة طول اليوم.","الأرض تتم دورة حول الشمس في نحو 365.25 يومًا، والمريخ نحو 687 يومًا أرضيًا. تغيّر نصف المحور في المختبر يغيّر الفترة المدارية وفق قانون كبلر، لكنه لا يحدد سرعة دوران الكوكب حول محوره.","لا تستخدم خانة «فترة المدار» لتستنتج طول اليوم، فالمدار والدوران عمليتان مستقلتان. كما أن «اليوم» يحتاج تعريفًا عند المقارنة بين الكواكب."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"السنة هي زمن إكمال دورة حول الشمس، واليوم قد يعني دورة محورية نجمية أو الفترة بين شروقين شمسيين، وهما ليسا متماثلين دائمًا. تختلف مدارات الكواكب وسرعات دورانها؛ فلا يعني طول السنة طول اليوم. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"إكمال دورة حول الشمس","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"الأرض تتم دورة حول الشمس في نحو 365.25 يومًا، والمريخ نحو 687 يومًا أرضيًا. تغيّر نصف المحور في المختبر يغيّر الفترة المدارية وفق قانون كبلر، لكنه لا يحدد سرعة دوران الكوكب حول محوره. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"ميز الدوران ← ميز المدار ← قارن الزمنين","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"سنة الكوكب هي فترة دورانه حول الشمس. سنة المريخ تبلغ تقريبًا 687 يومًا أرضيًا. الدوران المحوري والفترة المدارية مختلفان. اليوم النجمي يقيس العودة بالنسبة للنجوم، والشمسي بالنسبة للشمس. لا تستخدم خانة «فترة المدار» لتستنتج طول اليوم، فالمدار والدوران عمليتان مستقلتان. كما أن «اليوم» يحتاج تعريفًا عند المقارنة بين الكواكب. خطوات التحليل الصحيحة: ميز الدوران ← ميز المدار ← قارن الزمنين. مصطلح التذكر هو المدار.","example":"المدار","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-orbit","scenario":"الأيام والسنوات على الكواكب"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما المقصود بالسنة الكوكبية؟","target":"","options":["دقيقة ضوئية","وقت دوران القمر فقط","إكمال دورة حول الشمس","دورة حول المحور"],"answerIndex":2,"explanation":"سنة الكوكب هي فترة دورانه حول الشمس."},{"number":1,"kind":"choice","prompt":"كم تبلغ سنة المريخ تقريبًا بالأيام الأرضية؟","target":"","options":["365 يومًا","687 يومًا","24 يومًا","88 يومًا"],"answerIndex":1,"explanation":"سنة المريخ تبلغ تقريبًا 687 يومًا أرضيًا."},{"number":2,"kind":"choice","prompt":"هل طول السنة يحدد طول اليوم تلقائيًا؟","target":"","options":["لا","نعم دائمًا","فقط على المريخ","إذا كان للكوكب قمر"],"answerIndex":0,"explanation":"الدوران المحوري والفترة المدارية مختلفان."},{"number":3,"kind":"choice","prompt":"بماذا يختلف اليوم النجمي عن اليوم الشمسي؟","target":"","options":["المسافة إلى الشمس وحدها","الكتلة فقط","عدد الأقمار","المرجع المستخدم في القياس"],"answerIndex":3,"explanation":"اليوم النجمي يقيس العودة بالنسبة للنجوم، والشمسي بالنسبة للشمس."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الأيام والسنوات على الكواكب» في هذا التمرين.","target":"","tokens":["قارن الزمنين","ميز المدار","ميز الدوران"],"answer":["ميز الدوران","ميز المدار","قارن الزمنين"],"explanation":"الترتيب الصحيح وفق الدرس: ميز الدوران ← ميز المدار ← قارن الزمنين."},{"number":5,"kind":"type","prompt":"ما العملية التي تحدد طول السنة؟","target":"","answer":"المدار","explanation":"السنة هي زمن إكمال دورة حول الشمس، واليوم قد يعني دورة محورية نجمية أو الفترة بين شروقين شمسيين، وهما ليسا متماثلين دائمًا. تختلف مدارات الكواكب وسرعات دورانها؛ فلا يعني طول السنة طول اليوم."}]},{"index":6,"stage":{"title":"الفصول الأربعة وميل المحور","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 7 ندرس الفصول الأربعة وميل المحور. تنشأ الفصول على الأرض أساسًا بسبب ميل محور الدوران بنحو 23.4 درجة بالنسبة إلى العمود على مستوى مدارها، مما يغيّر زاوية ضوء الشمس وطول النهار خلال السنة. فصل الصيف في نصف الكرة الشمالي يقابله الشتاء في الجنوبي.","tips":["تنشأ الفصول على الأرض أساسًا بسبب ميل محور الدوران بنحو 23.4 درجة بالنسبة إلى العمود على مستوى مدارها، مما يغيّر زاوية ضوء الشمس وطول النهار خلال السنة. فصل الصيف في نصف الكرة الشمالي يقابله الشتاء في الجنوبي.","عندما يميل القطب الشمالي نحو الشمس يطول النهار وتزداد زاوية الأشعة في مناطق شمالية؛ وعندما يميل بعيدًا يحدث العكس. جرب تغيير الميل في المختبر عند خط عرض 35° شمالًا.","القرب من الشمس ليس السبب الرئيسي لفصول الأرض. لا تعمم طول النهار المحسوب عند خط عرض 35° على خط الاستواء أو القطبين؛ إنه نموذج لخط عرض محدد."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"تنشأ الفصول على الأرض أساسًا بسبب ميل محور الدوران بنحو 23.4 درجة بالنسبة إلى العمود على مستوى مدارها، مما يغيّر زاوية ضوء الشمس وطول النهار خلال السنة. فصل الصيف في نصف الكرة الشمالي يقابله الشتاء في الجنوبي. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"ميل محور الأرض أثناء دورانها حول الشمس","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"عندما يميل القطب الشمالي نحو الشمس يطول النهار وتزداد زاوية الأشعة في مناطق شمالية؛ وعندما يميل بعيدًا يحدث العكس. جرب تغيير الميل في المختبر عند خط عرض 35° شمالًا. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد ميل المحور ← حدد وقت السنة ← قارن طول النهار","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"يغيّر ميل المحور زاوية الإضاءة وطول النهار. ميل محور الأرض نحو 23.4° عن العمود على مستوى المدار. الفصول متعاكسة بين نصفي الكرة. يتغير ارتفاع الشمس في السماء وطول الفترة النهارية. القرب من الشمس ليس السبب الرئيسي لفصول الأرض. لا تعمم طول النهار المحسوب عند خط عرض 35° على خط الاستواء أو القطبين؛ إنه نموذج لخط عرض محدد. خطوات التحليل الصحيحة: حدد ميل المحور ← حدد وقت السنة ← قارن طول النهار. مصطلح التذكر هو الميل.","example":"الميل","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-seasons","scenario":"الفصول الأربعة وميل المحور"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما السبب الرئيسي لفصول الأرض؟","target":"","options":["اقتراب القمر","ميل محور الأرض أثناء دورانها حول الشمس","تغير المسافة وحده","تغير حجم الشمس"],"answerIndex":1,"explanation":"يغيّر ميل المحور زاوية الإضاءة وطول النهار."},{"number":1,"kind":"choice","prompt":"كم يبلغ ميل محور الأرض تقريبًا؟","target":"","options":["23.4 درجة","90 درجة","0 درجة","60 درجة"],"answerIndex":0,"explanation":"ميل محور الأرض نحو 23.4° عن العمود على مستوى المدار."},{"number":2,"kind":"choice","prompt":"عندما يكون شمال الأرض صيفًا فماذا يكون جنوبها عمومًا؟","target":"","options":["صيف أيضًا","لا توجد فصول","ربيع دائمًا","شتاء"],"answerIndex":3,"explanation":"الفصول متعاكسة بين نصفي الكرة."},{"number":3,"kind":"choice","prompt":"ما العاملان اللذان يتغيران مع الفصول؟","target":"","options":["سرعة الضوء وكتلة الشمس","عدد الكواكب","زاوية الشمس وطول النهار","كتلة الأرض وقطرها"],"answerIndex":2,"explanation":"يتغير ارتفاع الشمس في السماء وطول الفترة النهارية."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الفصول الأربعة وميل المحور» في هذا التمرين.","target":"","tokens":["قارن طول النهار","حدد وقت السنة","حدد ميل المحور"],"answer":["حدد ميل المحور","حدد وقت السنة","قارن طول النهار"],"explanation":"الترتيب الصحيح وفق الدرس: حدد ميل المحور ← حدد وقت السنة ← قارن طول النهار."},{"number":5,"kind":"type","prompt":"ما العامل الأساسي المسبب للفصول؟","target":"","answer":"الميل","explanation":"تنشأ الفصول على الأرض أساسًا بسبب ميل محور الدوران بنحو 23.4 درجة بالنسبة إلى العمود على مستوى مدارها، مما يغيّر زاوية ضوء الشمس وطول النهار خلال السنة. فصل الصيف في نصف الكرة الشمالي يقابله الشتاء في الجنوبي."}]},{"index":7,"stage":{"title":"أطوار القمر","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 8 ندرس أطوار القمر. نرى أطوار القمر لأن الجزء المضاء من نصفه المواجه للشمس يتغير منظورنا إليه بينما يدور حول الأرض. لا تنشأ الأطوار العادية من سقوط ظل الأرض على القمر؛ ظل الأرض يتعلق بالخسوف فقط.","tips":["نرى أطوار القمر لأن الجزء المضاء من نصفه المواجه للشمس يتغير منظورنا إليه بينما يدور حول الأرض. لا تنشأ الأطوار العادية من سقوط ظل الأرض على القمر؛ ظل الأرض يتعلق بالخسوف فقط.","عند الاصطفاف المناسب يظهر المحاق عندما يكون القمر تقريبًا في اتجاه الشمس من الأرض، ويظهر البدر عندما يكون مقابلها. غيّر زاوية الموضع في المختبر ولاحظ نسبة الجزء المضاء المرئي.","الأطوار لا تعني أن ضوء القمر يطفأ ويتشعل؛ الشمس تضيء نصف القمر دائمًا تقريبًا، ونحن نرى أجزاء مختلفة منه. زاوية الرؤية مهمة."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"نرى أطوار القمر لأن الجزء المضاء من نصفه المواجه للشمس يتغير منظورنا إليه بينما يدور حول الأرض. لا تنشأ الأطوار العادية من سقوط ظل الأرض على القمر؛ ظل الأرض يتعلق بالخسوف فقط. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"تغيّر الجزء المضاء الذي نراه","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"عند الاصطفاف المناسب يظهر المحاق عندما يكون القمر تقريبًا في اتجاه الشمس من الأرض، ويظهر البدر عندما يكون مقابلها. غيّر زاوية الموضع في المختبر ولاحظ نسبة الجزء المضاء المرئي. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد موضع القمر ← لاحظ الوجه المضاء ← سم الطور","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"الأطوار نتيجة تغير زاوية رؤية النصف المضاء. يظهر البدر عندما نرى معظم نصف القمر المضاءة مواجهًا لنا. الظل الأرضي يخص الخسوف، لا الأطوار العادية. القمر يعكس ضوء الشمس ولا يصدر ضوءًا مرئيًا ذاتيًا مثل النجم. الأطوار لا تعني أن ضوء القمر يطفأ ويتشعل؛ الشمس تضيء نصف القمر دائمًا تقريبًا، ونحن نرى أجزاء مختلفة منه. زاوية الرؤية مهمة. خطوات التحليل الصحيحة: حدد موضع القمر ← لاحظ الوجه المضاء ← سم الطور. مصطلح التذكر هو البدر.","example":"البدر","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-moon","scenario":"أطوار القمر"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما سبب أطوار القمر؟","target":"","options":["تغيّر الجزء المضاء الذي نراه","ظل الأرض كل ليلة","انطفاء ضوء القمر","تغير حجم القمر"],"answerIndex":0,"explanation":"الأطوار نتيجة تغير زاوية رؤية النصف المضاء."},{"number":1,"kind":"choice","prompt":"متى يكون القمر بدرًا تقريبًا؟","target":"","options":["عند محاقه","عندما يكون بين الشمس والأرض","كل يوم ظهرًا","عندما يقابل الشمس في السماء"],"answerIndex":3,"explanation":"يظهر البدر عندما نرى معظم نصف القمر المضاءة مواجهًا لنا."},{"number":2,"kind":"choice","prompt":"هل ظل الأرض سبب الأطوار الشهرية؟","target":"","options":["فقط في الربيع","إذا كان القمر كبيرًا","لا","نعم"],"answerIndex":2,"explanation":"الظل الأرضي يخص الخسوف، لا الأطوار العادية."},{"number":3,"kind":"choice","prompt":"ماذا يضيء القمر؟","target":"","options":["النجوم القريبة فقط","ضوء الشمس","ضوء يصدره القمر ذاتيًا","الأرض وحدها"],"answerIndex":1,"explanation":"القمر يعكس ضوء الشمس ولا يصدر ضوءًا مرئيًا ذاتيًا مثل النجم."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «أطوار القمر» في هذا التمرين.","target":"","tokens":["سم الطور","لاحظ الوجه المضاء","حدد موضع القمر"],"answer":["حدد موضع القمر","لاحظ الوجه المضاء","سم الطور"],"explanation":"الترتيب الصحيح وفق الدرس: حدد موضع القمر ← لاحظ الوجه المضاء ← سم الطور."},{"number":5,"kind":"type","prompt":"ما اسم الطور عندما يبدو قرص القمر مضاء كاملًا تقريبًا؟","target":"","answer":"البدر","explanation":"نرى أطوار القمر لأن الجزء المضاء من نصفه المواجه للشمس يتغير منظورنا إليه بينما يدور حول الأرض. لا تنشأ الأطوار العادية من سقوط ظل الأرض على القمر؛ ظل الأرض يتعلق بالخسوف فقط."}]},{"index":8,"stage":{"title":"الكسوف والخسوف","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 9 ندرس الكسوف والخسوف. يحدث الكسوف الشمسي عندما يحجب القمر جزءًا من ضوء الشمس عن منطقة على الأرض قرب المحاق، والخسوف القمري عندما يقع القمر في ظل الأرض قرب البدر. يلزم اقتراب القمر من مستوى عقدة مداره عند الاصطفاف.","tips":["يحدث الكسوف الشمسي عندما يحجب القمر جزءًا من ضوء الشمس عن منطقة على الأرض قرب المحاق، والخسوف القمري عندما يقع القمر في ظل الأرض قرب البدر. يلزم اقتراب القمر من مستوى عقدة مداره عند الاصطفاف.","غيّر طور القمر وميل مداره في المحاكاة: لن يكفي المحاق وحده لكسوف كل شهر، لأن مدار القمر مائل نحو خمس درجات عن مستوى مدار الأرض حول الشمس.","هذه محاكاة هندسية مبسطة لا تتنبأ بموعد أو مكان كسوف حقيقي؛ يجب الاعتماد على حسابات فلكية موثوقة لذلك. لا تنظر للشمس مباشرة خلال الكسوف دون مرشح شمسي مخصص."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"يحدث الكسوف الشمسي عندما يحجب القمر جزءًا من ضوء الشمس عن منطقة على الأرض قرب المحاق، والخسوف القمري عندما يقع القمر في ظل الأرض قرب البدر. يلزم اقتراب القمر من مستوى عقدة مداره عند الاصطفاف. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"قرب المحاق مع اصطفاف مناسب","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"غيّر طور القمر وميل مداره في المحاكاة: لن يكفي المحاق وحده لكسوف كل شهر، لأن مدار القمر مائل نحو خمس درجات عن مستوى مدار الأرض حول الشمس. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد طور القمر ← تحقق من العقدة ← ميز نوع الحدث","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"  ميل مدار القمر يمنع الاصطفاف الصحيح في معظم الشهور. تستلزم المشاهدة المباشرة للشمس حماية بمرشحات معتمدة. هذه محاكاة هندسية مبسطة لا تتنبأ بموعد أو مكان كسوف حقيقي؛ يجب الاعتماد على حسابات فلكية موثوقة لذلك. لا تنظر للشمس مباشرة خلال الكسوف دون مرشح شمسي مخصص. خطوات التحليل الصحيحة: حدد طور القمر ← تحقق من العقدة ← ميز نوع الحدث. مصطلح التذكر هو الخسوف.","example":"الخسوف","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-moon","scenario":"الكسوف والخسوف"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"متى يمكن أن يحدث كسوف شمسي؟","target":"","options":["عند البدر فقط","في منتصف النهار كل يوم","عندما يبعد القمر عن مستوى العقدة","قرب المحاق مع اصطفاف مناسب"],"answerIndex":3,"explanation":"يحدث الكسوف الشمسي قرب المحاق إذا اقترب القمر من مستوى العقدة واصطف مع الشمس والأرض."},{"number":1,"kind":"choice","prompt":"متى يحدث الخسوف القمري؟","target":"","options":["كل ليلة","عند بداية السنة","قرب البدر","قرب المحاق فقط"],"answerIndex":2,"explanation":"يحدث الخسوف القمري قرب البدر عندما يعبر القمر ظل الأرض بالقرب من عقدة مداره."},{"number":2,"kind":"choice","prompt":"لماذا لا يوجد كسوف كل محاق؟","target":"","options":["لأن الشمس تنطفئ","لأن مدار القمر مائل","لأن القمر يتوقف","لأن الأرض مسطحة"],"answerIndex":1,"explanation":"ميل مدار القمر يمنع الاصطفاف الصحيح في معظم الشهور."},{"number":3,"kind":"choice","prompt":"ما الاحتياط الأساسي لرصد الكسوف الشمسي؟","target":"","options":["استخدام مرشح شمسي مخصص","النظر بعينين مجردتين","النظر بمنظار عادي","التحديق من خلف زجاج ملون"],"answerIndex":0,"explanation":"تستلزم المشاهدة المباشرة للشمس حماية بمرشحات معتمدة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الكسوف والخسوف» في هذا التمرين.","target":"","tokens":["ميز نوع الحدث","تحقق من العقدة","حدد طور القمر"],"answer":["حدد طور القمر","تحقق من العقدة","ميز نوع الحدث"],"explanation":"الترتيب الصحيح وفق الدرس: حدد طور القمر ← تحقق من العقدة ← ميز نوع الحدث."},{"number":5,"kind":"type","prompt":"ما الظاهرة التي يدخل فيها القمر ظل الأرض؟","target":"","answer":"الخسوف","explanation":"يحدث الكسوف الشمسي عندما يحجب القمر جزءًا من ضوء الشمس عن منطقة على الأرض قرب المحاق، والخسوف القمري عندما يقع القمر في ظل الأرض قرب البدر. يلزم اقتراب القمر من مستوى عقدة مداره عند الاصطفاف."}]},{"index":9,"stage":{"title":"الجاذبية والوزن","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 10 ندرس الجاذبية والوزن. الكتلة مقدار المادة ولا تتغير لمجرد انتقال جسم إلى كوكب آخر؛ أما الوزن فهو قوة الجاذبية على الكتلة، ويُقاس بالنيوتن. في نموذج قرب سطح كوكب: الوزن = الكتلة × تسارع الجاذبية.","tips":["الكتلة مقدار المادة ولا تتغير لمجرد انتقال جسم إلى كوكب آخر؛ أما الوزن فهو قوة الجاذبية على الكتلة، ويُقاس بالنيوتن. في نموذج قرب سطح كوكب: الوزن = الكتلة × تسارع الجاذبية.","كتلة شخص 60 كجم تبقى 60 كجم على الأرض والقمر؛ وزنه على الأرض يقارب 589 نيوتن وعلى القمر 97 نيوتن عند استعمال 9.81 و1.62 م/ث² على التوالي.","هذه تقديرات للجاذبية عند سطح متوسط؛ تختلف الجاذبية مع الارتفاع وبنية الكوكب، ولا تعني «كتلة أقل» على القمر. قيم العمالقة الغازية ليست سطحًا صلبًا للمشي."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"الكتلة مقدار المادة ولا تتغير لمجرد انتقال جسم إلى كوكب آخر؛ أما الوزن فهو قوة الجاذبية على الكتلة، ويُقاس بالنيوتن. في نموذج قرب سطح كوكب: الوزن = الكتلة × تسارع الجاذبية. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"نيوتن","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"كتلة شخص 60 كجم تبقى 60 كجم على الأرض والقمر؛ وزنه على الأرض يقارب 589 نيوتن وعلى القمر 97 نيوتن عند استعمال 9.81 و1.62 م/ث² على التوالي. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد الكتلة ← اختر الجرم ← احسب قوة الوزن","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"الوزن قوة لذا يقاس بالنيوتن. الكتلة مستقلة عن شدة الجاذبية المحلية. الوزن W=m g قرب سطح الجسم. جاذبية القمر نحو سدس جاذبية الأرض. هذه تقديرات للجاذبية عند سطح متوسط؛ تختلف الجاذبية مع الارتفاع وبنية الكوكب، ولا تعني «كتلة أقل» على القمر. قيم العمالقة الغازية ليست سطحًا صلبًا للمشي. خطوات التحليل الصحيحة: حدد الكتلة ← اختر الجرم ← احسب قوة الوزن. مصطلح التذكر هو نيوتن.","example":"نيوتن","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-gravity","scenario":"الجاذبية والوزن"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما الوحدة العلمية للوزن بوصفه قوة؟","target":"","options":["درجة مئوية","وحدة فلكية","نيوتن","كيلوغرام"],"answerIndex":2,"explanation":"الوزن قوة لذا يقاس بالنيوتن."},{"number":1,"kind":"choice","prompt":"ماذا يحدث لكتلة جسم على القمر؟","target":"","options":["تتضاعف","تبقى كما هي","تصبح سدسها","تختفي"],"answerIndex":1,"explanation":"الكتلة مستقلة عن شدة الجاذبية المحلية."},{"number":2,"kind":"choice","prompt":"ما العلاقة التقريبية للوزن؟","target":"","options":["الكتلة × تسارع الجاذبية","الكتلة ÷ الزمن","الضغط × المسافة","الحرارة × الارتفاع"],"answerIndex":0,"explanation":"الوزن W=m g قرب سطح الجسم."},{"number":3,"kind":"choice","prompt":"هل وزن جسم على القمر أقل من الأرض؟","target":"","options":["لا","الوزنان متساويان","ليس للقمر جاذبية","نعم"],"answerIndex":3,"explanation":"جاذبية القمر نحو سدس جاذبية الأرض."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الجاذبية والوزن» في هذا التمرين.","target":"","tokens":["احسب قوة الوزن","اختر الجرم","حدد الكتلة"],"answer":["حدد الكتلة","اختر الجرم","احسب قوة الوزن"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الكتلة ← اختر الجرم ← احسب قوة الوزن."},{"number":5,"kind":"type","prompt":"ما وحدة قياس قوة الوزن؟","target":"","answer":"نيوتن","explanation":"الكتلة مقدار المادة ولا تتغير لمجرد انتقال جسم إلى كوكب آخر؛ أما الوزن فهو قوة الجاذبية على الكتلة، ويُقاس بالنيوتن. في نموذج قرب سطح كوكب: الوزن = الكتلة × تسارع الجاذبية."}]},{"index":10,"stage":{"title":"الكويكبات والمذنبات والكواكب القزمة","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 11 ندرس الكويكبات والمذنبات والكواكب القزمة. الكويكبات أجسام صغيرة غالبًا صخرية، والمذنبات تحتوي مواد متطايرة وغبارًا قد تشكل ذؤابة وذيلًا عند التسخين قرب الشمس. الكوكب القزم يدور حول الشمس ويقارب الشكل الكروي لكنه لم ينظف جواره المداري.","tips":["الكويكبات أجسام صغيرة غالبًا صخرية، والمذنبات تحتوي مواد متطايرة وغبارًا قد تشكل ذؤابة وذيلًا عند التسخين قرب الشمس. الكوكب القزم يدور حول الشمس ويقارب الشكل الكروي لكنه لم ينظف جواره المداري.","بلوتو كوكب قزم وفق تصنيف الاتحاد الفلكي الدولي، وليس أحد الكواكب الثمانية. وبعض المذنبات لها مدارات عالية الاستطالة؛ غيّر الاختلاف المركزي ولاحظ تغير شكل المدار.","لا تجعل الذيل دائمًا خلف اتجاه حركة المذنب؛ يتأثر بالرياح الشمسية وضغط الإشعاع، فيتجه عمومًا بعيدًا عن الشمس. ولا تعتبر كل جسم في حزام الكويكبات مذنبًا."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"الكويكبات أجسام صغيرة غالبًا صخرية، والمذنبات تحتوي مواد متطايرة وغبارًا قد تشكل ذؤابة وذيلًا عند التسخين قرب الشمس. الكوكب القزم يدور حول الشمس ويقارب الشكل الكروي لكنه لم ينظف جواره المداري. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"كوكب قزم","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"بلوتو كوكب قزم وفق تصنيف الاتحاد الفلكي الدولي، وليس أحد الكواكب الثمانية. وبعض المذنبات لها مدارات عالية الاستطالة؛ غيّر الاختلاف المركزي ولاحظ تغير شكل المدار. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد نوع الجرم ← افحص المدار ← قارن خصائصه","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"بلوتو مصنف كوكبًا قزمًا. تسخين المواد المتطايرة يطلق الغاز والغبار من المذنبات. الرياح الشمسية والإشعاع يدفعان مكونات الذيل غالبًا بعيدًا عن الشمس. كلما زاد الاختلاف المركزي للقطع الناقص ازدادت استطالته. لا تجعل الذيل دائمًا خلف اتجاه حركة المذنب؛ يتأثر بالرياح الشمسية وضغط الإشعاع، فيتجه عمومًا بعيدًا عن الشمس. ولا تعتبر كل جسم في حزام الكويكبات مذنبًا. خطوات التحليل الصحيحة: حدد نوع الجرم ← افحص المدار ← قارن خصائصه. مصطلح التذكر هو كوكب قزم.","example":"كوكب قزم","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-orbit","scenario":"الكويكبات والمذنبات والكواكب القزمة"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"كيف يصنف بلوتو حاليًا؟","target":"","options":["نجم","كوكب قزم","كوكب عملاق غازي","قمر الأرض"],"answerIndex":1,"explanation":"بلوتو مصنف كوكبًا قزمًا."},{"number":1,"kind":"choice","prompt":"بماذا تشتهر المذنبات قرب الشمس؟","target":"","options":["ذؤابة وذيول من غاز وغبار","أسطح محيطات واسعة","احتراق الخشب","إضاءة ذاتية كنجم"],"answerIndex":0,"explanation":"تسخين المواد المتطايرة يطلق الغاز والغبار من المذنبات."},{"number":2,"kind":"choice","prompt":"إلى أي اتجاه يمتد ذيل المذنب عادة؟","target":"","options":["خلف الحركة دائمًا","نحو مركز الأرض","نحو أقرب كوكب","بعيدًا عن الشمس"],"answerIndex":3,"explanation":"الرياح الشمسية والإشعاع يدفعان مكونات الذيل غالبًا بعيدًا عن الشمس."},{"number":3,"kind":"choice","prompt":"ما أثر زيادة الاختلاف المركزي على المدار؟","target":"","options":["يلغي الجاذبية","يحول الكوكب إلى نجم","يجعله أكثر استطالة","يحوله إلى مربع"],"answerIndex":2,"explanation":"كلما زاد الاختلاف المركزي للقطع الناقص ازدادت استطالته."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «الكويكبات والمذنبات والكواكب القزمة» في هذا التمرين.","target":"","tokens":["قارن خصائصه","افحص المدار","حدد نوع الجرم"],"answer":["حدد نوع الجرم","افحص المدار","قارن خصائصه"],"explanation":"الترتيب الصحيح وفق الدرس: حدد نوع الجرم ← افحص المدار ← قارن خصائصه."},{"number":5,"kind":"type","prompt":"ما تصنيف بلوتو العلمي؟","target":"","answer":"كوكب قزم","explanation":"الكويكبات أجسام صغيرة غالبًا صخرية، والمذنبات تحتوي مواد متطايرة وغبارًا قد تشكل ذؤابة وذيلًا عند التسخين قرب الشمس. الكوكب القزم يدور حول الشمس ويقارب الشكل الكروي لكنه لم ينظف جواره المداري."}]},{"index":11,"stage":{"title":"المهمة الفضائية الأخيرة","subtitle":"شرح علمي ثم تجربة متغيرة واختبار للفهم","intro":"في المحطة 12 ندرس المهمة الفضائية الأخيرة. تخطيط مهمة فضائية يبدأ باختيار وجهة وهدف علمي، ثم النظر في المسافة والمدار وقيود الوقت والطاقة والاتصالات. لا يكفي اختيار كوكب قريب في صورة، فالمسافات والمدارات تتغير باستمرار.","tips":["تخطيط مهمة فضائية يبدأ باختيار وجهة وهدف علمي، ثم النظر في المسافة والمدار وقيود الوقت والطاقة والاتصالات. لا يكفي اختيار كوكب قريب في صورة، فالمسافات والمدارات تتغير باستمرار.","مثال مهمة تعليمية: إرسال مسبار إلى المريخ لدراسة سطحه. اختر أولًا الهدف العلمي، ثم حدد موضع المريخ المداري التقريبي وافحص لماذا يتطلب الانتقال وقتًا وليس خطًا مستقيمًا.","المختبر يقارن فترات مدارية مبسطة وليس برنامجًا ملاحيًا حقيقيًا أو محاكاة لحرق الوقود. انتقالات المركبات تحتاج نماذج جاذبية ومناورات متعددة ولا يجوز تخمين مواعيد إطلاق منها."],"lessons":[{"title":"الفكرة العلمية الأساسية","body":"تخطيط مهمة فضائية يبدأ باختيار وجهة وهدف علمي، ثم النظر في المسافة والمدار وقيود الوقت والطاقة والاتصالات. لا يكفي اختيار كوكب قريب في صورة، فالمسافات والمدارات تتغير باستمرار. تذكر أن تفسير الظاهرة يحتاج إلى معرفة المتغيرات والتمييز بين السبب والملاحظة.","example":"تحديد الهدف العلمي","note":"افهم التعريف والعلاقة العلمية قبل الانتقال إلى تجربة المحاكاة."},{"title":"مثال تطبيقي محلول","body":"مثال مهمة تعليمية: إرسال مسبار إلى المريخ لدراسة سطحه. اختر أولًا الهدف العلمي، ثم حدد موضع المريخ المداري التقريبي وافحص لماذا يتطلب الانتقال وقتًا وليس خطًا مستقيمًا. وعند مقارنة النتائج انتبه إلى الوحدات والتعريف المستخدم في الحساب.","example":"حدد الهدف العلمي ← افحص مدارات الأجرام ← اختر قياسات المهمة","note":"اتبع الخطوات الموضحة ثم جرّب قيمًا أخرى في المختبر."},{"title":"الحقائق والتفسيرات وحدود النموذج","body":"هدف المهمة يحدد الأدوات والقياسات المطلوبة. تحتاج أزمنة السفر حساب المدارات والمناورات وليس رسمًا غير مقياسي. المثال يختار المريخ لدراسة سطحه. المهمات تتعامل مع حركة الأهداف والجاذبية وتوقيت الإطلاق. المختبر يقارن فترات مدارية مبسطة وليس برنامجًا ملاحيًا حقيقيًا أو محاكاة لحرق الوقود. انتقالات المركبات تحتاج نماذج جاذبية ومناورات متعددة ولا يجوز تخمين مواعيد إطلاق منها. خطوات التحليل الصحيحة: حدد الهدف العلمي ← افحص مدارات الأجرام ← اختر قياسات المهمة. مصطلح التذكر هو المريخ.","example":"المريخ","note":"قد يختلف النموذج المبسط عن الواقع في جوانب مذكورة هنا؛ لا تستخدمه للتنبؤ الدقيق."}],"lab":{"kind":"science","model":"solar-mission","scenario":"المهمة الفضائية الأخيرة"},"source":{"title":"NASA Science — Solar System Facts","url":"https://science.nasa.gov/solar-system/solar-system-facts/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما أول قرار عند إعداد مهمة علمية؟","target":"","options":["تحديد الهدف العلمي","تغيير لون المركبة","اختيار موسيقى الرحلة","حساب عدد الصور فقط"],"answerIndex":0,"explanation":"هدف المهمة يحدد الأدوات والقياسات المطلوبة."},{"number":1,"kind":"choice","prompt":"هل المسافة في ملصق الكواكب دليل دقيق لوقت السفر؟","target":"","options":["نعم دائمًا","إذا كبرت الصورة","للمريخ فقط","لا"],"answerIndex":3,"explanation":"تحتاج أزمنة السفر حساب المدارات والمناورات وليس رسمًا غير مقياسي."},{"number":2,"kind":"choice","prompt":"ما وجهة مثال المهمة المذكورة؟","target":"","options":["عطارد","القمر تيتان","المريخ","نبتون"],"answerIndex":2,"explanation":"المثال يختار المريخ لدراسة سطحه."},{"number":3,"kind":"choice","prompt":"لماذا لا يكفي خط مستقيم إلى الهدف؟","target":"","options":["لأن المريخ بلا جاذبية","لأن الأجرام تتحرك في مدارات","لأن الضوء ثابت","لأن الكواكب مربعة"],"answerIndex":1,"explanation":"المهمات تتعامل مع حركة الأهداف والجاذبية وتوقيت الإطلاق."},{"number":4,"kind":"order","prompt":"رتّب خطوات تحليل «المهمة الفضائية الأخيرة» في هذا التمرين.","target":"","tokens":["اختر قياسات المهمة","افحص مدارات الأجرام","حدد الهدف العلمي"],"answer":["حدد الهدف العلمي","افحص مدارات الأجرام","اختر قياسات المهمة"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الهدف العلمي ← افحص مدارات الأجرام ← اختر قياسات المهمة."},{"number":5,"kind":"type","prompt":"ما الكوكب المستهدف في المثال النهائي؟","target":"","answer":"المريخ","explanation":"تخطيط مهمة فضائية يبدأ باختيار وجهة وهدف علمي، ثم النظر في المسافة والمدار وقيود الوقت والطاقة والاتصالات. لا يكفي اختيار كوكب قريب في صورة، فالمسافات والمدارات تتغير باستمرار."}]}]},{"slug":"weather-climate","course":{"title":"الطقس والمناخ","description":"من الغلاف الجوي والرطوبة والسحب إلى العواصف والخرائط الجوية وتفسير المناخ، مع مختبرات تفاعلية للتجربة.","category":"الفلك والطبيعة"},"stages":[{"index":0,"stage":{"title":"طبقات الغلاف الجوي","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا طبقات الغلاف الجوي. الغلاف الجوي يحيط بالأرض ويتكون أساسًا من النيتروجين والأكسجين. التروبوسفير هي الطبقة الأقرب لسطح الأرض وفيها تحدث معظم ظواهر الطقس. ينخفض الضغط عادة كلما ارتفعنا بسبب تناقص وزن عمود الهواء فوقنا.","tips":["الغلاف الجوي يحيط بالأرض ويتكون أساسًا من النيتروجين والأكسجين. التروبوسفير هي الطبقة الأقرب لسطح الأرض وفيها تحدث معظم ظواهر الطقس. ينخفض الضغط عادة كلما ارتفعنا بسبب تناقص وزن عمود الهواء فوقنا.","على ارتفاع 5 كم يكون الضغط أقل كثيرًا منه عند مستوى سطح البحر. في نموذج قياسي مبسط تنخفض الحرارة في الجزء الأدنى من التروبوسفير بنحو 6.5 درجات مئوية لكل كيلومتر، لكن الواقع يتغير بحسب الطقس والارتفاع.","لا تفترض أن درجات الحرارة تنخفض باستمرار في كل طبقات الغلاف الجوي؛ فالتدرج يتبدل في الستراتوسفير. النموذج هنا تقريب جوي قياسي وليس رصدًا حيًا."],"lessons":[{"title":"القاعدة العلمية","body":"الغلاف الجوي يحيط بالأرض ويتكون أساسًا من النيتروجين والأكسجين. التروبوسفير هي الطبقة الأقرب لسطح الأرض وفيها تحدث معظم ظواهر الطقس. ينخفض الضغط عادة كلما ارتفعنا بسبب تناقص وزن عمود الهواء فوقنا. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"التروبوسفير","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"على ارتفاع 5 كم يكون الضغط أقل كثيرًا منه عند مستوى سطح البحر. في نموذج قياسي مبسط تنخفض الحرارة في الجزء الأدنى من التروبوسفير بنحو 6.5 درجات مئوية لكل كيلومتر، لكن الواقع يتغير بحسب الطقس والارتفاع. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"حدد الارتفاع ← قارن الضغط ← ميز الطبقة","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"توجد معظم الغيوم والعواصف في التروبوسفير الأقرب لسطح الأرض. يقل الضغط مع ارتفاعنا لأن عمود الهواء فوقنا يصبح أقل كتلة. النيتروجين يقارب 78% من الغلاف الجوي الجاف. تختلف التدرجات الحرارية بين الطبقات الجوية. لا تفترض أن درجات الحرارة تنخفض باستمرار في كل طبقات الغلاف الجوي؛ فالتدرج يتبدل في الستراتوسفير. النموذج هنا تقريب جوي قياسي وليس رصدًا حيًا. خطوات التحقق: حدد الارتفاع ← قارن الضغط ← ميز الطبقة. مصطلح التذكر: التروبوسفير.","example":"التروبوسفير","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-atmosphere","scenario":"طبقات الغلاف الجوي"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream/atmosphere"}},"questions":[{"number":0,"kind":"choice","prompt":"في أي طبقة تحدث معظم الظواهر الجوية؟","target":"","options":["الثيرموسفير","الميزوسفير","الإكسوسفير","التروبوسفير"],"answerIndex":3,"explanation":"توجد معظم الغيوم والعواصف في التروبوسفير الأقرب لسطح الأرض."},{"number":1,"kind":"choice","prompt":"ماذا يحدث للضغط الجوي عمومًا مع الارتفاع؟","target":"","options":["يثبت دائمًا","يختفي فورًا","ينخفض","يرتفع بلا حد"],"answerIndex":2,"explanation":"يقل الضغط مع ارتفاعنا لأن عمود الهواء فوقنا يصبح أقل كتلة."},{"number":2,"kind":"choice","prompt":"أي غاز يشكل معظم الغلاف الجوي للأرض؟","target":"","options":["الأرجون","النيتروجين","الأكسجين","ثاني أكسيد الكربون"],"answerIndex":1,"explanation":"النيتروجين يقارب 78% من الغلاف الجوي الجاف."},{"number":3,"kind":"choice","prompt":"هل تنخفض الحرارة في جميع الطبقات بالوتيرة نفسها؟","target":"","options":["لا","نعم دائمًا","فقط فوق المحيط","في الليل فقط"],"answerIndex":0,"explanation":"تختلف التدرجات الحرارية بين الطبقات الجوية."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «طبقات الغلاف الجوي».","target":"","tokens":["ميز الطبقة","قارن الضغط","حدد الارتفاع"],"answer":["حدد الارتفاع","قارن الضغط","ميز الطبقة"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الارتفاع ← قارن الضغط ← ميز الطبقة."},{"number":5,"kind":"type","prompt":"ما اسم الطبقة الأقرب للأرض التي تحدث فيها معظم أحوال الطقس؟","target":"","answer":"التروبوسفير","explanation":"الغلاف الجوي يحيط بالأرض ويتكون أساسًا من النيتروجين والأكسجين. التروبوسفير هي الطبقة الأقرب لسطح الأرض وفيها تحدث معظم ظواهر الطقس. ينخفض الضغط عادة كلما ارتفعنا بسبب تناقص وزن عمود الهواء فوقنا."}]},{"index":1,"stage":{"title":"كيف تسخن الأرض؟","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا كيف تسخن الأرض؟. تصل الطاقة الشمسية إلى الأرض ثم تمتص الأسطح أجزاء منها وتنعكس أجزاء أخرى وفق البياض أو الألبيدو. الماء واليابسة يختلفان في السعة الحرارية والاختلاط والتبخر، لذا قد يستجيبان للإشعاع بطرق مختلفة.","tips":["تصل الطاقة الشمسية إلى الأرض ثم تمتص الأسطح أجزاء منها وتنعكس أجزاء أخرى وفق البياض أو الألبيدو. الماء واليابسة يختلفان في السعة الحرارية والاختلاط والتبخر، لذا قد يستجيبان للإشعاع بطرق مختلفة.","عند إشعاع 800 واط/م² وسطح يعكس 25%، يمتص السطح في هذا النموذج 600 واط/م². هذه طاقة ممتصة في وحدة المساحة والوقت، ولا تعني درجة حرارة نهائية معلومة.","لا تحوّل الإشعاع الممتص مباشرة إلى حرارة سطحية من دون ميزانية طاقة كاملة تتضمن فقدان الحرارة والحمل والإشعاع والتبخر. لون السطح عامل واحد من عوامل عديدة."],"lessons":[{"title":"القاعدة العلمية","body":"تصل الطاقة الشمسية إلى الأرض ثم تمتص الأسطح أجزاء منها وتنعكس أجزاء أخرى وفق البياض أو الألبيدو. الماء واليابسة يختلفان في السعة الحرارية والاختلاط والتبخر، لذا قد يستجيبان للإشعاع بطرق مختلفة. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"نسبة الإشعاع المنعكس","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"عند إشعاع 800 واط/م² وسطح يعكس 25%، يمتص السطح في هذا النموذج 600 واط/م². هذه طاقة ممتصة في وحدة المساحة والوقت، ولا تعني درجة حرارة نهائية معلومة. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"حدد الإشعاع ← حدد الانعكاس ← احسب الامتصاص","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"البياض أو الألبيدو يصف الجزء المنعكس من الطاقة الشمسية. الممتص يساوي 800 × (1−0.25) = 600 واط/م². تؤثر السعة الحرارية والاختلاط والتبخر في استجابة السطح للتسخين. يلزم أيضًا حساب الطاقة المفقودة والمنتقلة بآليات مختلفة. لا تحوّل الإشعاع الممتص مباشرة إلى حرارة سطحية من دون ميزانية طاقة كاملة تتضمن فقدان الحرارة والحمل والإشعاع والتبخر. لون السطح عامل واحد من عوامل عديدة. خطوات التحقق: حدد الإشعاع ← حدد الانعكاس ← احسب الامتصاص. مصطلح التذكر: الألبيدو.","example":"الألبيدو","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-heat","scenario":"كيف تسخن الأرض؟"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/education/resource-collections/climate"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا يعني الألبيدو؟","target":"","options":["ضغط البحر","سرعة دوران الأرض","نسبة الإشعاع المنعكس","كتلة الهواء"],"answerIndex":2,"explanation":"البياض أو الألبيدو يصف الجزء المنعكس من الطاقة الشمسية."},{"number":1,"kind":"choice","prompt":"إذا عكس سطح 25% فكم يمتص من 800 واط/م² تقريبًا؟","target":"","options":["25 واط/م²","600 واط/م²","200 واط/م²","800 واط/م²"],"answerIndex":1,"explanation":"الممتص يساوي 800 × (1−0.25) = 600 واط/م²."},{"number":2,"kind":"choice","prompt":"لماذا تختلف استجابة اليابسة والماء للتسخين؟","target":"","options":["السعة الحرارية والاختلاط والتبخر","لأن الماء بلا كتلة","لأن الشمس لا تصل الماء","لأن اليابسة بلا إشعاع"],"answerIndex":0,"explanation":"تؤثر السعة الحرارية والاختلاط والتبخر في استجابة السطح للتسخين."},{"number":3,"kind":"choice","prompt":"هل يحدد الإشعاع الممتص وحده درجة حرارة السطح؟","target":"","options":["نعم دائمًا","إذا كان نهارًا فقط","عند خط الاستواء فقط","لا"],"answerIndex":3,"explanation":"يلزم أيضًا حساب الطاقة المفقودة والمنتقلة بآليات مختلفة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «كيف تسخن الأرض؟».","target":"","tokens":["احسب الامتصاص","حدد الانعكاس","حدد الإشعاع"],"answer":["حدد الإشعاع","حدد الانعكاس","احسب الامتصاص"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الإشعاع ← حدد الانعكاس ← احسب الامتصاص."},{"number":5,"kind":"type","prompt":"ما اسم النسبة التي تعكسها الأسطح من ضوء الشمس؟","target":"","answer":"الألبيدو","explanation":"تصل الطاقة الشمسية إلى الأرض ثم تمتص الأسطح أجزاء منها وتنعكس أجزاء أخرى وفق البياض أو الألبيدو. الماء واليابسة يختلفان في السعة الحرارية والاختلاط والتبخر، لذا قد يستجيبان للإشعاع بطرق مختلفة."}]},{"index":2,"stage":{"title":"الضغط الجوي وحركة الرياح","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا الضغط الجوي وحركة الرياح. تتحرك الرياح بفعل فروق الضغط إلى جانب انحراف كوريوليس والاحتكاك وعوامل أخرى. قرب السطح في نصف الكرة الشمالي، تدور الرياح عادة عكس عقارب الساعة حول المنخفض الجوي مع تدفق نحو مركزه.","tips":["تتحرك الرياح بفعل فروق الضغط إلى جانب انحراف كوريوليس والاحتكاك وعوامل أخرى. قرب السطح في نصف الكرة الشمالي، تدور الرياح عادة عكس عقارب الساعة حول المنخفض الجوي مع تدفق نحو مركزه.","عندما يقل الضغط في مركز منطقة مقارنة بجوارها، يتكون تدرج ضغط يمكنه دفع الهواء. يمكن تمثيل ذلك بخريطة قيم افتراضية دون أن تعطي اتجاه الرياح وسرعتها الحقيقية بدقة.","لا تقل إن الرياح تسير دائمًا مباشرة من المرتفع إلى المنخفض على سطح الأرض؛ فكوريوليس والاحتكاك يغيران اتجاهها. الخرائط هنا صناعية تعليمية وليست توقعات."],"lessons":[{"title":"القاعدة العلمية","body":"تتحرك الرياح بفعل فروق الضغط إلى جانب انحراف كوريوليس والاحتكاك وعوامل أخرى. قرب السطح في نصف الكرة الشمالي، تدور الرياح عادة عكس عقارب الساعة حول المنخفض الجوي مع تدفق نحو مركزه. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"تدرج الضغط","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"عندما يقل الضغط في مركز منطقة مقارنة بجوارها، يتكون تدرج ضغط يمكنه دفع الهواء. يمكن تمثيل ذلك بخريطة قيم افتراضية دون أن تعطي اتجاه الرياح وسرعتها الحقيقية بدقة. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"حدد مراكز الضغط ← قارن القيم ← فسر حركة الهواء","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"فرق الضغط عبر المسافة يسبب قوة تدرج الضغط. مع تأثير كوريوليس والاحتكاك يكون دوران المنخفض الشمالي عادة عكسيًا. يتعاكس اتجاه انحراف كوريوليس بين نصفي الكرة. لا يعطي النموذج معطيات فعلية ولا حلًا عدديًا كاملًا للطقس. لا تقل إن الرياح تسير دائمًا مباشرة من المرتفع إلى المنخفض على سطح الأرض؛ فكوريوليس والاحتكاك يغيران اتجاهها. الخرائط هنا صناعية تعليمية وليست توقعات. خطوات التحقق: حدد مراكز الضغط ← قارن القيم ← فسر حركة الهواء. مصطلح التذكر: كوريوليس.","example":"كوريوليس","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-map","scenario":"الضغط الجوي وحركة الرياح"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"ما العامل الذي يدفع الهواء بسبب اختلاف الضغط؟","target":"","options":["درجة حموضة الماء","تدرج الضغط","اسم المدينة","لون السحب"],"answerIndex":1,"explanation":"فرق الضغط عبر المسافة يسبب قوة تدرج الضغط."},{"number":1,"kind":"choice","prompt":"كيف يدور الهواء غالبًا حول منخفض في نصف الكرة الشمالي قرب السطح؟","target":"","options":["عكس عقارب الساعة","مع عقارب الساعة","لا يدور","يتحرك عموديًا فقط"],"answerIndex":0,"explanation":"مع تأثير كوريوليس والاحتكاك يكون دوران المنخفض الشمالي عادة عكسيًا."},{"number":2,"kind":"choice","prompt":"هل تختلف حركة الهواء بين نصفي الكرة بسبب كوريوليس؟","target":"","options":["لا","فقط فوق اليابسة","فقط في الصيف","نعم"],"answerIndex":3,"explanation":"يتعاكس اتجاه انحراف كوريوليس بين نصفي الكرة."},{"number":3,"kind":"choice","prompt":"هل النموذج المبسط خريطة توقع فعلية؟","target":"","options":["إن اخترنا قيمة ضغط","عندما نستخدم ألوانًا","لا","نعم"],"answerIndex":2,"explanation":"لا يعطي النموذج معطيات فعلية ولا حلًا عدديًا كاملًا للطقس."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «الضغط الجوي وحركة الرياح».","target":"","tokens":["فسر حركة الهواء","قارن القيم","حدد مراكز الضغط"],"answer":["حدد مراكز الضغط","قارن القيم","فسر حركة الهواء"],"explanation":"الترتيب الصحيح وفق الدرس: حدد مراكز الضغط ← قارن القيم ← فسر حركة الهواء."},{"number":5,"kind":"type","prompt":"ما اسم تأثير دوران الأرض الذي يساهم في انحراف الرياح؟","target":"","answer":"كوريوليس","explanation":"تتحرك الرياح بفعل فروق الضغط إلى جانب انحراف كوريوليس والاحتكاك وعوامل أخرى. قرب السطح في نصف الكرة الشمالي، تدور الرياح عادة عكس عقارب الساعة حول المنخفض الجوي مع تدفق نحو مركزه."}]},{"index":3,"stage":{"title":"الرطوبة ونقطة الندى","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا الرطوبة ونقطة الندى. الرطوبة النسبية تقارن مقدار بخار الماء الموجود بما يستطيع الهواء أن يكون عليه عند التشبع في درجة الحرارة نفسها. نقطة الندى هي الحرارة التي يصل عندها الهواء إلى التشبع إذا برد دون تغيير كمية بخار الماء تقريبًا.","tips":["الرطوبة النسبية تقارن مقدار بخار الماء الموجود بما يستطيع الهواء أن يكون عليه عند التشبع في درجة الحرارة نفسها. نقطة الندى هي الحرارة التي يصل عندها الهواء إلى التشبع إذا برد دون تغيير كمية بخار الماء تقريبًا.","إذا كانت الحرارة 25°م والرطوبة النسبية نحو 50%، تكون نقطة الندى أدنى من الحرارة بكثير. وعند تبريد الهواء إلى نقطة الندى قد يبدأ التكاثف إذا توافرت نوى مناسبة.","ارتفاع الرطوبة النسبية لا يضمن المطر؛ فقد يبلغ الهواء التشبع دون تشكل قطرات كبيرة كفاية للهطول. الحساب هنا تقريب باستخدام علاقة ضغط البخار المشبع."],"lessons":[{"title":"القاعدة العلمية","body":"الرطوبة النسبية تقارن مقدار بخار الماء الموجود بما يستطيع الهواء أن يكون عليه عند التشبع في درجة الحرارة نفسها. نقطة الندى هي الحرارة التي يصل عندها الهواء إلى التشبع إذا برد دون تغيير كمية بخار الماء تقريبًا. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"نسبة بخار الماء إلى التشبع عند الحرارة نفسها","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"إذا كانت الحرارة 25°م والرطوبة النسبية نحو 50%، تكون نقطة الندى أدنى من الحرارة بكثير. وعند تبريد الهواء إلى نقطة الندى قد يبدأ التكاثف إذا توافرت نوى مناسبة. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"قارن الحرارة والرطوبة ← احسب نقطة الندى ← فسر احتمال التكاثف","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"تقارن الرطوبة النسبية ضغط بخار الماء بالضغط المشبع في الحرارة نفسها. نقطة الندى هي حرارة التشبع مع بقاء كمية بخار الماء تقريبًا. يلزم نمو القطرات وعمليات ميكروفيزيائية قبل حدوث المطر. قطرات السحب تتكون عادة حول جسيمات دقيقة مثل الأملاح والغبار. ارتفاع الرطوبة النسبية لا يضمن المطر؛ فقد يبلغ الهواء التشبع دون تشكل قطرات كبيرة كفاية للهطول. الحساب هنا تقريب باستخدام علاقة ضغط البخار المشبع. خطوات التحقق: قارن الحرارة والرطوبة ← احسب نقطة الندى ← فسر احتمال التكاثف. مصطلح التذكر: نقطة الندى.","example":"نقطة الندى","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-moisture","scenario":"الرطوبة ونقطة الندى"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream/clouds/how-clouds-form"}},"questions":[{"number":0,"kind":"choice","prompt":"ما المقصود بالرطوبة النسبية؟","target":"","options":["نسبة بخار الماء إلى التشبع عند الحرارة نفسها","ضغط الهواء وحده","كتلة السحب فقط","درجة حرارة سطح البحر"],"answerIndex":0,"explanation":"تقارن الرطوبة النسبية ضغط بخار الماء بالضغط المشبع في الحرارة نفسها."},{"number":1,"kind":"choice","prompt":"ماذا تعني نقطة الندى؟","target":"","options":["أعلى حرارة في النهار","درجة غليان الماء","سرعة الرياح","درجة الوصول للتشبع عند التبريد"],"answerIndex":3,"explanation":"نقطة الندى هي حرارة التشبع مع بقاء كمية بخار الماء تقريبًا."},{"number":2,"kind":"choice","prompt":"هل تشبع الهواء يضمن سقوط المطر؟","target":"","options":["إذا كان صيفًا","إذا كانت هناك رياح فقط","لا","نعم دائمًا"],"answerIndex":2,"explanation":"يلزم نمو القطرات وعمليات ميكروفيزيائية قبل حدوث المطر."},{"number":3,"kind":"choice","prompt":"ما الذي قد يساعد على تكاثف بخار الماء في السحب؟","target":"","options":["ارتفاع الحرارة دائمًا","نوى التكاثف","الفراغ المطلق","انعدام الرطوبة"],"answerIndex":1,"explanation":"قطرات السحب تتكون عادة حول جسيمات دقيقة مثل الأملاح والغبار."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «الرطوبة ونقطة الندى».","target":"","tokens":["فسر احتمال التكاثف","احسب نقطة الندى","قارن الحرارة والرطوبة"],"answer":["قارن الحرارة والرطوبة","احسب نقطة الندى","فسر احتمال التكاثف"],"explanation":"الترتيب الصحيح وفق الدرس: قارن الحرارة والرطوبة ← احسب نقطة الندى ← فسر احتمال التكاثف."},{"number":5,"kind":"type","prompt":"ما اسم درجة بدء التشبع عند التبريد؟","target":"","answer":"نقطة الندى","explanation":"الرطوبة النسبية تقارن مقدار بخار الماء الموجود بما يستطيع الهواء أن يكون عليه عند التشبع في درجة الحرارة نفسها. نقطة الندى هي الحرارة التي يصل عندها الهواء إلى التشبع إذا برد دون تغيير كمية بخار الماء تقريبًا."}]},{"index":4,"stage":{"title":"كيف تتكون السحب؟","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا كيف تتكون السحب؟. عندما يرتفع الهواء يتمدد تحت ضغط أقل فيبرد غالبًا. إذا وصل إلى نقطة الندى وكان لديه بخار ماء ونوى تكاثف، قد تتكون قطرات سحاب أو بلورات جليد. لا تتساوى جميع السحب في الشكل والارتفاع.","tips":["عندما يرتفع الهواء يتمدد تحت ضغط أقل فيبرد غالبًا. إذا وصل إلى نقطة الندى وكان لديه بخار ماء ونوى تكاثف، قد تتكون قطرات سحاب أو بلورات جليد. لا تتساوى جميع السحب في الشكل والارتفاع.","في المختبر، زد الرطوبة أو اخفض الحرارة فتقترب الحالة من التشبع. هذا يوضح خطوة لازمة في ظروف كثيرة، لكنه لا يحاكي الرفع والرذاذ وبلورات الجليد بتفاصيلها.","تكون سحابة في النموذج لا يعني تلقائيًا هطول مطر. يحدث التكاثف في جو متحرك، وتحتاج قطرات المطر إلى النمو بما يكفي للسقوط."],"lessons":[{"title":"القاعدة العلمية","body":"عندما يرتفع الهواء يتمدد تحت ضغط أقل فيبرد غالبًا. إذا وصل إلى نقطة الندى وكان لديه بخار ماء ونوى تكاثف، قد تتكون قطرات سحاب أو بلورات جليد. لا تتساوى جميع السحب في الشكل والارتفاع. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"تبرد","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"في المختبر، زد الرطوبة أو اخفض الحرارة فتقترب الحالة من التشبع. هذا يوضح خطوة لازمة في ظروف كثيرة، لكنه لا يحاكي الرفع والرذاذ وبلورات الجليد بتفاصيلها. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"ارفع رطوبة الهواء ← قربه من التشبع ← راجع نوى التكاثف","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"يتسبب التمدد الأديباتي عادة في تبريد الكتلة الصاعدة. وجود بخار الماء والنوى وبلوغ التشبع يساعد على التكاثف. قطرات السحب ليست دائمًا كبيرة بما يكفي للهطول. ترتفع الرطوبة النسبية ويقترب الهواء من التشبع. تكون سحابة في النموذج لا يعني تلقائيًا هطول مطر. يحدث التكاثف في جو متحرك، وتحتاج قطرات المطر إلى النمو بما يكفي للسقوط. خطوات التحقق: ارفع رطوبة الهواء ← قربه من التشبع ← راجع نوى التكاثف. مصطلح التذكر: التكاثف.","example":"التكاثف","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-moisture","scenario":"كيف تتكون السحب؟"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream/clouds/how-clouds-form"}},"questions":[{"number":0,"kind":"choice","prompt":"ما الذي يحدث غالبًا لكتلة هواء ترتفع وتتمدد؟","target":"","options":["تشتعل","تزداد كثافتها دومًا","تفقد كل بخار الماء فورًا","تبرد"],"answerIndex":3,"explanation":"يتسبب التمدد الأديباتي عادة في تبريد الكتلة الصاعدة."},{"number":1,"kind":"choice","prompt":"ما الشرطان الرئيسيان لتكون قطرات السحب وفق النموذج؟","target":"","options":["حرارة عالية جدًا دائمًا","فراغ تام","توفر الماء ونوى التكاثف مع التشبع","عدم وجود بخار ماء"],"answerIndex":2,"explanation":"وجود بخار الماء والنوى وبلوغ التشبع يساعد على التكاثف."},{"number":2,"kind":"choice","prompt":"هل كل سحابة تمطر؟","target":"","options":["إذا ظهرت نهارًا","لا","نعم","إذا كان لونها أبيض"],"answerIndex":1,"explanation":"قطرات السحب ليست دائمًا كبيرة بما يكفي للهطول."},{"number":3,"kind":"choice","prompt":"ما أثر زيادة الرطوبة عند نفس الحرارة؟","target":"","options":["الاقتراب من التشبع","انعدام بخار الماء","ارتفاع كتلة الشمس","تغير اتجاه الأرض"],"answerIndex":0,"explanation":"ترتفع الرطوبة النسبية ويقترب الهواء من التشبع."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «كيف تتكون السحب؟».","target":"","tokens":["راجع نوى التكاثف","قربه من التشبع","ارفع رطوبة الهواء"],"answer":["ارفع رطوبة الهواء","قربه من التشبع","راجع نوى التكاثف"],"explanation":"الترتيب الصحيح وفق الدرس: ارفع رطوبة الهواء ← قربه من التشبع ← راجع نوى التكاثف."},{"number":5,"kind":"type","prompt":"ما العملية التي تحول بخار الماء إلى قطرات؟","target":"","answer":"التكاثف","explanation":"عندما يرتفع الهواء يتمدد تحت ضغط أقل فيبرد غالبًا. إذا وصل إلى نقطة الندى وكان لديه بخار ماء ونوى تكاثف، قد تتكون قطرات سحاب أو بلورات جليد. لا تتساوى جميع السحب في الشكل والارتفاع."}]},{"index":5,"stage":{"title":"المطر والثلج والبرد","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا المطر والثلج والبرد. يختلف نوع الهطول تبعًا إلى درجة الحرارة في طبقات الجو ومسار القطرة أو بلورة الجليد خلال السقوط. قد يتشكل الثلج في غيمة باردة، ثم يذوب أثناء هبوطه عبر هواء دافئ ليصل كمطر.","tips":["يختلف نوع الهطول تبعًا إلى درجة الحرارة في طبقات الجو ومسار القطرة أو بلورة الجليد خلال السقوط. قد يتشكل الثلج في غيمة باردة، ثم يذوب أثناء هبوطه عبر هواء دافئ ليصل كمطر.","إذا كانت طبقة الهواء القريبة من السطح تحت الصفر وكان عمود الهواء باردًا بعمومه، يزداد احتمال وصول الثلج. لكن مجرد درجة حرارة سطحية واحدة لا تكفي لتحديد الهطول بدقة.","البرَد يتكون غالبًا داخل تيارات صاعدة قوية في عواصف رعدية، ولا يساوي الثلج العادي. مختبر الرطوبة يشرح التشبع فقط، لا يتنبأ بنوع الهطول."],"lessons":[{"title":"القاعدة العلمية","body":"يختلف نوع الهطول تبعًا إلى درجة الحرارة في طبقات الجو ومسار القطرة أو بلورة الجليد خلال السقوط. قد يتشكل الثلج في غيمة باردة، ثم يذوب أثناء هبوطه عبر هواء دافئ ليصل كمطر. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"الملف الحراري العمودي للغلاف الجوي","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"إذا كانت طبقة الهواء القريبة من السطح تحت الصفر وكان عمود الهواء باردًا بعمومه، يزداد احتمال وصول الثلج. لكن مجرد درجة حرارة سطحية واحدة لا تكفي لتحديد الهطول بدقة. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"حدد طبقات الحرارة ← تتبع سقوط القطرة ← ميز نوع الهطول","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"قد ينصهر الثلج أثناء الهبوط عبر طبقة دافئة. تُحافظ الطبقات الباردة على البلورات الثلجية أثناء السقوط. ينمو البرد عادة داخل السحب الركامية الرعدية. تؤثر درجات الحرارة على طول المسار العمودي للهطول. البرَد يتكون غالبًا داخل تيارات صاعدة قوية في عواصف رعدية، ولا يساوي الثلج العادي. مختبر الرطوبة يشرح التشبع فقط، لا يتنبأ بنوع الهطول. خطوات التحقق: حدد طبقات الحرارة ← تتبع سقوط القطرة ← ميز نوع الهطول. مصطلح التذكر: البرد.","example":"البرد","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-moisture","scenario":"المطر والثلج والبرد"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"ما الذي يؤثر بقوة في نوع الهطول؟","target":"","options":["كتلة الأرض","لون التربة","الملف الحراري العمودي للغلاف الجوي","اسم الشهر فقط"],"answerIndex":2,"explanation":"قد ينصهر الثلج أثناء الهبوط عبر طبقة دافئة."},{"number":1,"kind":"choice","prompt":"كيف يمكن أن يصل الثلج إلى الأرض؟","target":"","options":["إذا كان سطح البحر مرتفعًا","إذا بقي عمود الهواء باردًا بما يكفي","إذا كان سطح الأرض حارًا جدًا","إذا انعدمت السحب"],"answerIndex":1,"explanation":"تُحافظ الطبقات الباردة على البلورات الثلجية أثناء السقوط."},{"number":2,"kind":"choice","prompt":"أين يتكون البرد غالبًا؟","target":"","options":["داخل عواصف رعدية بتيارات صاعدة قوية","داخل الصخور","في القمر","تحت قاع البحر"],"answerIndex":0,"explanation":"ينمو البرد عادة داخل السحب الركامية الرعدية."},{"number":3,"kind":"choice","prompt":"هل تكفي حرارة السطح وحدها لتحديد نوع الهطول؟","target":"","options":["نعم","في جميع الفصول","إذا كان المطر غزيرًا","لا"],"answerIndex":3,"explanation":"تؤثر درجات الحرارة على طول المسار العمودي للهطول."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «المطر والثلج والبرد».","target":"","tokens":["ميز نوع الهطول","تتبع سقوط القطرة","حدد طبقات الحرارة"],"answer":["حدد طبقات الحرارة","تتبع سقوط القطرة","ميز نوع الهطول"],"explanation":"الترتيب الصحيح وفق الدرس: حدد طبقات الحرارة ← تتبع سقوط القطرة ← ميز نوع الهطول."},{"number":5,"kind":"type","prompt":"ما اسم الكرات الجليدية التي تنمو في عواصف رعدية؟","target":"","answer":"البرد","explanation":"يختلف نوع الهطول تبعًا إلى درجة الحرارة في طبقات الجو ومسار القطرة أو بلورة الجليد خلال السقوط. قد يتشكل الثلج في غيمة باردة، ثم يذوب أثناء هبوطه عبر هواء دافئ ليصل كمطر."}]},{"index":6,"stage":{"title":"الجبهات الهوائية","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا الجبهات الهوائية. الجبهة الفاصلة بين كتلتي هواء مختلفتي الحرارة والرطوبة، وقد تسبب رفع الهواء وتغير الغيوم والهطول. الجبهة الباردة تتقدم عندما تدفع كتلة أبرد كتلة أدفأ، والجبهة الدافئة عندما تتقدم كتلة دافئة.","tips":["الجبهة الفاصلة بين كتلتي هواء مختلفتي الحرارة والرطوبة، وقد تسبب رفع الهواء وتغير الغيوم والهطول. الجبهة الباردة تتقدم عندما تدفع كتلة أبرد كتلة أدفأ، والجبهة الدافئة عندما تتقدم كتلة دافئة.","في خريطة مبسطة، ضع هواء أبرد غرب خط فاصل وهواء أدفأ شرقه؛ إذا تقدمت الكتلة الباردة يمكن أن يرتفع الهواء الدافئ قرب الجبهة. راقب كيف يرتبط انخفاض الضغط بتغيرات الجو.","ليست جميع الجبهات متشابهة، ولا تضمن كل جبهة هطول المطر. الخرائط التعليمية لا تمثل نموذجًا ثلاثي الأبعاد للتوزيع الحراري أو تطور الغيوم."],"lessons":[{"title":"القاعدة العلمية","body":"الجبهة الفاصلة بين كتلتي هواء مختلفتي الحرارة والرطوبة، وقد تسبب رفع الهواء وتغير الغيوم والهطول. الجبهة الباردة تتقدم عندما تدفع كتلة أبرد كتلة أدفأ، والجبهة الدافئة عندما تتقدم كتلة دافئة. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"حد فاصل بين كتل هوائية مختلفة","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"في خريطة مبسطة، ضع هواء أبرد غرب خط فاصل وهواء أدفأ شرقه؛ إذا تقدمت الكتلة الباردة يمكن أن يرتفع الهواء الدافئ قرب الجبهة. راقب كيف يرتبط انخفاض الضغط بتغيرات الجو. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"ميز الكتلتين ← حدد الجبهة ← افحص الرفع المحتمل","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"الجبهة منطقة فاصلة بين كتل هواء ذات خصائص مختلفة. تتقدم في الجبهة الباردة كتلة أبرد وتدفع الأدفأ. قد يؤدي دفع الهواء الدافئ إلى أعلى إلى التكاثف وتكوّن الغيوم. يعتمد الهطول على الرطوبة والاستقرار وبنية الجبهة. ليست جميع الجبهات متشابهة، ولا تضمن كل جبهة هطول المطر. الخرائط التعليمية لا تمثل نموذجًا ثلاثي الأبعاد للتوزيع الحراري أو تطور الغيوم. خطوات التحقق: ميز الكتلتين ← حدد الجبهة ← افحص الرفع المحتمل. مصطلح التذكر: الجبهة.","example":"الجبهة","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-map","scenario":"الجبهات الهوائية"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"ما الجبهة الهوائية؟","target":"","options":["نواة السحابة","حد فاصل بين كتل هوائية مختلفة","حافة اليابسة","خط الاستواء دائمًا"],"answerIndex":1,"explanation":"الجبهة منطقة فاصلة بين كتل هواء ذات خصائص مختلفة."},{"number":1,"kind":"choice","prompt":"ما الجبهة الباردة؟","target":"","options":["تقدم كتلة أبرد نحو أدفأ","تقدم قمر نحو الأرض","اختفاء الضغط","تجمد البحر دائمًا"],"answerIndex":0,"explanation":"تتقدم في الجبهة الباردة كتلة أبرد وتدفع الأدفأ."},{"number":2,"kind":"choice","prompt":"ماذا يمكن أن يحدث للهواء الدافئ عند جبهة باردة؟","target":"","options":["يختفي فورًا","تتوقف حركته","تنعدم رطوبته دائمًا","يرتفع"],"answerIndex":3,"explanation":"قد يؤدي دفع الهواء الدافئ إلى أعلى إلى التكاثف وتكوّن الغيوم."},{"number":3,"kind":"choice","prompt":"هل كل جبهة تسبب مطرًا بالضرورة؟","target":"","options":["إذا كانت باردة","إذا كان ضغطها منخفضًا","لا","نعم"],"answerIndex":2,"explanation":"يعتمد الهطول على الرطوبة والاستقرار وبنية الجبهة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «الجبهات الهوائية».","target":"","tokens":["افحص الرفع المحتمل","حدد الجبهة","ميز الكتلتين"],"answer":["ميز الكتلتين","حدد الجبهة","افحص الرفع المحتمل"],"explanation":"الترتيب الصحيح وفق الدرس: ميز الكتلتين ← حدد الجبهة ← افحص الرفع المحتمل."},{"number":5,"kind":"type","prompt":"ما اسم الحد بين كتلتين هوائيتين؟","target":"","answer":"الجبهة","explanation":"الجبهة الفاصلة بين كتلتي هواء مختلفتي الحرارة والرطوبة، وقد تسبب رفع الهواء وتغير الغيوم والهطول. الجبهة الباردة تتقدم عندما تدفع كتلة أبرد كتلة أدفأ، والجبهة الدافئة عندما تتقدم كتلة دافئة."}]},{"index":7,"stage":{"title":"العواصف الرعدية","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا العواصف الرعدية. تحتاج العواصف الرعدية إلى رطوبة ورفع وعدم استقرار جوي يساعد على تطور السحب الركامية. يتكون البرق من تفريغ كهربائي، والرعد صوت الموجة الناتجة عن التسخين السريع للهواء.","tips":["تحتاج العواصف الرعدية إلى رطوبة ورفع وعدم استقرار جوي يساعد على تطور السحب الركامية. يتكون البرق من تفريغ كهربائي، والرعد صوت الموجة الناتجة عن التسخين السريع للهواء.","قد توجد حرارة ورطوبة مرتفعتان دون عاصفة رعدية إن غاب الرفع الكافي أو منع الاستقرار تطور السحب. غيّر حرارة سطح البحر والقص الريحي في المختبر لمناقشة بيئات العواصف دون التنبؤ بالبرق.","ليس كل صوت قوي بعد غيمة «دليلًا على خطر محدد»؛ تابع تحذيرات الأرصاد الرسمية عند العواصف. المحاكاة لا تصدر تنبيه طقس ولا تحسب تشكل البرق."],"lessons":[{"title":"القاعدة العلمية","body":"تحتاج العواصف الرعدية إلى رطوبة ورفع وعدم استقرار جوي يساعد على تطور السحب الركامية. يتكون البرق من تفريغ كهربائي، والرعد صوت الموجة الناتجة عن التسخين السريع للهواء. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"رطوبة ورفع وعدم استقرار","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"قد توجد حرارة ورطوبة مرتفعتان دون عاصفة رعدية إن غاب الرفع الكافي أو منع الاستقرار تطور السحب. غيّر حرارة سطح البحر والقص الريحي في المختبر لمناقشة بيئات العواصف دون التنبؤ بالبرق. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"افحص الرطوبة ← افحص الرفع ← قدّر الاستقرار","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"الرطوبة والرفع وعدم الاستقرار تساعد على تطور العواصف الرعدية. يسخن البرق الهواء بسرعة ويحدث موجة ضغط تسمع كرعد. يلزم توفر عدة عوامل ومنها الرطوبة والرفع وعدم الاستقرار. التحذيرات الفعلية تصدرها جهات الأرصاد المختصة. ليس كل صوت قوي بعد غيمة «دليلًا على خطر محدد»؛ تابع تحذيرات الأرصاد الرسمية عند العواصف. المحاكاة لا تصدر تنبيه طقس ولا تحسب تشكل البرق. خطوات التحقق: افحص الرطوبة ← افحص الرفع ← قدّر الاستقرار. مصطلح التذكر: البرق.","example":"البرق","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-storm","scenario":"العواصف الرعدية"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"ما العناصر الأساسية لتطور عاصفة رعدية؟","target":"","options":["رطوبة ورفع وعدم استقرار","جليد صلب فقط","كتلة شمس كبيرة","غياب الهواء"],"answerIndex":0,"explanation":"الرطوبة والرفع وعدم الاستقرار تساعد على تطور العواصف الرعدية."},{"number":1,"kind":"choice","prompt":"من أين يأتي صوت الرعد؟","target":"","options":["احتكاك القمر بالشمس","أمواج البحر فقط","انهيار السحب الصلبة","التمدد السريع للهواء المسخن بالبرق"],"answerIndex":3,"explanation":"يسخن البرق الهواء بسرعة ويحدث موجة ضغط تسمع كرعد."},{"number":2,"kind":"choice","prompt":"هل حرارة عالية وحدها تضمن عاصفة رعدية؟","target":"","options":["ليلًا فقط","فوق الجبال فقط","لا","نعم"],"answerIndex":2,"explanation":"يلزم توفر عدة عوامل ومنها الرطوبة والرفع وعدم الاستقرار."},{"number":3,"kind":"choice","prompt":"ما المصدر الآمن لتحذيرات العواصف الحقيقية؟","target":"","options":["لون شاشة الهاتف","هيئات الأرصاد الرسمية","هذا المختبر","توقع غير موثق"],"answerIndex":1,"explanation":"التحذيرات الفعلية تصدرها جهات الأرصاد المختصة."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «العواصف الرعدية».","target":"","tokens":["قدّر الاستقرار","افحص الرفع","افحص الرطوبة"],"answer":["افحص الرطوبة","افحص الرفع","قدّر الاستقرار"],"explanation":"الترتيب الصحيح وفق الدرس: افحص الرطوبة ← افحص الرفع ← قدّر الاستقرار."},{"number":5,"kind":"type","prompt":"ما اسم التفريغ الكهربائي المضيء في العاصفة؟","target":"","answer":"البرق","explanation":"تحتاج العواصف الرعدية إلى رطوبة ورفع وعدم استقرار جوي يساعد على تطور السحب الركامية. يتكون البرق من تفريغ كهربائي، والرعد صوت الموجة الناتجة عن التسخين السريع للهواء."}]},{"index":8,"stage":{"title":"الأعاصير المدارية","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا الأعاصير المدارية. تحتاج الأعاصير المدارية بيئة ملائمة تشمل مياهًا دافئة على عمق كافٍ ورطوبة ودورانًا ومقدارًا محدودًا من القص الرأسي للرياح. تستخدم حرارة سطح البحر نحو 26.5°م دليلًا تعليميًا تقريبيًا، لكنه ليس شرطًا كافيًا ولا حدًا مطلقًا.","tips":["تحتاج الأعاصير المدارية بيئة ملائمة تشمل مياهًا دافئة على عمق كافٍ ورطوبة ودورانًا ومقدارًا محدودًا من القص الرأسي للرياح. تستخدم حرارة سطح البحر نحو 26.5°م دليلًا تعليميًا تقريبيًا، لكنه ليس شرطًا كافيًا ولا حدًا مطلقًا","في المختبر، جرّب مياهًا أكثر دفئًا وقصًا رأسيًا أضعف: قد تصبح بعض الظروف أكثر ملاءمة للتطور، لكن وجود إعصار يحتاج رصدًا فعليًا وعوامل أخرى عديدة.","لا يجوز إصدار توقع لمسار إعصار أو احتمالية تكوّنه من متغيرين فقط. الأداة توضيحية ولا تعتمد بيانات آنية، لذا راجع المصادر الرسمية لمعلومات السلامة."],"lessons":[{"title":"القاعدة العلمية","body":"تحتاج الأعاصير المدارية بيئة ملائمة تشمل مياهًا دافئة على عمق كافٍ ورطوبة ودورانًا ومقدارًا محدودًا من القص الرأسي للرياح. تستخدم حرارة سطح البحر نحو 26.5°م دليلًا تعليميًا تقريبيًا، لكنه ليس شرطًا كافيًا ولا حدًا مطلقًا. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"مياه دافئة ورطوبة مناسبة","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"في المختبر، جرّب مياهًا أكثر دفئًا وقصًا رأسيًا أضعف: قد تصبح بعض الظروف أكثر ملاءمة للتطور، لكن وجود إعصار يحتاج رصدًا فعليًا وعوامل أخرى عديدة. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"حدد حرارة الماء ← حدد القص الرأسي ← فسر ملاءمة الظروف","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"توفّر حرارة مياه البحر والرطوبة طاقة للتطور في بيئات مناسبة. القص القوي قد يعرقل تنظيم البنية العمودية للعاصفة. حد الحرارة تقريبي؛ توجد عوامل جوية ومحيطية أخرى كثيرة. المختبر لا يستعمل رصدًا أو نماذج طقس تشغيلية. لا يجوز إصدار توقع لمسار إعصار أو احتمالية تكوّنه من متغيرين فقط. الأداة توضيحية ولا تعتمد بيانات آنية، لذا راجع المصادر الرسمية لمعلومات السلامة. خطوات التحقق: حدد حرارة الماء ← حدد القص الرأسي ← فسر ملاءمة الظروف. مصطلح التذكر: القص الرأسي.","example":"القص الرأسي","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-storm","scenario":"الأعاصير المدارية"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"أي عامل يدعم تطور الأعاصير المدارية عادة؟","target":"","options":["مياه شديدة البرودة وحدها","غياب الدوران الأرضي","جبال ثلجية","مياه دافئة ورطوبة مناسبة"],"answerIndex":3,"explanation":"توفّر حرارة مياه البحر والرطوبة طاقة للتطور في بيئات مناسبة."},{"number":1,"kind":"choice","prompt":"ما أثر القص الرأسي الشديد للرياح غالبًا؟","target":"","options":["يمنع حركة الرياح كلها","يولد زلزالًا","قد يعيق تنظيم العاصفة","يضمن قوة أكبر دائمًا"],"answerIndex":2,"explanation":"القص القوي قد يعرقل تنظيم البنية العمودية للعاصفة."},{"number":2,"kind":"choice","prompt":"هل تجاوز 26.5°م يضمن إعصارًا؟","target":"","options":["إذا كان الوقت ليلًا","لا","نعم دائمًا","في كل بحر"],"answerIndex":1,"explanation":"حد الحرارة تقريبي؛ توجد عوامل جوية ومحيطية أخرى كثيرة."},{"number":3,"kind":"choice","prompt":"هل المختبر يعطي توقعات أعاصير حقيقية؟","target":"","options":["لا","نعم","فقط عند 30 درجة","فقط في نصف الكرة الشمالي"],"answerIndex":0,"explanation":"المختبر لا يستعمل رصدًا أو نماذج طقس تشغيلية."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «الأعاصير المدارية».","target":"","tokens":["فسر ملاءمة الظروف","حدد القص الرأسي","حدد حرارة الماء"],"answer":["حدد حرارة الماء","حدد القص الرأسي","فسر ملاءمة الظروف"],"explanation":"الترتيب الصحيح وفق الدرس: حدد حرارة الماء ← حدد القص الرأسي ← فسر ملاءمة الظروف."},{"number":5,"kind":"type","prompt":"ما اسم تغير سرعة أو اتجاه الرياح مع الارتفاع؟","target":"","answer":"القص الرأسي","explanation":"تحتاج الأعاصير المدارية بيئة ملائمة تشمل مياهًا دافئة على عمق كافٍ ورطوبة ودورانًا ومقدارًا محدودًا من القص الرأسي للرياح. تستخدم حرارة سطح البحر نحو 26.5°م دليلًا تعليميًا تقريبيًا، لكنه ليس شرطًا كافيًا ولا حدًا مطلقًا."}]},{"index":9,"stage":{"title":"كيف نقرأ خرائط الطقس؟","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا كيف نقرأ خرائط الطقس؟. تُظهر خرائط الطقس خطوط الضغط المتساوي والجبهات والغيوم وغيرها من الظواهر. تُفسر مناطق الضغط المنخفض والمرتفع وفق الموقع والفصل وحالة الغلاف الجوي، وتحتاج القراءة إلى تاريخ الخريطة ووحداتها.","tips":["تُظهر خرائط الطقس خطوط الضغط المتساوي والجبهات والغيوم وغيرها من الظواهر. تُفسر مناطق الضغط المنخفض والمرتفع وفق الموقع والفصل وحالة الغلاف الجوي، وتحتاج القراءة إلى تاريخ الخريطة ووحداتها.","إذا كانت الخطوط متقاربة فقد يكون تدرج الضغط أكبر، ما يدعم رياحًا أقوى في ظروف متشابهة. لا تستنتج اتجاه الرياح بدقة من سهم واحد أو خريطة دون نصف الكرة ومقدار الاحتكاك.","خريطة الضغط في مختبرنا بيانات صناعية وليس توقعًا لمنطقتك. لإصدار توقع حقيقي راجع الرصد والأقمار الصناعية والنماذج والتحذيرات المحلية."],"lessons":[{"title":"القاعدة العلمية","body":"تُظهر خرائط الطقس خطوط الضغط المتساوي والجبهات والغيوم وغيرها من الظواهر. تُفسر مناطق الضغط المنخفض والمرتفع وفق الموقع والفصل وحالة الغلاف الجوي، وتحتاج القراءة إلى تاريخ الخريطة ووحداتها. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"خطوط تصل نقاط الضغط نفسه","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"إذا كانت الخطوط متقاربة فقد يكون تدرج الضغط أكبر، ما يدعم رياحًا أقوى في ظروف متشابهة. لا تستنتج اتجاه الرياح بدقة من سهم واحد أو خريطة دون نصف الكرة ومقدار الاحتكاك. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"اقرأ الوقت والموقع ← حدد الضغط والجبهات ← فسر الحالات المحتملة","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"خط تساوي الضغط يربط مواقع الضغط الجوي المتساوي. التقارب يعني تغيرًا أكبر للضغط عبر مسافة قصيرة. الخريطة تحتاج المكان والوقت والمقياس والوحدات. هي خريطة توضيحية وليست حالة جوية متصلة بمحطة رصد. خريطة الضغط في مختبرنا بيانات صناعية وليس توقعًا لمنطقتك. لإصدار توقع حقيقي راجع الرصد والأقمار الصناعية والنماذج والتحذيرات المحلية. خطوات التحقق: اقرأ الوقت والموقع ← حدد الضغط والجبهات ← فسر الحالات المحتملة. مصطلح التذكر: الأيزوبار.","example":"الأيزوبار","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-map","scenario":"كيف نقرأ خرائط الطقس؟"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"ما المقصود بخطوط الضغط المتساوي؟","target":"","options":["حدود المدن","مسارات الأقمار","خطوط تصل نقاط الضغط نفسه","خطوط طول الأرض فقط"],"answerIndex":2,"explanation":"خط تساوي الضغط يربط مواقع الضغط الجوي المتساوي."},{"number":1,"kind":"choice","prompt":"ماذا يعني تقارب خطوط الضغط غالبًا؟","target":"","options":["ازدياد طول النهار","تدرج ضغط أشد","عدم وجود رياح قطعًا","ارتفاع الشمس"],"answerIndex":1,"explanation":"التقارب يعني تغيرًا أكبر للضغط عبر مسافة قصيرة."},{"number":2,"kind":"choice","prompt":"ما المعلومات الضرورية لقراءة خريطة طقس صحيحة؟","target":"","options":["الموقع والتاريخ والوحدات","لون الصورة فقط","اسم الرسام وحده","مقاس الورقة"],"answerIndex":0,"explanation":"الخريطة تحتاج المكان والوقت والمقياس والوحدات."},{"number":3,"kind":"choice","prompt":"هل خريطة الدرس توقع حي؟","target":"","options":["نعم","إذا ظهرت الأسهم","عند منتصف النهار","لا"],"answerIndex":3,"explanation":"هي خريطة توضيحية وليست حالة جوية متصلة بمحطة رصد."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «كيف نقرأ خرائط الطقس؟».","target":"","tokens":["فسر الحالات المحتملة","حدد الضغط والجبهات","اقرأ الوقت والموقع"],"answer":["اقرأ الوقت والموقع","حدد الضغط والجبهات","فسر الحالات المحتملة"],"explanation":"الترتيب الصحيح وفق الدرس: اقرأ الوقت والموقع ← حدد الضغط والجبهات ← فسر الحالات المحتملة."},{"number":5,"kind":"type","prompt":"ما اسم الخط الذي يجمع نقاط ضغط متساو؟","target":"","answer":"الأيزوبار","explanation":"تُظهر خرائط الطقس خطوط الضغط المتساوي والجبهات والغيوم وغيرها من الظواهر. تُفسر مناطق الضغط المنخفض والمرتفع وفق الموقع والفصل وحالة الغلاف الجوي، وتحتاج القراءة إلى تاريخ الخريطة ووحداتها."}]},{"index":10,"stage":{"title":"الفرق بين الطقس والمناخ","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا الفرق بين الطقس والمناخ. الطقس حالة الغلاف الجوي في زمان ومكان محددين، أما المناخ فيصف خصائص الجو وإحصاءاته على مدد طويلة غالبًا 30 سنة أو أكثر. يوم شديد البرودة لا يحدد وحده اتجاه المناخ.","tips":["الطقس حالة الغلاف الجوي في زمان ومكان محددين، أما المناخ فيصف خصائص الجو وإحصاءاته على مدد طويلة غالبًا 30 سنة أو أكثر. يوم شديد البرودة لا يحدد وحده اتجاه المناخ.","يمكن مقارنة يوم مطير واحد بمتوسط هطول موسم كامل، لكنهما مقياسان مختلفان. في المختبر نقارن أثر الإشعاع والانعكاس على امتصاص الطاقة كمثال لعامل مناخي، دون اعتبار الناتج توقع حرارة لسنوات.","لا تساو بين تغير يومي قصير واتجاه مناخي طويل المدى. الاختلافات الطبيعية والغازات الدفيئة والمحيطات وعوامل أخرى تدخل في النظام المناخي."],"lessons":[{"title":"القاعدة العلمية","body":"الطقس حالة الغلاف الجوي في زمان ومكان محددين، أما المناخ فيصف خصائص الجو وإحصاءاته على مدد طويلة غالبًا 30 سنة أو أكثر. يوم شديد البرودة لا يحدد وحده اتجاه المناخ. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"حالة الجو في زمان ومكان قصيرين","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"يمكن مقارنة يوم مطير واحد بمتوسط هطول موسم كامل، لكنهما مقياسان مختلفان. في المختبر نقارن أثر الإشعاع والانعكاس على امتصاص الطاقة كمثال لعامل مناخي، دون اعتبار الناتج توقع حرارة لسنوات. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"ميز المدى الزمني ← قارن الإحصاءات ← فسر الاتجاه","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"الطقس ظروف الغلاف الجوي الآنية أو القصيرة. تحسب القيم الطبيعية المناخية في فترات نموذجية من 30 سنة. اليوم الواحد لا يمثل اتجاهًا إحصائيًا طويل الأمد. يتأثر امتصاص الطاقة بالإشعاع الوارد والألبيدو. لا تساو بين تغير يومي قصير واتجاه مناخي طويل المدى. الاختلافات الطبيعية والغازات الدفيئة والمحيطات وعوامل أخرى تدخل في النظام المناخي. خطوات التحقق: ميز المدى الزمني ← قارن الإحصاءات ← فسر الاتجاه. مصطلح التذكر: المناخ.","example":"المناخ","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-heat","scenario":"الفرق بين الطقس والمناخ"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/explainers/what-s-difference-between-climate-and-weather"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا يصف الطقس؟","target":"","options":["مدار القمر","حالة الجو في زمان ومكان قصيرين","متوسط القرن فقط","تركيب صخور الوشاح"],"answerIndex":1,"explanation":"الطقس ظروف الغلاف الجوي الآنية أو القصيرة."},{"number":1,"kind":"choice","prompt":"ما المدة الشائعة لمعايير المناخ؟","target":"","options":["30 سنة","يوم واحد","أسبوع","ساعة"],"answerIndex":0,"explanation":"تحسب القيم الطبيعية المناخية في فترات نموذجية من 30 سنة."},{"number":2,"kind":"choice","prompt":"هل يوم بارد وحده ينفي تغيرًا مناخيًا؟","target":"","options":["نعم","إذا كان شتاء","إذا انخفض الضغط","لا"],"answerIndex":3,"explanation":"اليوم الواحد لا يمثل اتجاهًا إحصائيًا طويل الأمد."},{"number":3,"kind":"choice","prompt":"ما أحد مدخلات ميزانية طاقة السطح؟","target":"","options":["سرعة الضوء فقط","عدد الكواكب","الإشعاع الشمسي والانعكاس","حروف أسماء السحب"],"answerIndex":2,"explanation":"يتأثر امتصاص الطاقة بالإشعاع الوارد والألبيدو."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «الفرق بين الطقس والمناخ».","target":"","tokens":["فسر الاتجاه","قارن الإحصاءات","ميز المدى الزمني"],"answer":["ميز المدى الزمني","قارن الإحصاءات","فسر الاتجاه"],"explanation":"الترتيب الصحيح وفق الدرس: ميز المدى الزمني ← قارن الإحصاءات ← فسر الاتجاه."},{"number":5,"kind":"type","prompt":"ما اسم وصف متوسط الظروف الجوية طويلة المدى؟","target":"","answer":"المناخ","explanation":"الطقس حالة الغلاف الجوي في زمان ومكان محددين، أما المناخ فيصف خصائص الجو وإحصاءاته على مدد طويلة غالبًا 30 سنة أو أكثر. يوم شديد البرودة لا يحدد وحده اتجاه المناخ."}]},{"index":11,"stage":{"title":"أنت خبير الأرصاد: التحدي الأخير","subtitle":"من الرصد والتفسير إلى تجربة الطقس","intro":"نتعلم هنا أنت خبير الأرصاد: التحدي الأخير. التوقع الجوي الجيد يجمع رصد الضغط والحرارة والرطوبة والرياح والسحب وتطورها عبر الزمن، ويعبر عن عدم اليقين. قراءة رقم منفرد لا تسمح بتوقع دقيق لوقت الهطول أو مسار عاصفة.","tips":["التوقع الجوي الجيد يجمع رصد الضغط والحرارة والرطوبة والرياح والسحب وتطورها عبر الزمن، ويعبر عن عدم اليقين. قراءة رقم منفرد لا تسمح بتوقع دقيق لوقت الهطول أو مسار عاصفة.","افترض خريطة صناعية يظهر فيها منخفض وضغط يتناقص نحو المركز: حدّد منطقة التدرج الأقوى ثم قارن مع بيانات رطوبة مفترضة قبل وصف احتمالات تغير الغيوم. لا تصدر إنذارًا حقيقيًا اعتمادًا على تمرين.","المختبر محاكاة تعليمية؛ التوقعات الآنية تتطلب نماذج تشغيلية وأرصادًا محدثة. استخدم عبارة «قد» حيث توجد احتمالات، واربط الاستنتاج بالمعلومات المتاحة."],"lessons":[{"title":"القاعدة العلمية","body":"التوقع الجوي الجيد يجمع رصد الضغط والحرارة والرطوبة والرياح والسحب وتطورها عبر الزمن، ويعبر عن عدم اليقين. قراءة رقم منفرد لا تسمح بتوقع دقيق لوقت الهطول أو مسار عاصفة. نقارن بين العوامل المتغيرة ونفصل المشاهدة عن تفسيرها لتجنب الاستنتاج الخاطئ.","example":"أرصاد حديثة ونماذج ومراجعة عدم اليقين","note":"حدد المتغير الذي تدرسه، ثم فكر في وحداته قبل التجربة."},{"title":"حالة جوية محلولة","body":"افترض خريطة صناعية يظهر فيها منخفض وضغط يتناقص نحو المركز: حدّد منطقة التدرج الأقوى ثم قارن مع بيانات رطوبة مفترضة قبل وصف احتمالات تغير الغيوم. لا تصدر إنذارًا حقيقيًا اعتمادًا على تمرين. يُستحسن اختبار أكثر من حالة ومقارنة نتائجها لا الاكتفاء بمشاهدة واحدة.","example":"اجمع البيانات ← حدد العوامل المؤثرة ← صغ توقعًا مشروطًا","note":"لاحظ كيف يغيّر النموذج نتائجنا عندما تتغير المدخلات."},{"title":"حقائق وتحذيرات مهمة","body":"يعتمد التوقع على بيانات رصد متعددة ونماذج عددية وتقييم الثقة. احتمال المطر يعتمد على الرطوبة والرفع والتوزيع الحراري وغيرها. منهجية الأرصاد تميز التوقع الاحتمالي عن اليقين. التمارين لا تتصل بالرصد الحي ولا بنماذج تنبؤ تشغيلية. المختبر محاكاة تعليمية؛ التوقعات الآنية تتطلب نماذج تشغيلية وأرصادًا محدثة. استخدم عبارة «قد» حيث توجد احتمالات، واربط الاستنتاج بالمعلومات المتاحة. خطوات التحقق: اجمع البيانات ← حدد العوامل المؤثرة ← صغ توقعًا مشروطًا. مصطلح التذكر: الأرصاد الجوية.","example":"الأرصاد الجوية","note":"هذه محاكاة تعليمية لا تنشر إنذارات أو توقعات طقس حقيقية."}],"lab":{"kind":"science","model":"weather-map","scenario":"أنت خبير الأرصاد: التحدي الأخير"},"source":{"title":"NOAA — مصدر علمي للطقس والمناخ","url":"https://www.noaa.gov/jetstream"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا تحتاج النشرة الجوية الموثوقة؟","target":"","options":["أرصاد حديثة ونماذج ومراجعة عدم اليقين","صورة ضغط واحدة فقط","تخمين دون تاريخ","لون الغلاف"],"answerIndex":0,"explanation":"يعتمد التوقع على بيانات رصد متعددة ونماذج عددية وتقييم الثقة."},{"number":1,"kind":"choice","prompt":"هل انخفاض الضغط وحده يضمن مطرًا؟","target":"","options":["نعم","إذا كان الشتاء","إذا مر يومان","لا"],"answerIndex":3,"explanation":"احتمال المطر يعتمد على الرطوبة والرفع والتوزيع الحراري وغيرها."},{"number":2,"kind":"choice","prompt":"كيف تعبّر عن نتيجة غير مؤكدة؟","target":"","options":["بإخفاء البيانات","بتهويل الظاهرة","بذكر الاحتمال وحدود الأدلة","بقول أكيد دائمًا"],"answerIndex":2,"explanation":"منهجية الأرصاد تميز التوقع الاحتمالي عن اليقين."},{"number":3,"kind":"choice","prompt":"هل يمكن استعمال المحاكاة كتنبؤ فعلي؟","target":"","options":["فقط في النهار","لا","نعم دائمًا","فقط في المدن"],"answerIndex":1,"explanation":"التمارين لا تتصل بالرصد الحي ولا بنماذج تنبؤ تشغيلية."},{"number":4,"kind":"order","prompt":"رتّب خطوات تجربة «أنت خبير الأرصاد: التحدي الأخير».","target":"","tokens":["صغ توقعًا مشروطًا","حدد العوامل المؤثرة","اجمع البيانات"],"answer":["اجمع البيانات","حدد العوامل المؤثرة","صغ توقعًا مشروطًا"],"explanation":"الترتيب الصحيح وفق الدرس: اجمع البيانات ← حدد العوامل المؤثرة ← صغ توقعًا مشروطًا."},{"number":5,"kind":"type","prompt":"ما اسم العلم الذي يدرس أحوال الجو ويتنبأ بها؟","target":"","answer":"الأرصاد الجوية","explanation":"التوقع الجوي الجيد يجمع رصد الضغط والحرارة والرطوبة والرياح والسحب وتطورها عبر الزمن، ويعبر عن عدم اليقين. قراءة رقم منفرد لا تسمح بتوقع دقيق لوقت الهطول أو مسار عاصفة."}]}]},{"slug":"earth-interior","course":{"title":"الأرض من الداخل","description":"اكتشف طبقات الأرض والصفائح والزلازل والبراكين ودورة الصخور، وجرّب نماذج جيولوجية مبسطة في 12 محطة.","category":"الفلك والطبيعة"},"stages":[{"index":0,"stage":{"title":"طبقات الأرض العميقة","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 1 على طبقات الأرض العميقة. تتكون الأرض بنيويًا من قشرة ووشاح ولب، ويُقسم اللب إلى خارجي سائل وداخلي صلب في الظروف السائدة. يبلغ متوسط نصف قطر الأرض نحو 6371 كم، وتصل حدود الوشاح واللب إلى عمق نحو 2900 كم، ويبدأ اللب الداخلي قرب 5150 كم.","tips":["تتكون الأرض بنيويًا من قشرة ووشاح ولب، ويُقسم اللب إلى خارجي سائل وداخلي صلب في الظروف السائدة. يبلغ متوسط نصف قطر الأرض نحو 6371 كم، وتصل حدود الوشاح واللب إلى عمق نحو 2900 كم، ويبدأ اللب الداخلي قرب 5150 كم.","في النموذج اختر عمق 100 كم ثم 3000 كم؛ الأول داخل الوشاح الأعلى في مناطق كثيرة، والثاني يقع في اللب الخارجي. القشرة رقيقة جدًا مقارنة بنصف قطر الأرض، ويختلف سمكها بين المحيطات والقارات.","هذه حدود مبسطة لطبقات ميكانيكية وكيميائية؛ لا تفسر النموذج على أن الأرض تحوي حدودًا مسطحة أو درجة حرارة واحدة داخل كل طبقة."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"تتكون الأرض بنيويًا من قشرة ووشاح ولب، ويُقسم اللب إلى خارجي سائل وداخلي صلب في الظروف السائدة. يبلغ متوسط نصف قطر الأرض نحو 6371 كم، وتصل حدود الوشاح واللب إلى عمق نحو 2900 كم، ويبدأ اللب الداخلي قرب 5150 كم. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"القشرة","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"في النموذج اختر عمق 100 كم ثم 3000 كم؛ الأول داخل الوشاح الأعلى في مناطق كثيرة، والثاني يقع في اللب الخارجي. القشرة رقيقة جدًا مقارنة بنصف قطر الأرض، ويختلف سمكها بين المحيطات والقارات. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد العمق ← ميز الطبقة ← راجع طبيعتها","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"القشرة طبقة رقيقة للغاية مقارنة بنصف قطر الأرض. اللب الخارجي سائل بينما اللب الداخلي صلب في الظروف السائدة. يبلغ متوسط نصف قطر الأرض حوالي 6371 كيلومترًا. تقع حدود الوشاح واللب حول عمق 2900 كم. هذه حدود مبسطة لطبقات ميكانيكية وكيميائية؛ لا تفسر النموذج على أن الأرض تحوي حدودًا مسطحة أو درجة حرارة واحدة داخل كل طبقة. خطوات التحليل: حدد العمق ← ميز الطبقة ← راجع طبيعتها. المصطلح الذي تعلمته: القشرة.","example":"القشرة","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-interior","scenario":"طبقات الأرض العميقة"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes"}},"questions":[{"number":0,"kind":"choice","prompt":"أي طبقات الأرض أرق نسبة إلى نصف القطر؟","target":"","options":["الوشاح","اللب الخارجي","اللب الداخلي","القشرة"],"answerIndex":3,"explanation":"القشرة طبقة رقيقة للغاية مقارنة بنصف قطر الأرض."},{"number":1,"kind":"choice","prompt":"أي جزء من اللب في الحالة السائلة أساسًا؟","target":"","options":["القشرة","الوشاح كله","اللب الخارجي","اللب الداخلي"],"answerIndex":2,"explanation":"اللب الخارجي سائل بينما اللب الداخلي صلب في الظروف السائدة."},{"number":2,"kind":"choice","prompt":"ما متوسط نصف قطر الأرض تقريبًا؟","target":"","options":["290 كم","6371 كم","637 كم","150 مليون كم"],"answerIndex":1,"explanation":"يبلغ متوسط نصف قطر الأرض حوالي 6371 كيلومترًا."},{"number":3,"kind":"choice","prompt":"على أي عمق يبدأ اللب الخارجي تقريبًا؟","target":"","options":["2900 كم","35 كم","100 كم","6000 كم"],"answerIndex":0,"explanation":"تقع حدود الوشاح واللب حول عمق 2900 كم."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «طبقات الأرض العميقة».","target":"","tokens":["راجع طبيعتها","ميز الطبقة","حدد العمق"],"answer":["حدد العمق","ميز الطبقة","راجع طبيعتها"],"explanation":"الترتيب الصحيح وفق الدرس: حدد العمق ← ميز الطبقة ← راجع طبيعتها."},{"number":5,"kind":"type","prompt":"ما الطبقة الأرضية التي تقع فوق الوشاح؟","target":"","answer":"القشرة","explanation":"تتكون الأرض بنيويًا من قشرة ووشاح ولب، ويُقسم اللب إلى خارجي سائل وداخلي صلب في الظروف السائدة. يبلغ متوسط نصف قطر الأرض نحو 6371 كم، وتصل حدود الوشاح واللب إلى عمق نحو 2900 كم، ويبدأ اللب الداخلي قرب 5150 كم."}]},{"index":1,"stage":{"title":"كيف تتحرك القارات؟","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 2 على كيف تتحرك القارات؟. الغلاف الصخري للأرض مقسم إلى صفائح تكتونية تتحرك بسرعات تبلغ غالبًا سنتيمترات سنويًا. الحركة النسبية بين الصفائح تسبب انتشارًا لقاع البحر واندساسًا وتصادمًا وحدودًا تحويلية، لكن القارات ليست ألواحًا منفصلة بالكامل عن الصفائح المحيطية.","tips":["الغلاف الصخري للأرض مقسم إلى صفائح تكتونية تتحرك بسرعات تبلغ غالبًا سنتيمترات سنويًا. الحركة النسبية بين الصفائح تسبب انتشارًا لقاع البحر واندساسًا وتصادمًا وحدودًا تحويلية، لكن القارات ليست ألواحًا منفصلة بالكامل عن الص","إذا تحركت صفيحة بسرعة 5 سم/سنة طوال مليون سنة باتجاه ثابت افتراضيًا، فإن الإزاحة نحو 50 كم. هذا لا يعني أن السرعة أو الاتجاه لا يتغيران خلال ملايين السنين.","لا تصور الصفائح تتحرك فوق محيط من صهارة سائلة؛ الوشاح صلب في الغالب ويتشوه ببطء عبر أزمنة جيولوجية طويلة."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"الغلاف الصخري للأرض مقسم إلى صفائح تكتونية تتحرك بسرعات تبلغ غالبًا سنتيمترات سنويًا. الحركة النسبية بين الصفائح تسبب انتشارًا لقاع البحر واندساسًا وتصادمًا وحدودًا تحويلية، لكن القارات ليست ألواحًا منفصلة بالكامل عن الصفائح المحيطية. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"تكتونية الصفائح","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"إذا تحركت صفيحة بسرعة 5 سم/سنة طوال مليون سنة باتجاه ثابت افتراضيًا، فإن الإزاحة نحو 50 كم. هذا لا يعني أن السرعة أو الاتجاه لا يتغيران خلال ملايين السنين. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد الصفيحة ← قارن اتجاه الحركة ← احسب الإزاحة","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"تكتونية الصفائح تفسر الحركة النسبية للغلاف الصخري. السرعات المعتادة تتراوح في حدود سنتيمترات سنويًا. 5 سم × مليون سنة = 5 مليون سم = 50 كم. معظم الوشاح صلب مع قابلية تشوه بطيء. لا تصور الصفائح تتحرك فوق محيط من صهارة سائلة؛ الوشاح صلب في الغالب ويتشوه ببطء عبر أزمنة جيولوجية طويلة. خطوات التحليل: حدد الصفيحة ← قارن اتجاه الحركة ← احسب الإزاحة. المصطلح الذي تعلمته: الصفائح.","example":"الصفائح","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-plates","scenario":"كيف تتحرك القارات؟"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards"}},"questions":[{"number":0,"kind":"choice","prompt":"ما اسم نظرية حركة ألواح الغلاف الصخري؟","target":"","options":["التبخر الدوري","قانون كبلر","تكتونية الصفائح","ثبات القارات"],"answerIndex":2,"explanation":"تكتونية الصفائح تفسر الحركة النسبية للغلاف الصخري."},{"number":1,"kind":"choice","prompt":"كم تتحرك صفائح كثيرة سنويًا تقريبًا؟","target":"","options":["لا تتحرك مطلقًا","سنتيمترات","آلاف الكيلومترات","مئات الأمتار"],"answerIndex":1,"explanation":"السرعات المعتادة تتراوح في حدود سنتيمترات سنويًا."},{"number":2,"kind":"choice","prompt":"إذا تحركت صفيحة 5 سم/سنة لمدة مليون سنة فما الإزاحة التقريبية؟","target":"","options":["50 كم","5 كم","5000 كم","500 متر"],"answerIndex":0,"explanation":"5 سم × مليون سنة = 5 مليون سم = 50 كم."},{"number":3,"kind":"choice","prompt":"هل الوشاح كله سائل منصهر؟","target":"","options":["نعم","القشرة فقط سائلة","اللب كله غاز","لا"],"answerIndex":3,"explanation":"معظم الوشاح صلب مع قابلية تشوه بطيء."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «كيف تتحرك القارات؟».","target":"","tokens":["احسب الإزاحة","قارن اتجاه الحركة","حدد الصفيحة"],"answer":["حدد الصفيحة","قارن اتجاه الحركة","احسب الإزاحة"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الصفيحة ← قارن اتجاه الحركة ← احسب الإزاحة."},{"number":5,"kind":"type","prompt":"ما اسم الألواح المتحركة في الغلاف الصخري؟","target":"","answer":"الصفائح","explanation":"الغلاف الصخري للأرض مقسم إلى صفائح تكتونية تتحرك بسرعات تبلغ غالبًا سنتيمترات سنويًا. الحركة النسبية بين الصفائح تسبب انتشارًا لقاع البحر واندساسًا وتصادمًا وحدودًا تحويلية، لكن القارات ليست ألواحًا منفصلة بالكامل عن الصفائح المحيطية."}]},{"index":2,"stage":{"title":"الحدود التباعدية","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 3 على الحدود التباعدية. في الحدود التباعدية تبتعد صفيحتان، فتزداد مساحة القشرة الجديدة في مناطق مثل حيود وسط المحيط؛ يرتفع الوشاح ويحدث انصهار جزئي مع انخفاض الضغط. المثال الشهير هو حيد وسط الأطلسي.","tips":["في الحدود التباعدية تبتعد صفيحتان، فتزداد مساحة القشرة الجديدة في مناطق مثل حيود وسط المحيط؛ يرتفع الوشاح ويحدث انصهار جزئي مع انخفاض الضغط. المثال الشهير هو حيد وسط الأطلسي.","في المختبر اختر «تباعد» ثم سرعة نسبية 4 سم/سنة؛ خلال مليون سنة يصل الفتح الهندسي التقريبي إلى 40 كم إذا افترضنا ثبات السرعة. يمكن أن يظهر صدع ووادي انهدامي في بعض البيئات القارية.","المحاكاة لا تنتج قشرة حقيقية ولا تتبع كامل مسار الصهارة. وليست كل الحدود التباعدية في البحار؛ توجد أمثلة برية في أودية الانهدام."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"في الحدود التباعدية تبتعد صفيحتان، فتزداد مساحة القشرة الجديدة في مناطق مثل حيود وسط المحيط؛ يرتفع الوشاح ويحدث انصهار جزئي مع انخفاض الضغط. المثال الشهير هو حيد وسط الأطلسي. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"تبتعد الصفائح","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"في المختبر اختر «تباعد» ثم سرعة نسبية 4 سم/سنة؛ خلال مليون سنة يصل الفتح الهندسي التقريبي إلى 40 كم إذا افترضنا ثبات السرعة. يمكن أن يظهر صدع ووادي انهدامي في بعض البيئات القارية. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"اختر التباعد ← حدد السرعة ← قارن الإزاحة","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"تتحرك الصفائح بعيدًا عن بعضها في الحدود التباعدية. حيود وسط المحيط مناطق شائعة لتولد قشرة محيطية جديدة. يمكن أن يؤدي انخفاض الضغط إلى انصهار جزئي للوشاح الصاعد. 4 سنتيمترات سنويًا تساوي 40 كيلومترًا في مليون سنة. المحاكاة لا تنتج قشرة حقيقية ولا تتبع كامل مسار الصهارة. وليست كل الحدود التباعدية في البحار؛ توجد أمثلة برية في أودية الانهدام. خطوات التحليل: اختر التباعد ← حدد السرعة ← قارن الإزاحة. المصطلح الذي تعلمته: الحيد.","example":"الحيد","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-plates","scenario":"الحدود التباعدية"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا يحدث عند حدود الصفائح التباعدية؟","target":"","options":["تختفي الجاذبية","تبتعد الصفائح","تتصادم دائمًا","تتوقف الحركة"],"answerIndex":1,"explanation":"تتحرك الصفائح بعيدًا عن بعضها في الحدود التباعدية."},{"number":1,"kind":"choice","prompt":"أين توجد أمثلة شهيرة لانتشار قاع البحر؟","target":"","options":["حيد وسط الأطلسي","وسط الصحراء الكبرى وحدها","في باطن القمر","فوق سحب الأرض"],"answerIndex":0,"explanation":"حيود وسط المحيط مناطق شائعة لتولد قشرة محيطية جديدة."},{"number":2,"kind":"choice","prompt":"ما الذي يساعد انصهار الوشاح تحت الحيود؟","target":"","options":["تجميد كامل الوشاح","توقف الصفائح","انعدام الحرارة","انخفاض الضغط أثناء الصعود"],"answerIndex":3,"explanation":"يمكن أن يؤدي انخفاض الضغط إلى انصهار جزئي للوشاح الصاعد."},{"number":3,"kind":"choice","prompt":"إذا كانت السرعة 4 سم/سنة لمدة مليون سنة فما الإزاحة؟","target":"","options":["4000 كم","400 متر","40 كم","4 كم"],"answerIndex":2,"explanation":"4 سنتيمترات سنويًا تساوي 40 كيلومترًا في مليون سنة."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «الحدود التباعدية».","target":"","tokens":["قارن الإزاحة","حدد السرعة","اختر التباعد"],"answer":["اختر التباعد","حدد السرعة","قارن الإزاحة"],"explanation":"الترتيب الصحيح وفق الدرس: اختر التباعد ← حدد السرعة ← قارن الإزاحة."},{"number":5,"kind":"type","prompt":"ما اسم الحافة البحرية التي تنتشر عندها القشرة الجديدة؟","target":"","answer":"الحيد","explanation":"في الحدود التباعدية تبتعد صفيحتان، فتزداد مساحة القشرة الجديدة في مناطق مثل حيود وسط المحيط؛ يرتفع الوشاح ويحدث انصهار جزئي مع انخفاض الضغط. المثال الشهير هو حيد وسط الأطلسي."}]},{"index":3,"stage":{"title":"التصادم وتكوّن الجبال","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 4 على التصادم وتكوّن الجبال. عند حدود الصفائح التقاربية قد تندس صفيحة محيطية تحت أخرى أو تصطدم قارتان فتنضغط الصخور وترتفع الجبال. سلسلة الهيمالايا نتجت من التصادم المستمر بين الصفيحتين الهندية والأوراسية.","tips":["عند حدود الصفائح التقاربية قد تندس صفيحة محيطية تحت أخرى أو تصطدم قارتان فتنضغط الصخور وترتفع الجبال. سلسلة الهيمالايا نتجت من التصادم المستمر بين الصفيحتين الهندية والأوراسية.","اختر في المختبر صفيحتين قاريتين متقاربتين وشاهد رسم رفع للجبال، ثم قارن باندساس محيطي-قاري قد يصاحبه خندق وبراكين على الهامش القاري.","ليس كل تصادم يولد النتيجة نفسها؛ تعتمد الظواهر على كثافة ونوع الصفيحتين وتاريخ المنطقة. النماذج ثنائية الأبعاد تشرح مبدأ الحركة لا تضاريس دقيقة."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"عند حدود الصفائح التقاربية قد تندس صفيحة محيطية تحت أخرى أو تصطدم قارتان فتنضغط الصخور وترتفع الجبال. سلسلة الهيمالايا نتجت من التصادم المستمر بين الصفيحتين الهندية والأوراسية. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"التقاربية","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"اختر في المختبر صفيحتين قاريتين متقاربتين وشاهد رسم رفع للجبال، ثم قارن باندساس محيطي-قاري قد يصاحبه خندق وبراكين على الهامش القاري. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد نوع الصفائح ← اختر التقارب ← فسر الرفع أو الاندساس","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"القوى التقاربية تضغط القشرة وقد ترفع الجبال. تكوّنت الهيمالايا من تصادم الهند مع أوراسيا. الاندساس يرتبط بأخاديد بحرية وأقواس بركانية في سياقات كثيرة. تتوقف النتائج على أنواع الصفائح وظروفها. ليس كل تصادم يولد النتيجة نفسها؛ تعتمد الظواهر على كثافة ونوع الصفيحتين وتاريخ المنطقة. النماذج ثنائية الأبعاد تشرح مبدأ الحركة لا تضاريس دقيقة. خطوات التحليل: حدد نوع الصفائح ← اختر التقارب ← فسر الرفع أو الاندساس. المصطلح الذي تعلمته: الاندساس.","example":"الاندساس","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-plates","scenario":"التصادم وتكوّن الجبال"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards"}},"questions":[{"number":0,"kind":"choice","prompt":"ما نوع الحدود الذي قد ينشئ الجبال بالتصادم؟","target":"","options":["التقاربية","التباعدية فقط","التحويلية فقط","بدون حركة صفائح"],"answerIndex":0,"explanation":"القوى التقاربية تضغط القشرة وقد ترفع الجبال."},{"number":1,"kind":"choice","prompt":"ما الصفيحتان المرتبطتان بتكوّن الهيمالايا؟","target":"","options":["الأفريقية والأمريكية الجنوبية","القطبية والأطلسية","الهادئة والقطبية فقط","الهندية والأوراسية"],"answerIndex":3,"explanation":"تكوّنت الهيمالايا من تصادم الهند مع أوراسيا."},{"number":2,"kind":"choice","prompt":"ماذا يمكن أن ينتج عن اندساس صفيحة محيطية تحت قارية؟","target":"","options":["حيد تباعدي فقط","تحول الصخور إلى غاز","خندق وبراكين","غياب الزلازل دائمًا"],"answerIndex":2,"explanation":"الاندساس يرتبط بأخاديد بحرية وأقواس بركانية في سياقات كثيرة."},{"number":3,"kind":"choice","prompt":"هل تتطابق نتائج كل تصادم صفيحي؟","target":"","options":["إذا زادت الحرارة","لا","نعم","فقط إذا كان البحر قريبًا"],"answerIndex":1,"explanation":"تتوقف النتائج على أنواع الصفائح وظروفها."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «التصادم وتكوّن الجبال».","target":"","tokens":["فسر الرفع أو الاندساس","اختر التقارب","حدد نوع الصفائح"],"answer":["حدد نوع الصفائح","اختر التقارب","فسر الرفع أو الاندساس"],"explanation":"الترتيب الصحيح وفق الدرس: حدد نوع الصفائح ← اختر التقارب ← فسر الرفع أو الاندساس."},{"number":5,"kind":"type","prompt":"ما اسم دخول صفيحة تحت أخرى؟","target":"","answer":"الاندساس","explanation":"عند حدود الصفائح التقاربية قد تندس صفيحة محيطية تحت أخرى أو تصطدم قارتان فتنضغط الصخور وترتفع الجبال. سلسلة الهيمالايا نتجت من التصادم المستمر بين الصفيحتين الهندية والأوراسية."}]},{"index":4,"stage":{"title":"الصدوع والحدود التحويلية","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 5 على الصدوع والحدود التحويلية. على الحدود التحويلية تنزلق صفيحتان جانبيًا على امتداد صدوع. تتراكم الإجهادات بسبب الاحتكاك والقفل المؤقت ثم قد يتحرر جزء منها في زلزال. صدع سان أندرياس مثال معروف لحد تحويلي.","tips":["على الحدود التحويلية تنزلق صفيحتان جانبيًا على امتداد صدوع. تتراكم الإجهادات بسبب الاحتكاك والقفل المؤقت ثم قد يتحرر جزء منها في زلزال. صدع سان أندرياس مثال معروف لحد تحويلي.","غيّر نوع الحدود إلى «تحويلية» وارفع السرعة النسبية إلى 3 سم/سنة. النموذج يعرض الإزاحة الهندسية خلال فترة طويلة، ولا يحدد متى ينكسر صدع أو ما مقدار الزلزال.","ليس كل صدع حدًا بين صفيحتين كبيرتين؛ قد تنشأ صدوع داخل الصفائح. ولا يمكن التنبؤ بموعد زلزال معين من سرعة صفيحة وحدها."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"على الحدود التحويلية تنزلق صفيحتان جانبيًا على امتداد صدوع. تتراكم الإجهادات بسبب الاحتكاك والقفل المؤقت ثم قد يتحرر جزء منها في زلزال. صدع سان أندرياس مثال معروف لحد تحويلي. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"انزلاق جانبي","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"غيّر نوع الحدود إلى «تحويلية» وارفع السرعة النسبية إلى 3 سم/سنة. النموذج يعرض الإزاحة الهندسية خلال فترة طويلة، ولا يحدد متى ينكسر صدع أو ما مقدار الزلزال. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد نوع الصدع ← اختر الانزلاق ← افحص تراكم الإجهاد","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"الحدود التحويلية تتميز بحركة انزلاقية أفقية نسبية. صدع سان أندرياس يربط أجزاء من حدود صفائح في كاليفورنيا. يسمح الاحتكاك بتراكم إجهاد مرن قبل بعض الانزلاقات الزلزالية. لا تتوافر وسيلة موثوقة لتوقع وقت ومكان ومقدار زلزال معين. ليس كل صدع حدًا بين صفيحتين كبيرتين؛ قد تنشأ صدوع داخل الصفائح. ولا يمكن التنبؤ بموعد زلزال معين من سرعة صفيحة وحدها. خطوات التحليل: حدد نوع الصدع ← اختر الانزلاق ← افحص تراكم الإجهاد. المصطلح الذي تعلمته: الصدع.","example":"الصدع","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-plates","scenario":"الصدوع والحدود التحويلية"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/faqs/can-you-predict-earthquakes"}},"questions":[{"number":0,"kind":"choice","prompt":"ما نوع الحركة على حدود تحويلية؟","target":"","options":["تباعد فقط","تصادم رأسي فقط","ثبات تام","انزلاق جانبي"],"answerIndex":3,"explanation":"الحدود التحويلية تتميز بحركة انزلاقية أفقية نسبية."},{"number":1,"kind":"choice","prompt":"ما المثال الشهير لحد تحويلي؟","target":"","options":["قمة إيفرست وحدها","اللب الداخلي","صدع سان أندرياس","حيد وسط الأطلسي"],"answerIndex":2,"explanation":"صدع سان أندرياس يربط أجزاء من حدود صفائح في كاليفورنيا."},{"number":2,"kind":"choice","prompt":"ما الذي قد يتراكم على صدع مقفل؟","target":"","options":["الضوء","الإجهاد","الهواء النقي","الثلج فقط"],"answerIndex":1,"explanation":"يسمح الاحتكاك بتراكم إجهاد مرن قبل بعض الانزلاقات الزلزالية."},{"number":3,"kind":"choice","prompt":"هل تحدد سرعة الصفيحة موعد زلزال دقيقًا؟","target":"","options":["لا","نعم","إذا زادت عن 5 سم","إذا كان نهارًا"],"answerIndex":0,"explanation":"لا تتوافر وسيلة موثوقة لتوقع وقت ومكان ومقدار زلزال معين."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «الصدوع والحدود التحويلية».","target":"","tokens":["افحص تراكم الإجهاد","اختر الانزلاق","حدد نوع الصدع"],"answer":["حدد نوع الصدع","اختر الانزلاق","افحص تراكم الإجهاد"],"explanation":"الترتيب الصحيح وفق الدرس: حدد نوع الصدع ← اختر الانزلاق ← افحص تراكم الإجهاد."},{"number":5,"kind":"type","prompt":"ما اسم الكسر الجيولوجي الذي يحدث عليه انزلاق؟","target":"","answer":"الصدع","explanation":"على الحدود التحويلية تنزلق صفيحتان جانبيًا على امتداد صدوع. تتراكم الإجهادات بسبب الاحتكاك والقفل المؤقت ثم قد يتحرر جزء منها في زلزال. صدع سان أندرياس مثال معروف لحد تحويلي."}]},{"index":5,"stage":{"title":"كيف يحدث الزلزال؟","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 6 على كيف يحدث الزلزال؟. الزلازل تنتج غالبًا عن انزلاق مفاجئ على صدع بعد تراكم إجهاد. يسمى الموضع الذي يبدأ عنده الكسر في العمق البؤرة، والنقطة التي فوقه على سطح الأرض المركز السطحي. تنتشر الطاقة على هيئة موجات زلزالية.","tips":["الزلازل تنتج غالبًا عن انزلاق مفاجئ على صدع بعد تراكم إجهاد. يسمى الموضع الذي يبدأ عنده الكسر في العمق البؤرة، والنقطة التي فوقه على سطح الأرض المركز السطحي. تنتشر الطاقة على هيئة موجات زلزالية.","في المحاكاة، تُرسل موجات بسرعات نموذجية ثابتة من مصدر افتراضي إلى محطة. تغيير المسافة يزيد زمن وصول الموجات، لكن هذا ليس حسابًا لوقت وقوع الزلزال القادم.","لا تخلط بين تقدير خطر زلزالي على عقود والتنبؤ بتاريخ وموقع وقوة زلزال معين. لا تستطيع أي جهة حاليًا تقديم هذا التنبؤ الدقيق علميًا."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"الزلازل تنتج غالبًا عن انزلاق مفاجئ على صدع بعد تراكم إجهاد. يسمى الموضع الذي يبدأ عنده الكسر في العمق البؤرة، والنقطة التي فوقه على سطح الأرض المركز السطحي. تنتشر الطاقة على هيئة موجات زلزالية. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"انزلاق مفاجئ على صدع","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"في المحاكاة، تُرسل موجات بسرعات نموذجية ثابتة من مصدر افتراضي إلى محطة. تغيير المسافة يزيد زمن وصول الموجات، لكن هذا ليس حسابًا لوقت وقوع الزلزال القادم. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد الصدع ← ميز البؤرة والمركز ← تتبع الموجات","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"قد يحدث الكسر عندما يتجاوز الإجهاد مقاومة الاحتكاك. البؤرة هي موضع انطلاق الكسر في العمق. المركز السطحي يقع فوق البؤرة عموديًا. لا يمكن التنبؤ الدقيق بالزمان والمكان والمقدار بالعلم الحالي. لا تخلط بين تقدير خطر زلزالي على عقود والتنبؤ بتاريخ وموقع وقوة زلزال معين. لا تستطيع أي جهة حاليًا تقديم هذا التنبؤ الدقيق علميًا. خطوات التحليل: حدد الصدع ← ميز البؤرة والمركز ← تتبع الموجات. المصطلح الذي تعلمته: البؤرة.","example":"البؤرة","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-seismic","scenario":"كيف يحدث الزلزال؟"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes"}},"questions":[{"number":0,"kind":"choice","prompt":"ما مصدر معظم الزلازل التكتونية؟","target":"","options":["تساقط أوراق الشجر","تعاقب الفصول","انزلاق مفاجئ على صدع","حركة القمر حول الشمس"],"answerIndex":2,"explanation":"قد يحدث الكسر عندما يتجاوز الإجهاد مقاومة الاحتكاك."},{"number":1,"kind":"choice","prompt":"ما اسم نقطة بدء الكسر في باطن الأرض؟","target":"","options":["حيد المحيط","البؤرة","المركز السطحي","القشرة وحدها"],"answerIndex":1,"explanation":"البؤرة هي موضع انطلاق الكسر في العمق."},{"number":2,"kind":"choice","prompt":"ما المركز السطحي للزلزال؟","target":"","options":["النقطة على السطح فوق البؤرة","اللب الداخلي","منطقة الرياح","موقع أبعد محطة"],"answerIndex":0,"explanation":"المركز السطحي يقع فوق البؤرة عموديًا."},{"number":3,"kind":"choice","prompt":"هل يمكن تعيين موعد زلزال محدد بدقة حاليًا؟","target":"","options":["نعم","إذا عرفنا السرعة","عند ظهور سحب معينة","لا"],"answerIndex":3,"explanation":"لا يمكن التنبؤ الدقيق بالزمان والمكان والمقدار بالعلم الحالي."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «كيف يحدث الزلزال؟».","target":"","tokens":["تتبع الموجات","ميز البؤرة والمركز","حدد الصدع"],"answer":["حدد الصدع","ميز البؤرة والمركز","تتبع الموجات"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الصدع ← ميز البؤرة والمركز ← تتبع الموجات."},{"number":5,"kind":"type","prompt":"ما اسم نقطة بدء الانكسار داخل الأرض؟","target":"","answer":"البؤرة","explanation":"الزلازل تنتج غالبًا عن انزلاق مفاجئ على صدع بعد تراكم إجهاد. يسمى الموضع الذي يبدأ عنده الكسر في العمق البؤرة، والنقطة التي فوقه على سطح الأرض المركز السطحي. تنتشر الطاقة على هيئة موجات زلزالية."}]},{"index":6,"stage":{"title":"الموجات الزلزالية P وS","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 7 على الموجات الزلزالية P وS. موجات P انضغاطية تنتقل في المواد الصلبة والسوائل، وتصل غالبًا قبل موجات S القصّية التي لا تنتقل خلال السوائل. الفرق بين أزمنة وصول الموجتين يساعد على تقدير المسافة إلى مصدر الزلزال.","tips":["موجات P انضغاطية تنتقل في المواد الصلبة والسوائل، وتصل غالبًا قبل موجات S القصّية التي لا تنتقل خلال السوائل. الفرق بين أزمنة وصول الموجتين يساعد على تقدير المسافة إلى مصدر الزلزال.","في نموذج افتراضي بسرعتين ثابتتين P=6 كم/ث وS=3.5 كم/ث، تستغرق P نحو 100 ثانية لقطع 600 كم، بينما تستغرق S نحو 171 ثانية. الفرق قرابة 71 ثانية.","تتغير السرعات الحقيقية مع نوع الصخور والعمق وتُحسب المسارات الزلزالية بمنحنيات زمن السفر، لا بسرعتين ثابتتين في جميع أنحاء الأرض. المختبر للتعلم فقط."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"موجات P انضغاطية تنتقل في المواد الصلبة والسوائل، وتصل غالبًا قبل موجات S القصّية التي لا تنتقل خلال السوائل. الفرق بين أزمنة وصول الموجتين يساعد على تقدير المسافة إلى مصدر الزلزال. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"موجة P","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"في نموذج افتراضي بسرعتين ثابتتين P=6 كم/ث وS=3.5 كم/ث، تستغرق P نحو 100 ثانية لقطع 600 كم، بينما تستغرق S نحو 171 ثانية. الفرق قرابة 71 ثانية. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد المسافة ← احسب وصول P ← قارن وصول S","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"موجات P أسرع عادة من S في كثير من مواد الأرض. موجات S القصّية لا تنتشر في السوائل. الزمن التقريبي يساوي المسافة مقسومة على السرعة: 600÷6=100. تختلف السرعات حسب تركيب الوسط وعمقه. تتغير السرعات الحقيقية مع نوع الصخور والعمق وتُحسب المسارات الزلزالية بمنحنيات زمن السفر، لا بسرعتين ثابتتين في جميع أنحاء الأرض. المختبر للتعلم فقط. خطوات التحليل: حدد المسافة ← احسب وصول P ← قارن وصول S. المصطلح الذي تعلمته: S.","example":"موجة S","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-seismic","scenario":"الموجات الزلزالية P وS"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards/science-earthquakes"}},"questions":[{"number":0,"kind":"choice","prompt":"أي الموجات تصل غالبًا أولًا؟","target":"","options":["لا توجد موجات","P","S","كلاهما دائمًا معًا"],"answerIndex":1,"explanation":"موجات P أسرع عادة من S في كثير من مواد الأرض."},{"number":1,"kind":"choice","prompt":"أي موجات لا تمر عبر السوائل؟","target":"","options":["S","P","موجات الصوت في الهواء فقط","الضوء"],"answerIndex":0,"explanation":"موجات S القصّية لا تنتشر في السوائل."},{"number":2,"kind":"choice","prompt":"كم تستغرق موجة P بسرعة 6 كم/ث لمسافة 600 كم؟","target":"","options":["600 ثانية","10 ثوان","350 ثانية","100 ثانية"],"answerIndex":3,"explanation":"الزمن التقريبي يساوي المسافة مقسومة على السرعة: 600÷6=100."},{"number":3,"kind":"choice","prompt":"هل سرعة الموجات ثابتة في جميع طبقات الأرض؟","target":"","options":["إذا كان الزلزال عميقًا","فقط في المحيط","لا","نعم"],"answerIndex":2,"explanation":"تختلف السرعات حسب تركيب الوسط وعمقه."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «الموجات الزلزالية P وS».","target":"","tokens":["قارن وصول S","احسب وصول P","حدد المسافة"],"answer":["حدد المسافة","احسب وصول P","قارن وصول S"],"explanation":"الترتيب الصحيح وفق الدرس: حدد المسافة ← احسب وصول P ← قارن وصول S."},{"number":5,"kind":"type","prompt":"ما اسم الموجة القصية التي لا تنتشر في السوائل؟","target":"","answer":"S","explanation":"موجات P انضغاطية تنتقل في المواد الصلبة والسوائل، وتصل غالبًا قبل موجات S القصّية التي لا تنتقل خلال السوائل. الفرق بين أزمنة وصول الموجتين يساعد على تقدير المسافة إلى مصدر الزلزال."}]},{"index":7,"stage":{"title":"كيف تنشأ البراكين؟","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 8 على كيف تنشأ البراكين؟. تنشأ البراكين حين تصل الصهارة إلى السطح بطرق تتأثر ببيئة الصفائح وتركيب الصهارة والغازات والضغط. قد تكون الانفجارات هادئة نسبيًا أو عنيفة، وتؤثر لزوجة الصهارة والغازات في سلوكها.","tips":["تنشأ البراكين حين تصل الصهارة إلى السطح بطرق تتأثر ببيئة الصفائح وتركيب الصهارة والغازات والضغط. قد تكون الانفجارات هادئة نسبيًا أو عنيفة، وتؤثر لزوجة الصهارة والغازات في سلوكها.","صهارة أغنى بالسيليكا تكون غالبًا أعلى لزوجة عند ظروف متشابهة، ما قد يجعل خروج الغازات أصعب؛ لكن شدة الثوران لا تُحسب من نسبة السيليكا والغاز وحدهما.","المختبر يرسم مؤشرًا تعليميًا نوعيًا، ولا يتنبأ بانفجار بركاني حقيقي. وتتغير اللزوجة أيضًا مع الحرارة والبلورات والماء وعوامل أخرى."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"تنشأ البراكين حين تصل الصهارة إلى السطح بطرق تتأثر ببيئة الصفائح وتركيب الصهارة والغازات والضغط. قد تكون الانفجارات هادئة نسبيًا أو عنيفة، وتؤثر لزوجة الصهارة والغازات في سلوكها. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"الصهارة","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"صهارة أغنى بالسيليكا تكون غالبًا أعلى لزوجة عند ظروف متشابهة، ما قد يجعل خروج الغازات أصعب؛ لكن شدة الثوران لا تُحسب من نسبة السيليكا والغاز وحدهما. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد تركيب الصهارة ← افحص الغازات ← قارن السلوك المحتمل","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"الصهارة مادة صخرية منصهرة تحت السطح. عندما تتدفق الصهارة على السطح تسمى حممًا أو لابة. يمكن لزيادة السيليكا أن ترفع لزوجة الصهارة في ظروف متشابهة. يتطلب رصد البراكين قياسات جيولوجية وفيزيائية متنوعة ومستمرة. المختبر يرسم مؤشرًا تعليميًا نوعيًا، ولا يتنبأ بانفجار بركاني حقيقي. وتتغير اللزوجة أيضًا مع الحرارة والبلورات والماء وعوامل أخرى. خطوات التحليل: حدد تركيب الصهارة ← افحص الغازات ← قارن السلوك المحتمل. المصطلح الذي تعلمته: الصهارة.","example":"الصهارة","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-volcano","scenario":"كيف تنشأ البراكين؟"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/VHP"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا تسمى الصخور المنصهرة تحت السطح؟","target":"","options":["الصهارة","الحمم على السطح","الوشاح بأكمله","الرماد فقط"],"answerIndex":0,"explanation":"الصهارة مادة صخرية منصهرة تحت السطح."},{"number":1,"kind":"choice","prompt":"ما اسم الصهارة بعد خروجها إلى السطح؟","target":"","options":["اللب الداخلي","المياه الجوفية","السحب","الحمم البركانية"],"answerIndex":3,"explanation":"عندما تتدفق الصهارة على السطح تسمى حممًا أو لابة."},{"number":2,"kind":"choice","prompt":"ماذا يحدث غالبًا للزوجة إذا زادت السيليكا مع ثبات الظروف الأخرى؟","target":"","options":["تتحول إلى جليد","لا علاقة أبدًا","ترتفع","تنعدم"],"answerIndex":2,"explanation":"يمكن لزيادة السيليكا أن ترفع لزوجة الصهارة في ظروف متشابهة."},{"number":3,"kind":"choice","prompt":"هل يتنبأ هذا المختبر بوقت ثوران بركان؟","target":"","options":["إذا انخفض الضغط","لا","نعم","إذا زادت الغازات"],"answerIndex":1,"explanation":"يتطلب رصد البراكين قياسات جيولوجية وفيزيائية متنوعة ومستمرة."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «كيف تنشأ البراكين؟».","target":"","tokens":["قارن السلوك المحتمل","افحص الغازات","حدد تركيب الصهارة"],"answer":["حدد تركيب الصهارة","افحص الغازات","قارن السلوك المحتمل"],"explanation":"الترتيب الصحيح وفق الدرس: حدد تركيب الصهارة ← افحص الغازات ← قارن السلوك المحتمل."},{"number":5,"kind":"type","prompt":"ما اسم الصخر المنصهر تحت سطح الأرض؟","target":"","answer":"الصهارة","explanation":"تنشأ البراكين حين تصل الصهارة إلى السطح بطرق تتأثر ببيئة الصفائح وتركيب الصهارة والغازات والضغط. قد تكون الانفجارات هادئة نسبيًا أو عنيفة، وتؤثر لزوجة الصهارة والغازات في سلوكها."}]},{"index":8,"stage":{"title":"تكوّن السلاسل الجبلية","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 9 على تكوّن السلاسل الجبلية. قد تتكون السلاسل الجبلية من تصادم الصفائح وضغط القشرة وتثخينها وارتفاعها، كما تسهم الاندساس والبراكين والصدوع في أشكال مختلفة من التضاريس. ليست جميع الجبال نتيجة تصادم قاري مباشر.","tips":["قد تتكون السلاسل الجبلية من تصادم الصفائح وضغط القشرة وتثخينها وارتفاعها، كما تسهم الاندساس والبراكين والصدوع في أشكال مختلفة من التضاريس. ليست جميع الجبال نتيجة تصادم قاري مباشر.","تُعد الهيمالايا مثالًا على انضغاط القشرة وتصادم الهند وأوراسيا. يمكن تجربة التقارب في المختبر ومقارنة رفع الجبال بالانخفاض المرتبط بالاندساس المحيطي.","التضاريس تتأثر أيضًا بالتعرية والزمن الجيولوجي وتوازن القشرة. لا يحسب النموذج ارتفاع جبل حقيقي من السرعة السنوية وحدها."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"قد تتكون السلاسل الجبلية من تصادم الصفائح وضغط القشرة وتثخينها وارتفاعها، كما تسهم الاندساس والبراكين والصدوع في أشكال مختلفة من التضاريس. ليست جميع الجبال نتيجة تصادم قاري مباشر. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"تصادم صفائح قارية","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"تُعد الهيمالايا مثالًا على انضغاط القشرة وتصادم الهند وأوراسيا. يمكن تجربة التقارب في المختبر ومقارنة رفع الجبال بالانخفاض المرتبط بالاندساس المحيطي. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد نوع الحدود ← فسر الرفع ← افحص أثر التعرية","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"التصادم الهندي الأوراسي يضغط القشرة ويرفع الهيمالايا. توجد جبال بركانية وصدعية وأنواع أخرى. تساهم التعرية في نحت الجبال ونقل المواد. الارتفاع يعتمد على بنية القشرة والتوازن والتعرية وعوامل متعددة. التضاريس تتأثر أيضًا بالتعرية والزمن الجيولوجي وتوازن القشرة. لا يحسب النموذج ارتفاع جبل حقيقي من السرعة السنوية وحدها. خطوات التحليل: حدد نوع الحدود ← فسر الرفع ← افحص أثر التعرية. المصطلح الذي تعلمته: الهيمالايا.","example":"الهيمالايا","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-plates","scenario":"تكوّن السلاسل الجبلية"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards"}},"questions":[{"number":0,"kind":"choice","prompt":"ما العملية الأساسية المرتبطة بنمو الهيمالايا؟","target":"","options":["تباعد صفحات ورقية","كسوف الشمس","دوران القمر","تصادم صفائح قارية"],"answerIndex":3,"explanation":"التصادم الهندي الأوراسي يضغط القشرة ويرفع الهيمالايا."},{"number":1,"kind":"choice","prompt":"هل كل الجبال نتيجة تصادم قاري مباشر؟","target":"","options":["إذا زادت الأمطار","إذا كان المناخ باردًا","لا","نعم"],"answerIndex":2,"explanation":"توجد جبال بركانية وصدعية وأنواع أخرى."},{"number":2,"kind":"choice","prompt":"ما عملية تهدم الصخور التي تخفض التضاريس عبر الزمن؟","target":"","options":["التمدد الكوني","التعرية","الاندماج النووي","التكاثف"],"answerIndex":1,"explanation":"تساهم التعرية في نحت الجبال ونقل المواد."},{"number":3,"kind":"choice","prompt":"هل تحسب السرعة السنوية وحدها ارتفاع جبل؟","target":"","options":["لا","نعم","إذا كان الجبل صخريًا","إذا كان في قارة"],"answerIndex":0,"explanation":"الارتفاع يعتمد على بنية القشرة والتوازن والتعرية وعوامل متعددة."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «تكوّن السلاسل الجبلية».","target":"","tokens":["افحص أثر التعرية","فسر الرفع","حدد نوع الحدود"],"answer":["حدد نوع الحدود","فسر الرفع","افحص أثر التعرية"],"explanation":"الترتيب الصحيح وفق الدرس: حدد نوع الحدود ← فسر الرفع ← افحص أثر التعرية."},{"number":5,"kind":"type","prompt":"ما أشهر سلسلة جبلية نتجت من تصادم الهند وأوراسيا؟","target":"","answer":"الهيمالايا","explanation":"قد تتكون السلاسل الجبلية من تصادم الصفائح وضغط القشرة وتثخينها وارتفاعها، كما تسهم الاندساس والبراكين والصدوع في أشكال مختلفة من التضاريس. ليست جميع الجبال نتيجة تصادم قاري مباشر."}]},{"index":9,"stage":{"title":"دورة الصخور والمعادن","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 10 على دورة الصخور والمعادن. تنقسم الصخور في التصنيف الأساسي إلى نارية ورسوبية ومتحولة. تتشكل النارية من تبرد الصهارة أو الحمم، والرسوبية من تراكم الرواسب وتحجرها أو ترسيب مواد، والمتحولة بتغير صخر موجود بفعل الحرارة والضغط دون انصهاره الكامل.","tips":["تنقسم الصخور في التصنيف الأساسي إلى نارية ورسوبية ومتحولة. تتشكل النارية من تبرد الصهارة أو الحمم، والرسوبية من تراكم الرواسب وتحجرها أو ترسيب مواد، والمتحولة بتغير صخر موجود بفعل الحرارة والضغط دون انصهاره الكامل.","يمكن للصخر الناري أن يتجوى إلى رواسب ثم يتكون صخر رسوبي؛ ويمكن لصخر رسوبي أن يتحول تحت ضغط وحرارة إلى متحول. ليست هذه دورة إلزامية بترتيب واحد لجميع الصخور.","لا تخلط المعادن بالصخور: المعدن مادة طبيعية صلبة ذات تركيب وبنية محددين وفق التعريف الجيولوجي، والصخر مجموعة من المعادن أو مواد معدنية."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"تنقسم الصخور في التصنيف الأساسي إلى نارية ورسوبية ومتحولة. تتشكل النارية من تبرد الصهارة أو الحمم، والرسوبية من تراكم الرواسب وتحجرها أو ترسيب مواد، والمتحولة بتغير صخر موجود بفعل الحرارة والضغط دون انصهاره الكامل. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"النارية","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"يمكن للصخر الناري أن يتجوى إلى رواسب ثم يتكون صخر رسوبي؛ ويمكن لصخر رسوبي أن يتحول تحت ضغط وحرارة إلى متحول. ليست هذه دورة إلزامية بترتيب واحد لجميع الصخور. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد الصخر ← اختر العملية ← اعرف الناتج","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"تتشكل الصخور النارية من تبريد مواد منصهرة. التحول يعيد تركيب الصخور تحت حرارة وضغط. يمكن أن يسلك الصخر مسارات متعددة بين الأنواع. الصخر قد يتكون من مجموعة معادن أو مواد أخرى. لا تخلط المعادن بالصخور: المعدن مادة طبيعية صلبة ذات تركيب وبنية محددين وفق التعريف الجيولوجي، والصخر مجموعة من المعادن أو مواد معدنية. خطوات التحليل: حدد الصخر ← اختر العملية ← اعرف الناتج. المصطلح الذي تعلمته: النارية.","example":"النارية","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-rocks","scenario":"دورة الصخور والمعادن"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/special-topics/water-science-school"}},"questions":[{"number":0,"kind":"choice","prompt":"أي الصخور تنشأ من تبرد الصهارة؟","target":"","options":["المتحولة","كل الصخور بلا فرق","النارية","الرسوبية"],"answerIndex":2,"explanation":"تتشكل الصخور النارية من تبريد مواد منصهرة."},{"number":1,"kind":"choice","prompt":"بماذا تتميز الصخور المتحولة؟","target":"","options":["تنمو في الشمس","تغير صخر سابق بالحرارة والضغط دون انصهار تام","تتكون من الهواء فقط","تتجمد من الماء وحده"],"answerIndex":1,"explanation":"التحول يعيد تركيب الصخور تحت حرارة وضغط."},{"number":2,"kind":"choice","prompt":"هل دورة الصخور تسلك تسلسلًا واحدًا ثابتًا؟","target":"","options":["لا","نعم دائمًا","بشكل دائري مرئي","إذا كان الصخر كبيرًا"],"answerIndex":0,"explanation":"يمكن أن يسلك الصخر مسارات متعددة بين الأنواع."},{"number":3,"kind":"choice","prompt":"ما الفرق الأساسي بين المعدن والصخر؟","target":"","options":["الصخر عنصر كيميائي واحد دائمًا","المعدن غاز فقط","لا فرق مطلقًا","الصخر قد يحتوي عدة معادن"],"answerIndex":3,"explanation":"الصخر قد يتكون من مجموعة معادن أو مواد أخرى."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «دورة الصخور والمعادن».","target":"","tokens":["اعرف الناتج","اختر العملية","حدد الصخر"],"answer":["حدد الصخر","اختر العملية","اعرف الناتج"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الصخر ← اختر العملية ← اعرف الناتج."},{"number":5,"kind":"type","prompt":"ما اسم الصخور الناتجة من تبرد الصهارة؟","target":"","answer":"النارية","explanation":"تنقسم الصخور في التصنيف الأساسي إلى نارية ورسوبية ومتحولة. تتشكل النارية من تبرد الصهارة أو الحمم، والرسوبية من تراكم الرواسب وتحجرها أو ترسيب مواد، والمتحولة بتغير صخر موجود بفعل الحرارة والضغط دون انصهاره الكامل."}]},{"index":10,"stage":{"title":"التجوية والتعرية","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 11 على التجوية والتعرية. التجوية تكسر الصخور أو تغير تركيبها في مكانها، بينما تنقل التعرية المواد بواسطة الماء أو الرياح أو الجليد والجاذبية. وتتراكم الرواسب في مواضع مختلفة لتشكل تضاريس وأحيانًا صخورًا رسوبية.","tips":["التجوية تكسر الصخور أو تغير تركيبها في مكانها، بينما تنقل التعرية المواد بواسطة الماء أو الرياح أو الجليد والجاذبية. وتتراكم الرواسب في مواضع مختلفة لتشكل تضاريس وأحيانًا صخورًا رسوبية.","يمكن أن تتشقق صخرة بفعل تمدد وتجمد الماء داخلها؛ هذه تجوية. وإذا حملت المياه الفتات بعيدًا فهو تعرية ونقل. ثم قد يحدث ترسيب عندما تقل قدرة الوسط على الحمل.","لا تخلط سرعة حركة الرياح مع الزمن الجيولوجي اللازم لنحت تضاريس كبيرة. النموذج يوضح تسلسل العمليات ولا يحسب معدل تآكل حقيقي."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"التجوية تكسر الصخور أو تغير تركيبها في مكانها، بينما تنقل التعرية المواد بواسطة الماء أو الرياح أو الجليد والجاذبية. وتتراكم الرواسب في مواضع مختلفة لتشكل تضاريس وأحيانًا صخورًا رسوبية. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"تفتت أو تغير الصخر في مكانه","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"يمكن أن تتشقق صخرة بفعل تمدد وتجمد الماء داخلها؛ هذه تجوية. وإذا حملت المياه الفتات بعيدًا فهو تعرية ونقل. ثم قد يحدث ترسيب عندما تقل قدرة الوسط على الحمل. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"حدد التجوية ← تتبع النقل ← حدد الترسيب","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"التجوية تُضعف وتفكك الصخور أو تغيرها في موقعها. التعرية تشمل إزالة ونقل المواد بالماء أو الرياح أو غيرهما. تترسب المواد عندما لا يبقى الوسط قادرًا على نقلها. الماء والرياح من عوامل النقل والتعرية. لا تخلط سرعة حركة الرياح مع الزمن الجيولوجي اللازم لنحت تضاريس كبيرة. النموذج يوضح تسلسل العمليات ولا يحسب معدل تآكل حقيقي. خطوات التحليل: حدد التجوية ← تتبع النقل ← حدد الترسيب. المصطلح الذي تعلمته: التعرية.","example":"التعرية","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-rocks","scenario":"التجوية والتعرية"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/water-resources"}},"questions":[{"number":0,"kind":"choice","prompt":"ما التجوية؟","target":"","options":["حركة القمر","تفتت أو تغير الصخر في مكانه","انتقال الرواسب بعيدًا دائمًا","اندماج الشمس"],"answerIndex":1,"explanation":"التجوية تُضعف وتفكك الصخور أو تغيرها في موقعها."},{"number":1,"kind":"choice","prompt":"ما التعرية؟","target":"","options":["نقل المواد بعد تفككها","انصهار جميع المعادن","تبخر الصخور كلها","إضاءة الشمس"],"answerIndex":0,"explanation":"التعرية تشمل إزالة ونقل المواد بالماء أو الرياح أو غيرهما."},{"number":2,"kind":"choice","prompt":"متى يحدث الترسيب غالبًا؟","target":"","options":["عند زيادة سرعة الرياح دائمًا","عند اختفاء الجاذبية","عند وصول الضوء","عندما تقل قدرة الوسط على حمل الرواسب"],"answerIndex":3,"explanation":"تترسب المواد عندما لا يبقى الوسط قادرًا على نقلها."},{"number":3,"kind":"choice","prompt":"هل الماء والرياح عوامل تعرية؟","target":"","options":["فقط في الصحراء","فقط في البحر","نعم","لا"],"answerIndex":2,"explanation":"الماء والرياح من عوامل النقل والتعرية."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «التجوية والتعرية».","target":"","tokens":["حدد الترسيب","تتبع النقل","حدد التجوية"],"answer":["حدد التجوية","تتبع النقل","حدد الترسيب"],"explanation":"الترتيب الصحيح وفق الدرس: حدد التجوية ← تتبع النقل ← حدد الترسيب."},{"number":5,"kind":"type","prompt":"ما اسم العملية التي تنقل الرواسب؟","target":"","answer":"التعرية","explanation":"التجوية تكسر الصخور أو تغير تركيبها في مكانها، بينما تنقل التعرية المواد بواسطة الماء أو الرياح أو الجليد والجاذبية. وتتراكم الرواسب في مواضع مختلفة لتشكل تضاريس وأحيانًا صخورًا رسوبية."}]},{"index":11,"stage":{"title":"التحقيق الجيولوجي الأخير","subtitle":"افهم القوى الجيولوجية واختبرها عمليًا","intro":"نتعرف في المحطة 12 على التحقيق الجيولوجي الأخير. عند دراسة منطقة جيولوجية، يجمع الباحث خرائط الصخور والصدوع والطبقات والعمر النسبي وأدلة النشاط الزلزالي والبركاني. يكوّن تفسيرًا تاريخيًا مع ذكر عدم اليقين، ولا يحكم من مظهر واحد.","tips":["عند دراسة منطقة جيولوجية، يجمع الباحث خرائط الصخور والصدوع والطبقات والعمر النسبي وأدلة النشاط الزلزالي والبركاني. يكوّن تفسيرًا تاريخيًا مع ذكر عدم اليقين، ولا يحكم من مظهر واحد.","إذا وجدت طبقات ملتوية وصدوعًا مع حركة تقاربية، فقد تدل على ضغط قديم. اختبر نوع الحدود ثم قارن النتيجة ببيانات صخور افتراضية بدل استنتاج تاريخ كامل من شكل سهم واحد.","لا تستخدم النموذج لتحديد وقوع زلزال مستقبلي. نتائج التحقيق مشروطة بالمعطيات المتاحة والعديد من الأحداث الجيولوجية تتداخل عبر أزمنة طويلة."],"lessons":[{"title":"كيف تعمل الأرض هنا؟","body":"عند دراسة منطقة جيولوجية، يجمع الباحث خرائط الصخور والصدوع والطبقات والعمر النسبي وأدلة النشاط الزلزالي والبركاني. يكوّن تفسيرًا تاريخيًا مع ذكر عدم اليقين، ولا يحكم من مظهر واحد. قارن ما نراه على السطح بما يكشفه الاستدلال الجيولوجي عن باطن الكوكب.","example":"جمع خرائط صخور وصدوع وأدلة متعددة","note":"ابدأ بتمييز الطبقات والقوى والظواهر قبل الانتقال إلى تجربة المختبر."},{"title":"مثال جيولوجي محلول","body":"إذا وجدت طبقات ملتوية وصدوعًا مع حركة تقاربية، فقد تدل على ضغط قديم. اختبر نوع الحدود ثم قارن النتيجة ببيانات صخور افتراضية بدل استنتاج تاريخ كامل من شكل سهم واحد. جرّب تعديل متغير واحد على الأقل ثم قارن ما يتغير وما يبقى ثابتًا.","example":"اجمع الخريطة والأدلة ← اختبر نوع الحدود ← اكتب استنتاجًا مشروطًا","note":"خطوات القراءة الجيدة تبدأ بالمعطيات ثم تفسيرها وفق النظرية."},{"title":"تفسير الأدلة وحدود النموذج","body":"تفسير التاريخ الجيولوجي يحتاج مصادر أدلة متنوعة. غالبًا تنتج الطيات عن تشوه تحت ضغط. لا توجد طريقة موثوقة للتنبؤ بموعد زلزال محدد من المحاكاة. التحليل الجيولوجي يربط التفسير بحدود بياناته. لا تستخدم النموذج لتحديد وقوع زلزال مستقبلي. نتائج التحقيق مشروطة بالمعطيات المتاحة والعديد من الأحداث الجيولوجية تتداخل عبر أزمنة طويلة. خطوات التحليل: اجمع الخريطة والأدلة ← اختبر نوع الحدود ← اكتب استنتاجًا مشروطًا. المصطلح الذي تعلمته: الصدع.","example":"الصدع","note":"النموذج التعليمي لا يُصدر تنبؤات بزلازل أو براكين حقيقية."}],"lab":{"kind":"science","model":"earth-plates","scenario":"التحقيق الجيولوجي الأخير"},"source":{"title":"USGS — مرجع جيولوجي","url":"https://www.usgs.gov/programs/earthquake-hazards"}},"questions":[{"number":0,"kind":"choice","prompt":"ما أفضل طريقة لاستنتاج تاريخ منطقة جيولوجية؟","target":"","options":["جمع خرائط صخور وصدوع وأدلة متعددة","صورة واحدة فقط","درجة حرارة اليوم","رأي بلا بيانات"],"answerIndex":0,"explanation":"تفسير التاريخ الجيولوجي يحتاج مصادر أدلة متنوعة."},{"number":1,"kind":"choice","prompt":"ماذا قد تدل طبقات ملتوية على نحو واضح؟","target":"","options":["انعدام القوى","عدم وجود صخور","كسوف قديم حتمًا","ضغط وتشوه تكتوني"],"answerIndex":3,"explanation":"غالبًا تنتج الطيات عن تشوه تحت ضغط."},{"number":2,"kind":"choice","prompt":"هل يمكن معرفة تاريخ زلزال قادم من هذا المختبر؟","target":"","options":["إذا اخترنا حدًا تحويليًا","إذا طال الوقت","لا","نعم"],"answerIndex":2,"explanation":"لا توجد طريقة موثوقة للتنبؤ بموعد زلزال محدد من المحاكاة."},{"number":3,"kind":"choice","prompt":"كيف تعرض نتيجة فيها عدم يقين؟","target":"","options":["كعنوان مخيف","كاستنتاج مشروط بالأدلة","كحقيقة نهائية دون مصادر","بإخفاء المعطيات"],"answerIndex":1,"explanation":"التحليل الجيولوجي يربط التفسير بحدود بياناته."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «التحقيق الجيولوجي الأخير».","target":"","tokens":["اكتب استنتاجًا مشروطًا","اختبر نوع الحدود","اجمع الخريطة والأدلة"],"answer":["اجمع الخريطة والأدلة","اختبر نوع الحدود","اكتب استنتاجًا مشروطًا"],"explanation":"الترتيب الصحيح وفق الدرس: اجمع الخريطة والأدلة ← اختبر نوع الحدود ← اكتب استنتاجًا مشروطًا."},{"number":5,"kind":"type","prompt":"ما الاسم العلمي لكسر الصخور المصحوب بإزاحة؟","target":"","answer":"الصدع","explanation":"عند دراسة منطقة جيولوجية، يجمع الباحث خرائط الصخور والصدوع والطبقات والعمر النسبي وأدلة النشاط الزلزالي والبركاني. يكوّن تفسيرًا تاريخيًا مع ذكر عدم اليقين، ولا يحكم من مظهر واحد."}]}]},{"slug":"universe-mysteries","course":{"title":"أسرار الكون","description":"من المقاييس الكونية والنجوم والمجرات إلى الثقوب السوداء والكواكب الخارجية وتمدد الكون، عبر 12 محطة ومختبرات.","category":"الفلك والطبيعة"},"stages":[{"index":0,"stage":{"title":"حجم الكون المرصود","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم حجم الكون المرصود. الكون المرصود هو الجزء الذي وصلنا ضوءه أو إشاراته منذ مراحل الكون الأولى. لا يعني حد الكون المرصود وجود جدار أو نهاية مؤكدة للكون كله؛ فالمسافات الكونية هائلة، وتحتاج وحدات مثل السنة الضوئية والفرسخ الفلكي.","tips":["الكون المرصود هو الجزء الذي وصلنا ضوءه أو إشاراته منذ مراحل الكون الأولى. لا يعني حد الكون المرصود وجود جدار أو نهاية مؤكدة للكون كله؛ فالمسافات الكونية هائلة، وتحتاج وحدات مثل السنة الضوئية والفرسخ الفلكي.","تقع الشمس على بعد نحو 8 دقائق ضوئية من الأرض، وأقرب النجوم بعد الشمس يبعد أكثر من أربع سنوات ضوئية. ليس هذا فرقًا طفيفًا؛ فالانتقال من النظام الشمسي إلى النجوم قفزة ضخمة في المقاييس.","لا تخلط بين عمر الكون نحو 13.8 مليار سنة ونصف قطر الكون المرصود نحو 46 مليار سنة ضوئية؛ تمدد الفضاء يفسر الفرق. مختبر المسافات يستعمل أمثلة ثابتة تقريبية، ولا يحسب حد الكون بنفسه."],"lessons":[{"title":"المبدأ الفلكي","body":"الكون المرصود هو الجزء الذي وصلنا ضوءه أو إشاراته منذ مراحل الكون الأولى. لا يعني حد الكون المرصود وجود جدار أو نهاية مؤكدة للكون كله؛ فالمسافات الكونية هائلة، وتحتاج وحدات مثل السنة الضوئية والفرسخ الفلكي. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"ما تمكنت إشاراته من الوصول إلينا","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"تقع الشمس على بعد نحو 8 دقائق ضوئية من الأرض، وأقرب النجوم بعد الشمس يبعد أكثر من أربع سنوات ضوئية. ليس هذا فرقًا طفيفًا؛ فالانتقال من النظام الشمسي إلى النجوم قفزة ضخمة في المقاييس. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"ابدأ بالأرض ← وسع المقياس للنجوم ← قارن المجرات","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"هو المنطقة التي يمكن رصد إشارات منها من خلال تاريخ الكون. أفق الرصد ليس بالضرورة حدًا ماديًا للكون كله. السنة الضوئية مسافة يقطعها الضوء في عام. تشير قياسات الخلفية الكونية والتمدد إلى عمر يقارب 13.8 مليار سنة. لا تخلط بين عمر الكون نحو 13.8 مليار سنة ونصف قطر الكون المرصود نحو 46 مليار سنة ضوئية؛ تمدد الفضاء يفسر الفرق. مختبر المسافات يستعمل أمثلة ثابتة تقريبية، ولا يحسب حد الكون بنفسه. خطوات الحل: ابدأ بالأرض ← وسع المقياس للنجوم ← قارن المجرات. المصطلح الذي تعلمته: الكون المرصود.","example":"الكون المرصود","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-scale","scenario":"حجم الكون المرصود"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا يعني الكون المرصود؟","target":"","options":["كل الكون دون استثناء","المجموعة الشمسية وحدها","الجزء غير المضيء فقط","ما تمكنت إشاراته من الوصول إلينا"],"answerIndex":3,"explanation":"هو المنطقة التي يمكن رصد إشارات منها من خلال تاريخ الكون."},{"number":1,"kind":"choice","prompt":"هل حد الكون المرصود دليل على جدار للكون؟","target":"","options":["إذا كان كرويًا","إذا كان مظلمًا","لا","نعم"],"answerIndex":2,"explanation":"أفق الرصد ليس بالضرورة حدًا ماديًا للكون كله."},{"number":2,"kind":"choice","prompt":"ما الوحدة المناسبة للمسافات بين النجوم؟","target":"","options":["البوصة وحدها","السنة الضوئية","السنتيمتر فقط","الساعة الحرارية"],"answerIndex":1,"explanation":"السنة الضوئية مسافة يقطعها الضوء في عام."},{"number":3,"kind":"choice","prompt":"ما عمر الكون التقريبي في النموذج الكوني السائد؟","target":"","options":["13.8 مليار سنة","13.8 مليون سنة","مليار يوم","100 ألف سنة"],"answerIndex":0,"explanation":"تشير قياسات الخلفية الكونية والتمدد إلى عمر يقارب 13.8 مليار سنة."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «حجم الكون المرصود».","target":"","tokens":["قارن المجرات","وسع المقياس للنجوم","ابدأ بالأرض"],"answer":["ابدأ بالأرض","وسع المقياس للنجوم","قارن المجرات"],"explanation":"الترتيب الصحيح وفق الدرس: ابدأ بالأرض ← وسع المقياس للنجوم ← قارن المجرات."},{"number":5,"kind":"type","prompt":"ما اسم الجزء الذي نستطيع تلقي إشاراته من الكون؟","target":"","answer":"الكون المرصود","explanation":"الكون المرصود هو الجزء الذي وصلنا ضوءه أو إشاراته منذ مراحل الكون الأولى. لا يعني حد الكون المرصود وجود جدار أو نهاية مؤكدة للكون كله؛ فالمسافات الكونية هائلة، وتحتاج وحدات مثل السنة الضوئية والفرسخ الفلكي."}]},{"index":1,"stage":{"title":"الضوء والزمن والمسافات","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم الضوء والزمن والمسافات. تُعرّف السنة الضوئية بأنها المسافة التي يقطعها الضوء في الفراغ خلال سنة، وتساوي قرابة 9.46 تريليون كيلومتر. النظر إلى جسم يبعد سنة ضوئية واحدة يعني رؤية الضوء الذي غادره منذ نحو سنة، ضمن وصف مبسط للفضاء القريب.","tips":["تُعرّف السنة الضوئية بأنها المسافة التي يقطعها الضوء في الفراغ خلال سنة، وتساوي قرابة 9.46 تريليون كيلومتر. النظر إلى جسم يبعد سنة ضوئية واحدة يعني رؤية الضوء الذي غادره منذ نحو سنة، ضمن وصف مبسط للفضاء القريب.","عندما ترى الشمس فأنت ترى حالتها قبل نحو 8 دقائق و20 ثانية؛ وعند رصد نجم يبعد 4 سنوات ضوئية تراه كما كان عندما انطلق الضوء قبل 4 سنوات.","لا تخلط بين السنة الضوئية ووحدة زمنية في الأساس؛ هي وحدة مسافة. عند المسافات الكونية الكبيرة جدًا يؤثر تمدد الكون في تفسير أزمنة السفر والمسافات."],"lessons":[{"title":"المبدأ الفلكي","body":"تُعرّف السنة الضوئية بأنها المسافة التي يقطعها الضوء في الفراغ خلال سنة، وتساوي قرابة 9.46 تريليون كيلومتر. النظر إلى جسم يبعد سنة ضوئية واحدة يعني رؤية الضوء الذي غادره منذ نحو سنة، ضمن وصف مبسط للفضاء القريب. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"وحدة مسافة","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"عندما ترى الشمس فأنت ترى حالتها قبل نحو 8 دقائق و20 ثانية؛ وعند رصد نجم يبعد 4 سنوات ضوئية تراه كما كان عندما انطلق الضوء قبل 4 سنوات. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد الجسم ← اقرأ المسافة ← فسر زمن الضوء","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"السنة الضوئية هي المسافة التي يقطعها الضوء خلال سنة في الفراغ. السنة الضوئية تقارب 9.46 × 10^12 كيلومترًا. يستغرق الضوء أربع سنوات تقريبًا ليقطع أربع سنوات ضوئية. ضوء الشمس يحتاج قرابة 8.3 دقائق للوصول إلى الأرض. لا تخلط بين السنة الضوئية ووحدة زمنية في الأساس؛ هي وحدة مسافة. عند المسافات الكونية الكبيرة جدًا يؤثر تمدد الكون في تفسير أزمنة السفر والمسافات. خطوات الحل: حدد الجسم ← اقرأ المسافة ← فسر زمن الضوء. المصطلح الذي تعلمته: السنة الضوئية.","example":"السنة الضوئية","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-scale","scenario":"الضوء والزمن والمسافات"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما السنة الضوئية؟","target":"","options":["كتلة نجم","قيمة حرارة","وحدة مسافة","وحدة زمن فقط"],"answerIndex":2,"explanation":"السنة الضوئية هي المسافة التي يقطعها الضوء خلال سنة في الفراغ."},{"number":1,"kind":"choice","prompt":"كم كيلومترًا في سنة ضوئية تقريبًا؟","target":"","options":["150 مليون كم","9.46 تريليون كم","946 كم","9.46 مليون كم"],"answerIndex":1,"explanation":"السنة الضوئية تقارب 9.46 × 10^12 كيلومترًا."},{"number":2,"kind":"choice","prompt":"ماذا نرى عند رصد نجم يبعد أربع سنوات ضوئية؟","target":"","options":["ضوءه الذي انطلق قبل أربع سنوات تقريبًا","حالته اللحظية بالتأكيد","صورة من المستقبل","ضوء الشمس فقط"],"answerIndex":0,"explanation":"يستغرق الضوء أربع سنوات تقريبًا ليقطع أربع سنوات ضوئية."},{"number":3,"kind":"choice","prompt":"كم يستغرق ضوء الشمس للوصول إلى الأرض؟","target":"","options":["سنة كاملة","ثانية واحدة","24 ساعة","نحو 8 دقائق و20 ثانية"],"answerIndex":3,"explanation":"ضوء الشمس يحتاج قرابة 8.3 دقائق للوصول إلى الأرض."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «الضوء والزمن والمسافات».","target":"","tokens":["فسر زمن الضوء","اقرأ المسافة","حدد الجسم"],"answer":["حدد الجسم","اقرأ المسافة","فسر زمن الضوء"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الجسم ← اقرأ المسافة ← فسر زمن الضوء."},{"number":5,"kind":"type","prompt":"ما اسم وحدة المسافة التي يقطعها الضوء في عام؟","target":"","answer":"السنة الضوئية","explanation":"تُعرّف السنة الضوئية بأنها المسافة التي يقطعها الضوء في الفراغ خلال سنة، وتساوي قرابة 9.46 تريليون كيلومتر. النظر إلى جسم يبعد سنة ضوئية واحدة يعني رؤية الضوء الذي غادره منذ نحو سنة، ضمن وصف مبسط للفضاء القريب."}]},{"index":2,"stage":{"title":"المجرات ودرب التبانة","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم المجرات ودرب التبانة. المجرة تجمع هائل من النجوم والغاز والغبار والمادة المظلمة مرتبط بالجاذبية. تنتمي الشمس إلى مجرة درب التبانة وهي مجرة حلزونية قضيبية، وتقع شمسنا في منطقة تُعرف بنتوء الجبار قرب أحد أذرعها.","tips":["المجرة تجمع هائل من النجوم والغاز والغبار والمادة المظلمة مرتبط بالجاذبية. تنتمي الشمس إلى مجرة درب التبانة وهي مجرة حلزونية قضيبية، وتقع شمسنا في منطقة تُعرف بنتوء الجبار قرب أحد أذرعها.","قطر قرص درب التبانة من رتبة مئة ألف سنة ضوئية، أي إن عبوره بالضوء يحتاج نحو مئة ألف سنة تقريبًا. ومجرة المرأة المسلسلة جارة كبيرة لدرب التبانة تبعد نحو 2.5 مليون سنة ضوئية.","الأرقام الكونية تعتمد على طريقة تحديد حدود الأقراص والهالات. لا ترسم كل المجرات بحجم متساوٍ أو تفترض أن النجوم تصطدم بكثرة لمجرد تقارب رسمها."],"lessons":[{"title":"المبدأ الفلكي","body":"المجرة تجمع هائل من النجوم والغاز والغبار والمادة المظلمة مرتبط بالجاذبية. تنتمي الشمس إلى مجرة درب التبانة وهي مجرة حلزونية قضيبية، وتقع شمسنا في منطقة تُعرف بنتوء الجبار قرب أحد أذرعها. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"درب التبانة","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"قطر قرص درب التبانة من رتبة مئة ألف سنة ضوئية، أي إن عبوره بالضوء يحتاج نحو مئة ألف سنة تقريبًا. ومجرة المرأة المسلسلة جارة كبيرة لدرب التبانة تبعد نحو 2.5 مليون سنة ضوئية. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد المجرة ← قارن حجمها ← قدر زمن الضوء","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"تقع المجموعة الشمسية ضمن درب التبانة. تصنف درب التبانة كمجرة حلزونية قضيبية. المسافة إلى مجرة المرأة المسلسلة نحو 2.5 مليون سنة ضوئية. ترتبط نجوم المجرة وغازها وغبارها ومكوناتها الأخرى بالجاذبية. الأرقام الكونية تعتمد على طريقة تحديد حدود الأقراص والهالات. لا ترسم كل المجرات بحجم متساوٍ أو تفترض أن النجوم تصطدم بكثرة لمجرد تقارب رسمها. خطوات الحل: حدد المجرة ← قارن حجمها ← قدر زمن الضوء. المصطلح الذي تعلمته: درب التبانة.","example":"درب التبانة","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-scale","scenario":"المجرات ودرب التبانة"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/galaxies/"}},"questions":[{"number":0,"kind":"choice","prompt":"إلى أي مجرة تنتمي الشمس؟","target":"","options":["مجرة المثلث","درب التبانة","المرأة المسلسلة","سحابة ماجلان الكبرى"],"answerIndex":1,"explanation":"تقع المجموعة الشمسية ضمن درب التبانة."},{"number":1,"kind":"choice","prompt":"ما الشكل العام لمجرة درب التبانة؟","target":"","options":["حلزونية قضيبية","كروية منتظمة","مربعة","حلقة فارغة تمامًا"],"answerIndex":0,"explanation":"تصنف درب التبانة كمجرة حلزونية قضيبية."},{"number":2,"kind":"choice","prompt":"كم تبعد المرأة المسلسلة عن مجرتنا تقريبًا؟","target":"","options":["8 دقائق ضوئية","وحدة فلكية واحدة","10 كيلومترات","2.5 مليون سنة ضوئية"],"answerIndex":3,"explanation":"المسافة إلى مجرة المرأة المسلسلة نحو 2.5 مليون سنة ضوئية."},{"number":3,"kind":"choice","prompt":"مم تتكون المجرة إلى جانب النجوم؟","target":"","options":["ثلج بحري","حمم بركانية","غاز وغبار ومادة مظلمة","هواء الأرض فقط"],"answerIndex":2,"explanation":"ترتبط نجوم المجرة وغازها وغبارها ومكوناتها الأخرى بالجاذبية."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «المجرات ودرب التبانة».","target":"","tokens":["قدر زمن الضوء","قارن حجمها","حدد المجرة"],"answer":["حدد المجرة","قارن حجمها","قدر زمن الضوء"],"explanation":"الترتيب الصحيح وفق الدرس: حدد المجرة ← قارن حجمها ← قدر زمن الضوء."},{"number":5,"kind":"type","prompt":"ما اسم مجرتنا؟","target":"","answer":"درب التبانة","explanation":"المجرة تجمع هائل من النجوم والغاز والغبار والمادة المظلمة مرتبط بالجاذبية. تنتمي الشمس إلى مجرة درب التبانة وهي مجرة حلزونية قضيبية، وتقع شمسنا في منطقة تُعرف بنتوء الجبار قرب أحد أذرعها."}]},{"index":3,"stage":{"title":"ولادة النجوم","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم ولادة النجوم. تبدأ النجوم من مناطق كثيفة في سحب غاز وغبار تنهار تحت الجاذبية. أثناء الانكماش ترتفع الحرارة والضغط في النجم الأولي؛ وعندما يتواصل اندماج الهيدروجين في اللب يستقر النجم على التسلسل الرئيسي.","tips":["تبدأ النجوم من مناطق كثيفة في سحب غاز وغبار تنهار تحت الجاذبية. أثناء الانكماش ترتفع الحرارة والضغط في النجم الأولي؛ وعندما يتواصل اندماج الهيدروجين في اللب يستقر النجم على التسلسل الرئيسي.","قد تتشكّل نجوم كثيرة داخل منطقة تشكل نجمي واحدة، لكن كتلة السحابة وتبريد الغاز والمجالات المغناطيسية والتغذية الراجعة تؤثر في النتائج. يعرض المختبر تأثير الكتلة على العمر النجمي تقريبًا.","لا يكفي أن تكون السحابة شديدة الحرارة وحدها لتنهار؛ ضغط الغاز والجاذبية والعوامل الأخرى مهمة. ومعادلة العمر في المختبر ليست محاكاة لتكوّن النجم منذ السديم."],"lessons":[{"title":"المبدأ الفلكي","body":"تبدأ النجوم من مناطق كثيفة في سحب غاز وغبار تنهار تحت الجاذبية. أثناء الانكماش ترتفع الحرارة والضغط في النجم الأولي؛ وعندما يتواصل اندماج الهيدروجين في اللب يستقر النجم على التسلسل الرئيسي. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"سحب غاز وغبار كثيفة","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"قد تتشكّل نجوم كثيرة داخل منطقة تشكل نجمي واحدة، لكن كتلة السحابة وتبريد الغاز والمجالات المغناطيسية والتغذية الراجعة تؤثر في النتائج. يعرض المختبر تأثير الكتلة على العمر النجمي تقريبًا. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد السحابة ← تتبع الانكماش ← افحص بدء الاندماج","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"تنشأ النجوم داخل مناطق كثيفة من السحب الجزيئية. تسحب الجاذبية المادة نحو المناطق الأكثر كثافة. يولّد اندماج الهيدروجين في اللب الطاقة الرئيسة للنجوم الشبيهة بالشمس. تمر الكتلة المتشكلة بمرحلة النجم الأولي قبل استقرار الاندماج الهيدروجيني. لا يكفي أن تكون السحابة شديدة الحرارة وحدها لتنهار؛ ضغط الغاز والجاذبية والعوامل الأخرى مهمة. ومعادلة العمر في المختبر ليست محاكاة لتكوّن النجم منذ السديم. خطوات الحل: حدد السحابة ← تتبع الانكماش ← افحص بدء الاندماج. المصطلح الذي تعلمته: نجم أولي.","example":"نجم أولي","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-stars","scenario":"ولادة النجوم"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/stars/"}},"questions":[{"number":0,"kind":"choice","prompt":"مم تبدأ ولادة النجوم عادة؟","target":"","options":["سحب غاز وغبار كثيفة","صخور سطح الأرض","مياه المحيط","مجال كهرومغناطيسي وحده"],"answerIndex":0,"explanation":"تنشأ النجوم داخل مناطق كثيفة من السحب الجزيئية."},{"number":1,"kind":"choice","prompt":"أي قوة تساعد على انكماش السحابة؟","target":"","options":["الانعكاس الضوئي","الرياح الأرضية","المد والجزر فقط","الجاذبية"],"answerIndex":3,"explanation":"تسحب الجاذبية المادة نحو المناطق الأكثر كثافة."},{"number":2,"kind":"choice","prompt":"ما العملية التي تدعم النجم المستقر على التسلسل الرئيسي؟","target":"","options":["انصهار الصخور","انعدام الضغط","اندماج الهيدروجين","احتراق الأكسجين الكيميائي"],"answerIndex":2,"explanation":"يولّد اندماج الهيدروجين في اللب الطاقة الرئيسة للنجوم الشبيهة بالشمس."},{"number":3,"kind":"choice","prompt":"كيف تسمى المرحلة المبكرة قبل الاستقرار على التسلسل الرئيسي؟","target":"","options":["مذنب","نجم أولي","كوكب قزم","قمر"],"answerIndex":1,"explanation":"تمر الكتلة المتشكلة بمرحلة النجم الأولي قبل استقرار الاندماج الهيدروجيني."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «ولادة النجوم».","target":"","tokens":["افحص بدء الاندماج","تتبع الانكماش","حدد السحابة"],"answer":["حدد السحابة","تتبع الانكماش","افحص بدء الاندماج"],"explanation":"الترتيب الصحيح وفق الدرس: حدد السحابة ← تتبع الانكماش ← افحص بدء الاندماج."},{"number":5,"kind":"type","prompt":"ما اسم النجم في مرحلة التكوّن قبل التسلسل الرئيسي؟","target":"","answer":"نجم أولي","explanation":"تبدأ النجوم من مناطق كثيفة في سحب غاز وغبار تنهار تحت الجاذبية. أثناء الانكماش ترتفع الحرارة والضغط في النجم الأولي؛ وعندما يتواصل اندماج الهيدروجين في اللب يستقر النجم على التسلسل الرئيسي."}]},{"index":4,"stage":{"title":"ألوان النجوم والحرارة","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم ألوان النجوم والحرارة. يرتبط لون الضوء الصادر من نجم بحرارة سطحه الفعالة في تقريب الجسم الأسود: النجوم الأكثر حرارة تميل إلى الأزرق والأبيض، والأبرد تميل إلى البرتقالي والأحمر. يتأثر الطيف أيضًا بامتصاص العناصر والخصائص الفيزيائية.","tips":["يرتبط لون الضوء الصادر من نجم بحرارة سطحه الفعالة في تقريب الجسم الأسود: النجوم الأكثر حرارة تميل إلى الأزرق والأبيض، والأبرد تميل إلى البرتقالي والأحمر. يتأثر الطيف أيضًا بامتصاص العناصر والخصائص الفيزيائية.","نجم سطحه نحو 3000 كلفن يظهر محمرًا نسبيًا، ونجم نحو 10000 كلفن يميل إلى الأبيض المزرق. يمكنك تغيير الحرارة في المختبر لرؤية تدرج لون تمثيلي لا صورة طيفية حقيقية.","لا تستخدم اللون وحده لحساب المسافة أو الكتلة بدقة، ولا تصف كل النجوم الحمراء بأنها صغيرة؛ توجد عمالقة حمراء كبيرة للغاية."],"lessons":[{"title":"المبدأ الفلكي","body":"يرتبط لون الضوء الصادر من نجم بحرارة سطحه الفعالة في تقريب الجسم الأسود: النجوم الأكثر حرارة تميل إلى الأزرق والأبيض، والأبرد تميل إلى البرتقالي والأحمر. يتأثر الطيف أيضًا بامتصاص العناصر والخصائص الفيزيائية. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"الزرقاء","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"نجم سطحه نحو 3000 كلفن يظهر محمرًا نسبيًا، ونجم نحو 10000 كلفن يميل إلى الأبيض المزرق. يمكنك تغيير الحرارة في المختبر لرؤية تدرج لون تمثيلي لا صورة طيفية حقيقية. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد درجة الحرارة ← لاحظ اللون ← راجع حدود الاستنتاج","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"اللون الأزرق يرتبط بدرجات حرارة سطحية أعلى من الأحمر في النموذج الحراري. يساعد لون النجم في تقدير حرارة سطحه الفعالة. النجوم ذات الحرارة السطحية الأقل تظهر أحمَر نسبيًا. توجد عمالقة حمراء ضخمة الحجم. لا تستخدم اللون وحده لحساب المسافة أو الكتلة بدقة، ولا تصف كل النجوم الحمراء بأنها صغيرة؛ توجد عمالقة حمراء كبيرة للغاية. خطوات الحل: حدد درجة الحرارة ← لاحظ اللون ← راجع حدود الاستنتاج. المصطلح الذي تعلمته: كلفن.","example":"كلفن","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-stars","scenario":"ألوان النجوم والحرارة"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/stars/"}},"questions":[{"number":0,"kind":"choice","prompt":"أي النجوم تكون عادة أعلى حرارة سطحية؟","target":"","options":["الحمراء","البرتقالية","جميع الألوان متساوية","الزرقاء"],"answerIndex":3,"explanation":"اللون الأزرق يرتبط بدرجات حرارة سطحية أعلى من الأحمر في النموذج الحراري."},{"number":1,"kind":"choice","prompt":"ماذا يمثل لون النجم هنا بصورة أساسية؟","target":"","options":["عدد كواكبه","عمره وحده","حرارة سطحه التقريبية","المسافة وحدها"],"answerIndex":2,"explanation":"يساعد لون النجم في تقدير حرارة سطحه الفعالة."},{"number":2,"kind":"choice","prompt":"أي حرارة أقرب إلى نجم مائل للاحمرار؟","target":"","options":["مليون كلفن للسطح","3000 كلفن","20000 كلفن","100000 كلفن"],"answerIndex":1,"explanation":"النجوم ذات الحرارة السطحية الأقل تظهر أحمَر نسبيًا."},{"number":3,"kind":"choice","prompt":"هل كل النجوم الحمراء صغيرة الحجم؟","target":"","options":["لا","نعم","إذا كانت قديمة","فقط خارج مجرتنا"],"answerIndex":0,"explanation":"توجد عمالقة حمراء ضخمة الحجم."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «ألوان النجوم والحرارة».","target":"","tokens":["راجع حدود الاستنتاج","لاحظ اللون","حدد درجة الحرارة"],"answer":["حدد درجة الحرارة","لاحظ اللون","راجع حدود الاستنتاج"],"explanation":"الترتيب الصحيح وفق الدرس: حدد درجة الحرارة ← لاحظ اللون ← راجع حدود الاستنتاج."},{"number":5,"kind":"type","prompt":"ما اسم وحدة قياس الحرارة المطلقة في الفلك؟","target":"","answer":"كلفن","explanation":"يرتبط لون الضوء الصادر من نجم بحرارة سطحه الفعالة في تقريب الجسم الأسود: النجوم الأكثر حرارة تميل إلى الأزرق والأبيض، والأبرد تميل إلى البرتقالي والأحمر. يتأثر الطيف أيضًا بامتصاص العناصر والخصائص الفيزيائية."}]},{"index":5,"stage":{"title":"حياة النجوم حسب الكتلة","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم حياة النجوم حسب الكتلة. كتلة النجم من أهم العوامل المؤثرة في سرعة استهلاكه للوقود النووي وفي مسار تطوره. النجوم الأكبر كتلة تستهلك وقودها سريعًا عمومًا فتقصر أعمارها على التسلسل الرئيسي رغم امتلاكها وقودًا أكثر.","tips":["كتلة النجم من أهم العوامل المؤثرة في سرعة استهلاكه للوقود النووي وفي مسار تطوره. النجوم الأكبر كتلة تستهلك وقودها سريعًا عمومًا فتقصر أعمارها على التسلسل الرئيسي رغم امتلاكها وقودًا أكثر.","صيغة مدرسية تقريبية لعمر التسلسل الرئيسي هي نحو 10 مليارات سنة × (الكتلة بوحدة الكتلة الشمسية)^(-2.5)، لكنها لا تصلح على كامل نطاق الكتل أو المراحل التطورية.","لا تفسر الرقم باعتباره موعدًا حتميًا لموت النجم؛ تتغير الأعمار أيضًا بالتركيب والدوران والكتلة المفقودة. لا يساوي عمر التسلسل الرئيسي عمر جميع مراحل النجم."],"lessons":[{"title":"المبدأ الفلكي","body":"كتلة النجم من أهم العوامل المؤثرة في سرعة استهلاكه للوقود النووي وفي مسار تطوره. النجوم الأكبر كتلة تستهلك وقودها سريعًا عمومًا فتقصر أعمارها على التسلسل الرئيسي رغم امتلاكها وقودًا أكثر. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"يقصر","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"صيغة مدرسية تقريبية لعمر التسلسل الرئيسي هي نحو 10 مليارات سنة × (الكتلة بوحدة الكتلة الشمسية)^(-2.5)، لكنها لا تصلح على كامل نطاق الكتل أو المراحل التطورية. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد الكتلة ← قدر العمر التقريبي ← حدد حدود النموذج","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"تستهلك النجوم الأعلى كتلة وقودها بوتيرة أسرع. تستعمل كتلة الشمس مرجعًا لوصف كتل النجوم. علاقة الكتلة والعمر تقريبية وتعتمد على نطاق النماذج. تلعب الكتلة الابتدائية دورًا محوريًا في دورة حياة النجم. لا تفسر الرقم باعتباره موعدًا حتميًا لموت النجم؛ تتغير الأعمار أيضًا بالتركيب والدوران والكتلة المفقودة. لا يساوي عمر التسلسل الرئيسي عمر جميع مراحل النجم. خطوات الحل: حدد الكتلة ← قدر العمر التقريبي ← حدد حدود النموذج. المصطلح الذي تعلمته: الكتلة.","example":"الكتلة","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-stars","scenario":"حياة النجوم حسب الكتلة"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/stars/"}},"questions":[{"number":0,"kind":"choice","prompt":"ماذا يحدث عادة لعمر النجم الرئيسي عند زيادة كتلته كثيرًا؟","target":"","options":["يبقى ثابتًا","يتوقف الاندماج فورًا","يقصر","يطول دائمًا"],"answerIndex":2,"explanation":"تستهلك النجوم الأعلى كتلة وقودها بوتيرة أسرع."},{"number":1,"kind":"choice","prompt":"ما الوحدة المستخدمة لمقارنة كتلة النجوم؟","target":"","options":["درجة الحرارة","الكتلة الشمسية","وحدة الضغط","السنة الضوئية"],"answerIndex":1,"explanation":"تستعمل كتلة الشمس مرجعًا لوصف كتل النجوم."},{"number":2,"kind":"choice","prompt":"هل العمر التقريبي في المختبر موعد دقيق لنهاية النجم؟","target":"","options":["لا","نعم","إذا كان لونه أزرق","إذا كان قزمًا"],"answerIndex":0,"explanation":"علاقة الكتلة والعمر تقريبية وتعتمد على نطاق النماذج."},{"number":3,"kind":"choice","prompt":"ما العامل الأساسي في مسار تطور النجم؟","target":"","options":["اسم الكوكبة فقط","مسافة الأرض عنه فقط","حجمه المرئي من الأرض","الكتلة"],"answerIndex":3,"explanation":"تلعب الكتلة الابتدائية دورًا محوريًا في دورة حياة النجم."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «حياة النجوم حسب الكتلة».","target":"","tokens":["حدد حدود النموذج","قدر العمر التقريبي","حدد الكتلة"],"answer":["حدد الكتلة","قدر العمر التقريبي","حدد حدود النموذج"],"explanation":"الترتيب الصحيح وفق الدرس: حدد الكتلة ← قدر العمر التقريبي ← حدد حدود النموذج."},{"number":5,"kind":"type","prompt":"ما المتغير الأهم الذي نغيّره لتجربة عمر النجم؟","target":"","answer":"الكتلة","explanation":"كتلة النجم من أهم العوامل المؤثرة في سرعة استهلاكه للوقود النووي وفي مسار تطوره. النجوم الأكبر كتلة تستهلك وقودها سريعًا عمومًا فتقصر أعمارها على التسلسل الرئيسي رغم امتلاكها وقودًا أكثر."}]},{"index":6,"stage":{"title":"موت النجوم وبقاياها","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم موت النجوم وبقاياها. النجم الشبيه بالشمس يمر بمراحل تؤدي عادة إلى قزم أبيض بعد فقدان طبقاته الخارجية. أما كثير من النجوم الضخمة فقد تنتهي بانهيار اللب وتترك نجومًا نيوترونية أو ثقوبًا سوداء وفق كتلة اللب والظروف.","tips":["النجم الشبيه بالشمس يمر بمراحل تؤدي عادة إلى قزم أبيض بعد فقدان طبقاته الخارجية. أما كثير من النجوم الضخمة فقد تنتهي بانهيار اللب وتترك نجومًا نيوترونية أو ثقوبًا سوداء وفق كتلة اللب والظروف.","إذا اخترت كتلة ابتدائية من رتبة كتلة الشمس، يظهر مسار تعليمي نحو قزم أبيض. وإذا رفعتها إلى عشرات الكتل الشمسية، يوضح النموذج احتمال نهاية بانهيار لب لا ضمانًا لنوع بقايا واحد.","لا تستنتج مصير النجم من حد كتلة أولية واحد على نحو صارم؛ فقد تغير الرياح النجمية والثنائية والتركيب الكتلة النهائية ومسار الانهيار."],"lessons":[{"title":"المبدأ الفلكي","body":"النجم الشبيه بالشمس يمر بمراحل تؤدي عادة إلى قزم أبيض بعد فقدان طبقاته الخارجية. أما كثير من النجوم الضخمة فقد تنتهي بانهيار اللب وتترك نجومًا نيوترونية أو ثقوبًا سوداء وفق كتلة اللب والظروف. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"قزم أبيض","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"إذا اخترت كتلة ابتدائية من رتبة كتلة الشمس، يظهر مسار تعليمي نحو قزم أبيض. وإذا رفعتها إلى عشرات الكتل الشمسية، يوضح النموذج احتمال نهاية بانهيار لب لا ضمانًا لنوع بقايا واحد. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"افحص الكتلة ← اتبع المسار التطوري ← قارن البقايا","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"تنتهي نجوم كثيرة شبيهة بالشمس إلى أقزام بيضاء. قد ينتج نجم نيوتروني أو ثقب أسود عن انهيار اللب في بعض النجوم الضخمة. كثير من النجوم الأقل كتلة لا تمر بانفجار انهيار لب. تؤثر خسارة الكتلة والتفاعل الثنائي وعوامل أخرى في البقايا. لا تستنتج مصير النجم من حد كتلة أولية واحد على نحو صارم؛ فقد تغير الرياح النجمية والثنائية والتركيب الكتلة النهائية ومسار الانهيار. خطوات الحل: افحص الكتلة ← اتبع المسار التطوري ← قارن البقايا. المصطلح الذي تعلمته: قزم أبيض.","example":"قزم أبيض","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-stars","scenario":"موت النجوم وبقاياها"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/stars/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما البقايا الشائعة لنجم شبيه بالشمس؟","target":"","options":["مذنب","قزم أبيض","ثقب أسود حتمًا","نجم نيوتروني دائمًا"],"answerIndex":1,"explanation":"تنتهي نجوم كثيرة شبيهة بالشمس إلى أقزام بيضاء."},{"number":1,"kind":"choice","prompt":"ما إحدى بقايا انهيار لب نجم ضخم؟","target":"","options":["نجم نيوتروني","كوكب صخري","قمر جليدي","سحابة مطر"],"answerIndex":0,"explanation":"قد ينتج نجم نيوتروني أو ثقب أسود عن انهيار اللب في بعض النجوم الضخمة."},{"number":2,"kind":"choice","prompt":"هل جميع النجوم تنفجر كمستعرات عظمى؟","target":"","options":["نعم","إذا كانت حمراء","إذا كانت قريبة من الأرض","لا"],"answerIndex":3,"explanation":"كثير من النجوم الأقل كتلة لا تمر بانفجار انهيار لب."},{"number":3,"kind":"choice","prompt":"هل كتلة الولادة وحدها تحسم البقايا في كل الحالات؟","target":"","options":["في مجرتنا فقط","إذا كان اللون أزرق","لا","نعم"],"answerIndex":2,"explanation":"تؤثر خسارة الكتلة والتفاعل الثنائي وعوامل أخرى في البقايا."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «موت النجوم وبقاياها».","target":"","tokens":["قارن البقايا","اتبع المسار التطوري","افحص الكتلة"],"answer":["افحص الكتلة","اتبع المسار التطوري","قارن البقايا"],"explanation":"الترتيب الصحيح وفق الدرس: افحص الكتلة ← اتبع المسار التطوري ← قارن البقايا."},{"number":5,"kind":"type","prompt":"ما اسم البقايا الكثيفة الشائعة لنجم شبيه بالشمس؟","target":"","answer":"قزم أبيض","explanation":"النجم الشبيه بالشمس يمر بمراحل تؤدي عادة إلى قزم أبيض بعد فقدان طبقاته الخارجية. أما كثير من النجوم الضخمة فقد تنتهي بانهيار اللب وتترك نجومًا نيوترونية أو ثقوبًا سوداء وفق كتلة اللب والظروف."}]},{"index":7,"stage":{"title":"الثقوب السوداء","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم الثقوب السوداء. الثقب الأسود منطقة لا تستطيع الإشارات الضوئية من داخل أفق حدثها الوصول إلى الخارج. قد تتكون الثقوب السوداء النجمية من انهيار نجوم ضخمة، وتوجد أيضًا ثقوب سوداء هائلة الكتلة في مراكز مجرات.","tips":["الثقب الأسود منطقة لا تستطيع الإشارات الضوئية من داخل أفق حدثها الوصول إلى الخارج. قد تتكون الثقوب السوداء النجمية من انهيار نجوم ضخمة، وتوجد أيضًا ثقوب سوداء هائلة الكتلة في مراكز مجرات.","إذا انهار لب نجم ضخم بما فيه الكفاية بعد فقدان دعم الضغط، فقد ينشأ ثقب أسود. لا نرى «ثقبًا مظلمًا» مباشرة بسهولة، بل نستدل من الغاز الساخن والحركة والثقل الجذبي وآثار أخرى.","لا يعرض المختبر مسارات الضوء في الزمكان بدقة نسبية عامة؛ يشرح أثر الكتلة على المسار التطوري. والثقب الأسود ليس مكنسة تسحب كل شيء مهما كانت المسافة."],"lessons":[{"title":"المبدأ الفلكي","body":"الثقب الأسود منطقة لا تستطيع الإشارات الضوئية من داخل أفق حدثها الوصول إلى الخارج. قد تتكون الثقوب السوداء النجمية من انهيار نجوم ضخمة، وتوجد أيضًا ثقوب سوداء هائلة الكتلة في مراكز مجرات. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"حد لا تصل من داخله إشارات ضوئية إلى الخارج","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"إذا انهار لب نجم ضخم بما فيه الكفاية بعد فقدان دعم الضغط، فقد ينشأ ثقب أسود. لا نرى «ثقبًا مظلمًا» مباشرة بسهولة، بل نستدل من الغاز الساخن والحركة والثقل الجذبي وآثار أخرى. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد مجال الجاذبية ← افحص الأدلة غير المباشرة ← فرق بين الأفق والمحيط","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"يمثل أفق الحدث حد عدم القدرة على إرسال إشارة ضوئية للخارج في وصف الثقب الأسود. تُستخدم آثار الجاذبية والغاز المتساقط لرصد الثقوب السوداء. تؤثر جاذبيته كما تؤثر كتلة مساوية على مسافات كبيرة. تشير المشاهدات إلى ثقوب سوداء هائلة الكتلة في مراكز مجرات عديدة. لا يعرض المختبر مسارات الضوء في الزمكان بدقة نسبية عامة؛ يشرح أثر الكتلة على المسار التطوري. والثقب الأسود ليس مكنسة تسحب كل شيء مهما كانت المسافة. خطوات الحل: حدد مجال الجاذبية ← افحص الأدلة غير المباشرة ← فرق بين الأفق والمحيط. المصطلح الذي تعلمته: أفق الحدث.","example":"أفق الحدث","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-blackhole","scenario":"الثقوب السوداء"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/black-holes/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما أفق الحدث؟","target":"","options":["حد لا تصل من داخله إشارات ضوئية إلى الخارج","سطح صخري","حافة مجرة","طرف الغلاف الجوي"],"answerIndex":0,"explanation":"يمثل أفق الحدث حد عدم القدرة على إرسال إشارة ضوئية للخارج في وصف الثقب الأسود."},{"number":1,"kind":"choice","prompt":"كيف يمكن الاستدلال على ثقب أسود؟","target":"","options":["من لون السماء وحده","من صوت مباشر في الفراغ","من شكل غيمة أرضية","من حركة الأجرام والغاز والإشعاع المحيط"],"answerIndex":3,"explanation":"تُستخدم آثار الجاذبية والغاز المتساقط لرصد الثقوب السوداء."},{"number":2,"kind":"choice","prompt":"هل كل الثقب الأسود يبتلع الأجسام البعيدة دون اعتبار المسافة؟","target":"","options":["فقط أثناء الليل","إذا كان في درب التبانة","لا","نعم"],"answerIndex":2,"explanation":"تؤثر جاذبيته كما تؤثر كتلة مساوية على مسافات كبيرة."},{"number":3,"kind":"choice","prompt":"أين توجد ثقوب سوداء فائقة الكتلة؟","target":"","options":["في حلقات زحل فقط","في مراكز مجرات كثيرة","داخل كل نواة ذرية","في السحب الأرضية"],"answerIndex":1,"explanation":"تشير المشاهدات إلى ثقوب سوداء هائلة الكتلة في مراكز مجرات عديدة."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «الثقوب السوداء».","target":"","tokens":["فرق بين الأفق والمحيط","افحص الأدلة غير المباشرة","حدد مجال الجاذبية"],"answer":["حدد مجال الجاذبية","افحص الأدلة غير المباشرة","فرق بين الأفق والمحيط"],"explanation":"الترتيب الصحيح وفق الدرس: حدد مجال الجاذبية ← افحص الأدلة غير المباشرة ← فرق بين الأفق والمحيط."},{"number":5,"kind":"type","prompt":"ما اسم الحد الحاسم المحيط بالثقب الأسود؟","target":"","answer":"أفق الحدث","explanation":"الثقب الأسود منطقة لا تستطيع الإشارات الضوئية من داخل أفق حدثها الوصول إلى الخارج. قد تتكون الثقوب السوداء النجمية من انهيار نجوم ضخمة، وتوجد أيضًا ثقوب سوداء هائلة الكتلة في مراكز مجرات."}]},{"index":8,"stage":{"title":"كيف نكتشف كوكبًا خارجيًا؟","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم كيف نكتشف كوكبًا خارجيًا؟. يمكن اكتشاف كوكب خارج المجموعة الشمسية من انخفاض صغير دوري في ضوء نجمه عندما يعبر الكوكب أمام قرص النجم بالنسبة للمراقب. في النموذج المثالي تكون نسبة انخفاض السطوع تقريبًا مربع نسبة نصف قطر الكوكب إلى نصف قطر نجمه.","tips":["يمكن اكتشاف كوكب خارج المجموعة الشمسية من انخفاض صغير دوري في ضوء نجمه عندما يعبر الكوكب أمام قرص النجم بالنسبة للمراقب. في النموذج المثالي تكون نسبة انخفاض السطوع تقريبًا مربع نسبة نصف قطر الكوكب إلى نصف قطر نجمه.","إذا تضاعف نصف قطر الكوكب وبقي النجم نفسه، يصير انخفاض السطوع نحو أربعة أضعاف في النموذج الهندسي المبسط. كرر المحاكاة مع نجم أصغر ولاحظ تغير العمق.","العبور لا يحدث لكل مدار من منظور الأرض؛ يعتمد على الاصطفاف. العمق الفعلي يتأثر بتعتيم حافة النجم والبقع والتلوث الضوئي، لذا النموذج تقريبي."],"lessons":[{"title":"المبدأ الفلكي","body":"يمكن اكتشاف كوكب خارج المجموعة الشمسية من انخفاض صغير دوري في ضوء نجمه عندما يعبر الكوكب أمام قرص النجم بالنسبة للمراقب. في النموذج المثالي تكون نسبة انخفاض السطوع تقريبًا مربع نسبة نصف قطر الكوكب إلى نصف قطر نجمه. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"انخفاض دوري في ضوء النجم","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"إذا تضاعف نصف قطر الكوكب وبقي النجم نفسه، يصير انخفاض السطوع نحو أربعة أضعاف في النموذج الهندسي المبسط. كرر المحاكاة مع نجم أصغر ولاحظ تغير العمق. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد حجم الكوكب ← حدد حجم النجم ← اقرأ عمق الانخفاض","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"يحجب الكوكب جزءًا من ضوء النجم فيحدث انخفاضًا عابرًا. العمق النسبي يساوي تقريبًا مربع نسبة نصفي القطر. يتطلب العبور محاذاة مناسبة لمستوى المدار بالنسبة للراصد. تعطي الفواصل بين عبورات متكررة تقديرًا للفترة المدارية. العبور لا يحدث لكل مدار من منظور الأرض؛ يعتمد على الاصطفاف. العمق الفعلي يتأثر بتعتيم حافة النجم والبقع والتلوث الضوئي، لذا النموذج تقريبي. خطوات الحل: حدد حجم الكوكب ← حدد حجم النجم ← اقرأ عمق الانخفاض. المصطلح الذي تعلمته: العبور.","example":"العبور","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-transit","scenario":"كيف نكتشف كوكبًا خارجيًا؟"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/exoplanets/whats-a-transit/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما علامة عبور كوكب أمام نجمه؟","target":"","options":["ارتفاع مستمر في كل الأطوال","صوت رعد","اختفاء النجم دائمًا","انخفاض دوري في ضوء النجم"],"answerIndex":3,"explanation":"يحجب الكوكب جزءًا من ضوء النجم فيحدث انخفاضًا عابرًا."},{"number":1,"kind":"choice","prompt":"إذا تضاعف نصف قطر الكوكب، فكيف يتغير عمق العبور تقريبًا؟","target":"","options":["ينخفض إلى النصف","يبقى ثابتًا","يزيد أربعة أضعاف","يتضاعف فقط"],"answerIndex":2,"explanation":"العمق النسبي يساوي تقريبًا مربع نسبة نصفي القطر."},{"number":2,"kind":"choice","prompt":"هل جميع الكواكب الخارجية تظهر لها عبورات من الأرض؟","target":"","options":["إذا كان النجم أصفر","لا","نعم","إذا كانت كبيرة"],"answerIndex":1,"explanation":"يتطلب العبور محاذاة مناسبة لمستوى المدار بالنسبة للراصد."},{"number":3,"kind":"choice","prompt":"ما الذي يكشفه تكرار الانخفاضات المنتظمة؟","target":"","options":["الفترة المدارية المحتملة","لون سطح الكوكب مباشرة","عدد الجبال","نوع الصخور"],"answerIndex":0,"explanation":"تعطي الفواصل بين عبورات متكررة تقديرًا للفترة المدارية."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «كيف نكتشف كوكبًا خارجيًا؟».","target":"","tokens":["اقرأ عمق الانخفاض","حدد حجم النجم","حدد حجم الكوكب"],"answer":["حدد حجم الكوكب","حدد حجم النجم","اقرأ عمق الانخفاض"],"explanation":"الترتيب الصحيح وفق الدرس: حدد حجم الكوكب ← حدد حجم النجم ← اقرأ عمق الانخفاض."},{"number":5,"kind":"type","prompt":"ما اسم مرور كوكب أمام نجم من منظور الراصد؟","target":"","answer":"العبور","explanation":"يمكن اكتشاف كوكب خارج المجموعة الشمسية من انخفاض صغير دوري في ضوء نجمه عندما يعبر الكوكب أمام قرص النجم بالنسبة للمراقب. في النموذج المثالي تكون نسبة انخفاض السطوع تقريبًا مربع نسبة نصف قطر الكوكب إلى نصف قطر نجمه."}]},{"index":9,"stage":{"title":"تمدد الكون","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم تمدد الكون. تشير المشاهدات إلى توسع الكون على المقاييس الكبيرة، بحيث تتباعد مجرات كثيرة بعضها عن بعض في المتوسط. في مسافات قريبة نسبيًا تسمح بها الصيغة البسيطة، ترتبط سرعة التباعد بمسافة المجرة وفق قانون هابل-لومتر: v≈H₀d.","tips":["تشير المشاهدات إلى توسع الكون على المقاييس الكبيرة، بحيث تتباعد مجرات كثيرة بعضها عن بعض في المتوسط. في مسافات قريبة نسبيًا تسمح بها الصيغة البسيطة، ترتبط سرعة التباعد بمسافة المجرة وفق قانون هابل-لومتر: v≈H₀d.","إذا افترضنا H₀=70 كم/ث/ميغابارسيك ومجرة تبعد 100 ميغابارسيك، فسرعة التباعد التقريبية 7000 كم/ث في النظام البسيط. لا يعني ذلك حركة محلية عبر الفضاء بالطريقة نفسها لكل المقاييس.","قانون v=H₀d تقريب ملائم عند انزياحات حمراء صغيرة؛ عند مسافات كبيرة يلزم نموذج كوني وتفسير نسبي عام. تمدد الكون لا يفصل الأجسام المرتبطة جاذبيًا مثل الأرض والشمس."],"lessons":[{"title":"المبدأ الفلكي","body":"تشير المشاهدات إلى توسع الكون على المقاييس الكبيرة، بحيث تتباعد مجرات كثيرة بعضها عن بعض في المتوسط. في مسافات قريبة نسبيًا تسمح بها الصيغة البسيطة، ترتبط سرعة التباعد بمسافة المجرة وفق قانون هابل-لومتر: v≈H₀d. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"زيادة سرعة التباعد مع المسافة تقريبًا","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"إذا افترضنا H₀=70 كم/ث/ميغابارسيك ومجرة تبعد 100 ميغابارسيك، فسرعة التباعد التقريبية 7000 كم/ث في النظام البسيط. لا يعني ذلك حركة محلية عبر الفضاء بالطريقة نفسها لكل المقاييس. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"حدد المسافة ← اختر ثابت هابل ← احسب سرعة التباعد","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"يرتبط معدل ابتعاد المجرات بالمسافة في التقريب القريب. 70×100=7000 كيلومتر في الثانية. الأنظمة المرتبطة جاذبيًا لا تتوسع وفق قانون هابل البسيط. عند المسافات الكبيرة يتطلب التفسير نماذج كونية أوسع. قانون v=H₀d تقريب ملائم عند انزياحات حمراء صغيرة؛ عند مسافات كبيرة يلزم نموذج كوني وتفسير نسبي عام. تمدد الكون لا يفصل الأجسام المرتبطة جاذبيًا مثل الأرض والشمس. خطوات الحل: حدد المسافة ← اختر ثابت هابل ← احسب سرعة التباعد. المصطلح الذي تعلمته: هابل.","example":"هابل","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-expansion","scenario":"تمدد الكون"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما الذي يصفه قانون هابل-لومتر على المقاييس الكبيرة؟","target":"","options":["توقف ضوء النجوم","تغير حجم الأرض","زيادة سرعة التباعد مع المسافة تقريبًا","ثبات جميع المجرات"],"answerIndex":2,"explanation":"يرتبط معدل ابتعاد المجرات بالمسافة في التقريب القريب."},{"number":1,"kind":"choice","prompt":"إذا H₀=70 والمسافة 100 Mpc فما سرعة التباعد التقريبية؟","target":"","options":["7 كم/ث","7000 كم/ث","70 كم/ث","100 كم/ث"],"answerIndex":1,"explanation":"70×100=7000 كيلومتر في الثانية."},{"number":2,"kind":"choice","prompt":"هل تمدد الكون يمزق الأرض من الشمس؟","target":"","options":["لا","نعم","إذا مرت سنة","إذا كانت الشمس ساخنة"],"answerIndex":0,"explanation":"الأنظمة المرتبطة جاذبيًا لا تتوسع وفق قانون هابل البسيط."},{"number":3,"kind":"choice","prompt":"هل تصلح صيغة هابل البسيطة لجميع المسافات بلا تصحيح؟","target":"","options":["نعم","إذا كانت المجرة زرقاء","فقط مع النجوم الصغيرة","لا"],"answerIndex":3,"explanation":"عند المسافات الكبيرة يتطلب التفسير نماذج كونية أوسع."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «تمدد الكون».","target":"","tokens":["احسب سرعة التباعد","اختر ثابت هابل","حدد المسافة"],"answer":["حدد المسافة","اختر ثابت هابل","احسب سرعة التباعد"],"explanation":"الترتيب الصحيح وفق الدرس: حدد المسافة ← اختر ثابت هابل ← احسب سرعة التباعد."},{"number":5,"kind":"type","prompt":"ما اسم القانون الذي يربط السرعة بالمسافة كونيًا تقريبًا؟","target":"","answer":"هابل","explanation":"تشير المشاهدات إلى توسع الكون على المقاييس الكبيرة، بحيث تتباعد مجرات كثيرة بعضها عن بعض في المتوسط. في مسافات قريبة نسبيًا تسمح بها الصيغة البسيطة، ترتبط سرعة التباعد بمسافة المجرة وفق قانون هابل-لومتر: v≈H₀d."}]},{"index":10,"stage":{"title":"أدلة الكون المبكر","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم أدلة الكون المبكر. يشمل دعم النموذج الكوني المبكر رصد تمدد الكون وإشعاع الخلفية الكونية الميكروي ووفرة العناصر الخفيفة. الخلفية الكونية إشعاع وصلنا من وقت كان عمر الكون فيه نحو 380 ألف سنة بعد بداية التمدد الساخن.","tips":["يشمل دعم النموذج الكوني المبكر رصد تمدد الكون وإشعاع الخلفية الكونية الميكروي ووفرة العناصر الخفيفة. الخلفية الكونية إشعاع وصلنا من وقت كان عمر الكون فيه نحو 380 ألف سنة بعد بداية التمدد الساخن.","يمكن مقارنة انزياح ضوء مجرات بعيدة بمسافاتها، ثم النظر إلى الخلفية الكونية التي تبلغ حرارتها الحالية نحو 2.725 كلفن. هذه أدلة مستقلة نسبيًا تتكامل في تفسير تطور الكون.","لا تصف الانفجار العظيم بانفجار مادة من نقطة في فراغ جاهز بالمعنى اليومي؛ نموذج التمدد يتناول تطور الفضاء نفسه. المحاكاة لا تحسب الإشعاع الكوني الميكروي."],"lessons":[{"title":"المبدأ الفلكي","body":"يشمل دعم النموذج الكوني المبكر رصد تمدد الكون وإشعاع الخلفية الكونية الميكروي ووفرة العناصر الخفيفة. الخلفية الكونية إشعاع وصلنا من وقت كان عمر الكون فيه نحو 380 ألف سنة بعد بداية التمدد الساخن. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"إشعاع الخلفية الكونية الميكروي","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"يمكن مقارنة انزياح ضوء مجرات بعيدة بمسافاتها، ثم النظر إلى الخلفية الكونية التي تبلغ حرارتها الحالية نحو 2.725 كلفن. هذه أدلة مستقلة نسبيًا تتكامل في تفسير تطور الكون. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"اجمع أدلة التمدد ← افحص الخلفية الكونية ← وازن التفسير","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"إشعاع الخلفية الكونية بقايا ضوئية من مراحل الكون المبكر. تبلغ حرارة إشعاع الخلفية الكونية نحو 2.725 كلفن. تعود الخلفية الكونية إلى وقت تكوّنت فيه الذرات وتحررت الفوتونات نسبيًا. الوصف العلمي يتناول توسع الكون المبكر لا انفجارًا محليًا كالمتفجرات. لا تصف الانفجار العظيم بانفجار مادة من نقطة في فراغ جاهز بالمعنى اليومي؛ نموذج التمدد يتناول تطور الفضاء نفسه. المحاكاة لا تحسب الإشعاع الكوني الميكروي. خطوات الحل: اجمع أدلة التمدد ← افحص الخلفية الكونية ← وازن التفسير. المصطلح الذي تعلمته: الخلفية الكونية.","example":"الخلفية الكونية","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-expansion","scenario":"أدلة الكون المبكر"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/universe/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما أحد الأدلة الأساسية على تطور الكون من حالة أكثر حرارة وكثافة؟","target":"","options":["حركة الغيوم الأرضية","إشعاع الخلفية الكونية الميكروي","تغير الطقس اليومي","لون ماء البحر"],"answerIndex":1,"explanation":"إشعاع الخلفية الكونية بقايا ضوئية من مراحل الكون المبكر."},{"number":1,"kind":"choice","prompt":"ما الحرارة الحالية التقريبية للخلفية الكونية؟","target":"","options":["2.7 كلفن","300 كلفن","3000 كلفن","10000 كلفن"],"answerIndex":0,"explanation":"تبلغ حرارة إشعاع الخلفية الكونية نحو 2.725 كلفن."},{"number":2,"kind":"choice","prompt":"متى أصبح الكون شفافًا تقريبًا للفوتونات التي نرصدها في الخلفية؟","target":"","options":["بعد يوم واحد","بعد مليار سنة تمامًا","بعد مليون مليار سنة","بعد نحو 380 ألف سنة"],"answerIndex":3,"explanation":"تعود الخلفية الكونية إلى وقت تكوّنت فيه الذرات وتحررت الفوتونات نسبيًا."},{"number":3,"kind":"choice","prompt":"هل الانفجار العظيم انفجار داخل فراغ مسبق فقط؟","target":"","options":["في مركز درب التبانة","داخل الشمس","لا، النموذج يصف تمدد الفضاء","نعم دائمًا"],"answerIndex":2,"explanation":"الوصف العلمي يتناول توسع الكون المبكر لا انفجارًا محليًا كالمتفجرات."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «أدلة الكون المبكر».","target":"","tokens":["وازن التفسير","افحص الخلفية الكونية","اجمع أدلة التمدد"],"answer":["اجمع أدلة التمدد","افحص الخلفية الكونية","وازن التفسير"],"explanation":"الترتيب الصحيح وفق الدرس: اجمع أدلة التمدد ← افحص الخلفية الكونية ← وازن التفسير."},{"number":5,"kind":"type","prompt":"ما اسم إشعاع البقايا من الكون المبكر؟","target":"","answer":"الخلفية الكونية","explanation":"يشمل دعم النموذج الكوني المبكر رصد تمدد الكون وإشعاع الخلفية الكونية الميكروي ووفرة العناصر الخفيفة. الخلفية الكونية إشعاع وصلنا من وقت كان عمر الكون فيه نحو 380 ألف سنة بعد بداية التمدد الساخن."}]},{"index":11,"stage":{"title":"مهمة المرصد الفضائي","subtitle":"اكتشف الأدلة الفلكية ثم اختبرها","intro":"في هذه المحطة نتعلم مهمة المرصد الفضائي. يعتمد التحقيق الفلكي على بيانات ملاحظة قابلة للتحليل، لا على صورة جميلة فقط. يستطيع الطالب فحص منحنى ضوء نجم ثم تقدير هل يظهر انخفاض دوري متكرر قبل طرح احتمال وجود كوكب عابر.","tips":["يعتمد التحقيق الفلكي على بيانات ملاحظة قابلة للتحليل، لا على صورة جميلة فقط. يستطيع الطالب فحص منحنى ضوء نجم ثم تقدير هل يظهر انخفاض دوري متكرر قبل طرح احتمال وجود كوكب عابر.","اختر نصف قطر كوكب ونصف قطر نجمه، ثم لاحظ عمق انخفاض الضوء في رسم اصطناعي. قارن بين عدة أحجام وتذكر أن آثار البقع النجمية أو أنظمة ثنائية قد تشبه بعض إشارات العبور.","النموذج يصنع منحنى ضوء مثاليًا دون ضجيج رصدي حقيقي، لذلك لا يؤكد اكتشاف كوكب بعينه. الاكتشافات تحتاج رصدًا متكررًا وتحليلًا مستقلًا واستبعاد تفسيرات أخرى."],"lessons":[{"title":"المبدأ الفلكي","body":"يعتمد التحقيق الفلكي على بيانات ملاحظة قابلة للتحليل، لا على صورة جميلة فقط. يستطيع الطالب فحص منحنى ضوء نجم ثم تقدير هل يظهر انخفاض دوري متكرر قبل طرح احتمال وجود كوكب عابر. نعتمد على الضوء والقياسات لبناء تفسير للظاهرة بدلاً من افتراض أن المظهر وحده يكفي.","example":"فحص نمط الانخفاض وتكراره","note":"تعرّف على معنى الكميات والمسافات قبل بدء أي حساب."},{"title":"مثال فلكي محلول","body":"اختر نصف قطر كوكب ونصف قطر نجمه، ثم لاحظ عمق انخفاض الضوء في رسم اصطناعي. قارن بين عدة أحجام وتذكر أن آثار البقع النجمية أو أنظمة ثنائية قد تشبه بعض إشارات العبور. جرّب تغيير متغير واحد في المختبر وفسّر لماذا تتبدل النتيجة وفق العلاقة المدروسة.","example":"افحص بيانات الضوء ← كرر القياسات ← استبعد التفسيرات البديلة","note":"اتبع المثال وتأكد من اتجاه العلاقة قبل الانتقال إلى الاختبار."},{"title":"الأدلة والحدود المهمة","body":"يجب فحص الإشارة وتكرارها قبل تفسيرها بعبور كوكب. قد تسبب النجوم الثنائية والبقع والضجيج إشارات مضللة. عمق العبور يتعلق بنسبة مربعي نصفي القطر. يتطلب التأكيد رصدًا وتحليلًا إضافيًا وليس رسمًا تعليميًا. النموذج يصنع منحنى ضوء مثاليًا دون ضجيج رصدي حقيقي، لذلك لا يؤكد اكتشاف كوكب بعينه. الاكتشافات تحتاج رصدًا متكررًا وتحليلًا مستقلًا واستبعاد تفسيرات أخرى. خطوات الحل: افحص بيانات الضوء ← كرر القياسات ← استبعد التفسيرات البديلة. المصطلح الذي تعلمته: المنحنى الضوئي.","example":"المنحنى الضوئي","note":"الأمثلة الكونية مبسطة ولا تُعد بيانات مرصد حقيقية أو تنبؤات قطعية."}],"lab":{"kind":"science","model":"cosmos-transit","scenario":"مهمة المرصد الفضائي"},"source":{"title":"NASA Science — علم الفلك والكون","url":"https://science.nasa.gov/exoplanets/whats-a-transit/"}},"questions":[{"number":0,"kind":"choice","prompt":"ما أول خطوة عند تحليل منحنى ضوء محتمل؟","target":"","options":["فحص نمط الانخفاض وتكراره","إعلان كوكب فورًا","حذف كل البيانات","اختيار لون الكوكب"],"answerIndex":0,"explanation":"يجب فحص الإشارة وتكرارها قبل تفسيرها بعبور كوكب."},{"number":1,"kind":"choice","prompt":"هل يمكن أن تقلد ظواهر أخرى إشارة العبور؟","target":"","options":["لا","إذا كان الكوكب كبيرًا","إذا كان النجم صغيرًا","نعم"],"answerIndex":3,"explanation":"قد تسبب النجوم الثنائية والبقع والضجيج إشارات مضللة."},{"number":2,"kind":"choice","prompt":"ماذا تقارن المحاكاة الاصطناعية؟","target":"","options":["التنبؤ بالمطر","قوة الصخور","نصف قطر الكوكب والنجم وانخفاض الضوء","سرعة الصوت"],"answerIndex":2,"explanation":"عمق العبور يتعلق بنسبة مربعي نصفي القطر."},{"number":3,"kind":"choice","prompt":"هل يكفي رسم اصطناعي واحد لتأكيد كوكب حقيقي؟","target":"","options":["إذا كان الاسم معروفًا","لا","نعم","إذا كان المنحنى ناعمًا"],"answerIndex":1,"explanation":"يتطلب التأكيد رصدًا وتحليلًا إضافيًا وليس رسمًا تعليميًا."},{"number":4,"kind":"order","prompt":"رتب خطوات دراسة «مهمة المرصد الفضائي».","target":"","tokens":["استبعد التفسيرات البديلة","كرر القياسات","افحص بيانات الضوء"],"answer":["افحص بيانات الضوء","كرر القياسات","استبعد التفسيرات البديلة"],"explanation":"الترتيب الصحيح وفق الدرس: افحص بيانات الضوء ← كرر القياسات ← استبعد التفسيرات البديلة."},{"number":5,"kind":"type","prompt":"ما اسم منحنى سطوع النجم عبر الزمن؟","target":"","answer":"المنحنى الضوئي","explanation":"يعتمد التحقيق الفلكي على بيانات ملاحظة قابلة للتحليل، لا على صورة جميلة فقط. يستطيع الطالب فحص منحنى ضوء نجم ثم تقدير هل يظهر انخفاض دوري متكرر قبل طرح احتمال وجود كوكب عابر."}]}]}]$school967_nature$::jsonb);

insert into public.school_editor_courses(slug,draft,published,version,published_version,updated_by)
select c.item->>'slug',c.item->'course',c.item->'course',1,1,null
from pg_temp.school967_nature_seed t
